window.__D("text/igrot-rebbe/c064",{"p":[[1200970182,"ח'תתנז\n\n<p>ב\"ה, י\"ב-י\"ג תמוז ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>ובעמדנו בימי הגאולה, י\"ב-י\"ג תמוז, גאולת כ\"ק מו\"ח אדמו\"ר נשיא ישראל, שהוא גם גאולתנו ופדות נפשנו.</p>\n<p>יהי רצון שיגאל כאו\"א מטרדות הרבות ומחשבונות הרבים וה' יהי' חלקו ונחלתו, וכידוע פס\"ד הרמב\"ם אשר לא בכהן ולוי בלבד הדברים אמורים, \"אלא כל איש ואיש מכל באי העולם אשר נדבה רוחו אותו והבינו מדעו להבדל לעמוד לפני ה' לשרתו ולעבדו לדעת את ה' והלך ישר כמו שעשהו האלקים ופרק מעל צוארו עול החשבונות הרבים אשר בקשו בני האדם ה\"ז נתקדש קדש קדשים ויהי' הוי' חלקו ונחלתו לעולם ולעולמי עולמים ויזכה לו בעוה\"ז דבר המספיק לו כמו שזכה לכהנים וללוויים הרי דוד ע\"ה אומר ה' מנת חלקי וכוסי אתה תומיך גורלי\".</p>\n<p>ויהי רצון שיוסיף בהתמדה ושקידה בלימוד נגלה וחסידות ויהי' זה מתוך בריאות הנפש והגוף.</p>\n<p>בברכה לבשו\"ט בכלל ובפרט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתנז</b></i></h4>\n<p>כללי פרטי. וראה לעיל אגרת ח'תתמו, ובהנסמן בהערות שם.</p>\n<p><b>כל איש ואיש: </b>ולא \"כל איש\" - כי כל אחד נשאר בסוגו הקודם גם לאחר שנדבה רוחו כו' (ראה מג\"א א, ח ובתרגום ומחז\"ל שם. תו\"א לז, ג עה\"פ תהלים פז, ה). ובנדו\"ד י\"ל שבכלל ב' סוגים הם אלה שתורתם אומנתם והשאר (ראה ברכות לה, ב. תו\"א ר\"פ תרומה).</p>\n<p><b>מכל באי העולם: </b>כולל גם או\"ה - ראה ר\"ה פ\"א מ\"ב (ומכאן ראי' לגירסת הרמב\"ם במשנה שם) - כי חסידי או\"ה יש להם חלק לעוה\"ב (רמב\"ם הל' מלכים ספ\"ח).</p>\n<p><b>נדבה רוחו אותו: </b>שמות (לה, כא). ונדיבות ה\"ה מדת הלב (ראה רמב\"ן שם).</p>\n<p><b>והבינו מדעו: </b>שכל שבמוח.</p>\n<p><b>להבדל.. נתקדש קדש קדשים: </b>ע\"ד דה\"א (כג, יג) האמור בכהנים [וכה\"ג, דמתאים לשם קדה\"ק, כי רק הוא נכנס לשם. וראה חדא\"ג סוף הוריות. זח\"ג קעו, ב. ב\"ק לח, א].</p>\n<p><b>לעמוד.. לשרתו: </b>דברים י, ח.</p>\n<p><b>לשרתו ולעבדו: </b>ראה מנחות קט, ב.</p>\n<p><b>ישר.. בקשו: </b>ראה קהלת ז, כט.</p>\n<p><b>לעולם ולעולמי עולמים: </b>ל' הספרי דברים כג, ז.</p>\n<p><b>לכהנים וללוויים: </b>כן הוא ברמב\"ם דפוס רומי.</p>\n<p><b>הרי דוד: </b>אף שלא הי' משבט לוי.</p>\n<p><b>תומיך גורלי: </b>רק תומיך, כי צ\"ל מלאכה מעט (רמב\"ם הל' ת\"ת פ\"ג ה\"ט. וראה הל' ת\"ת לאדה\"ז פ\"ג ס\"ג) וכדיוק הרדב\"ז כאן. אבל קשה דא\"כ אינו \"כמו שזכה לכהנים\". ואולי מכאן ראי' להכס\"מ (בהל' ת\"ת שם) די\"ל דהרמב\"ם שולל רק את המשים על לבו כו'.</p>\n<p>ולכן יש ב' אופנים: ה' מנת חלקי, או תומיך גורלי. ואכ\"מ.</p>"],[1200970183,"ח'תתנח\n\n<p>ב\"ה, ימי הגאולה י\"ב-י\"ג תמוז, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>האברך אברהם שי'</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ\"ז סיון.</p>\n<p>ובעמדנו בימי י\"ב-י\"ג תמוז, גאולת כ\"ק מו\"ח אדמו\"ר נשיא ישראל, שהיא גם גאולתנו.</p>\n<p>שבודאי ידוע לו אודות העבודה במסירת נפש של בעל השמחה והגאולה, עבודה קדושה בהפצת התורה הנגלה והחסידות, ובאופן דמוסיף והולך.</p>\n<p>התקוה אשר ילמוד מפרשת ימים אלו לקח המתאים והמעשה עיקר - להוסיף בהתמדה ושקידה בלימוד התורה, לימוד הנגלה ולימוד החסידות, ומובן שצריך להיות - כהוראת חז\"ל - באופן שהלימוד יביא לידי מעשה, הידור בקיום המצות.</p>\n<p>בטח יודע משלשת השיעורים השוים לכל נפש בחומש תהלים ותניא ושומר עליהם, ועכ\"פ יעשה כן מכאן ולהבא.</p>\n<p>[בברכה] לבשו\"ט בכל האמור,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>ש. מ. סימפסאן</p>\n<p>מזכיר</p>\n<p>הספר ששואל אודותו - מחברו מעיד עליו <b>(וכן הוא באמת)</b> שהוא נגד רבותינו ז\"ל - הן רבותינו בנגלה והן רבותינו בפנימיות התורה.</p>\n<h4><i><b>ח'תתנח</b></i></h4>\n<p><b>והמעשה עיקר:</b> אבות פ\"א מי\"ז.</p>\n<p><b>כהוראת חז\"ל:</b> קידושין מ, ב.</p>\n<p><b>הספר:</b> חשבונות הגאולה.</p>"],[1200970184,"ח'תתנט\n\n<p>ב\"ה, ימי הגאולה י\"ב-י\"ג תמוז, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>מר אריאל שי'<br>\nהמכונה דר. ברסלע</p>\n<p>שלום וברכה!</p>\n<p>לפלא שזה כמה חדשים שלא שמעתי מכ', ורצוני לקוות שהוא סימן טוב שהכל בסדר.</p>\n<p>ובעמדנו בימי סגולה אלה, ימי גאולת כ\"ק מו\"ח אדמו\"ר ממאסרו במדינת מולדתו, אשר בודאי ידועה לכ' פרשת הימים ההם, יהי רצון אשר זכרון הימים האלה יעורר בכל אחד ואחד מאתנו התעוררות לתוספת מעשים בפועל ברוחו של בעל השמחה והגאולה, וזכותו יעמוד לכל או\"א מאתנו בתוככי כלל ישראל.</p>\n<p>בכבוד ובברכה.</p>"],[1200970185,"ח'תתס\n\n<p>ב\"ה, ימי הגאולה י\"ב-י\"ג תמוז, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>אגודת נשי ובנות חב\"ד סניף:<br>\nה' עליהן תחיינה</p>\n<p>ברכה ושלום!</p>\n<p>בעמדנו בימי הגאולה, גאולת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, שהיא גם גאולתנו ופדות נפשנו,</p>\n<p>אשר בודאי ידוע להן התענינותו בתקנת נשי ובנות ישראל ועניניהן.</p>\n<p>- וכפי שאמר וגם כתב כמה וכמה פעמים (וזו גם היתה מהסיבות הראשונות לפרסומו כמה משיחותיו הק' באידיש, בלשון המדוברת באותן המדינות בם הי' בימים ההם) -</p>\n<p>תקנה אמיתית, ז.א. עד שתפעול בהנהגה היום-יומית, שתהא מתאימה בכל להוראות תורתנו תורת חיים ומצוותי' עליהן נאמר וחי בהם.</p>\n<p>וגם פעולות אלו עשה במסירה ונתינה ועד למסירת נפש, וכידוע ומפורסם.</p>\n<p>וכיון אשר הוראות צדיקים ומעשיהם קיימים ופועלים פעולתם גם לאחרי זמן אפילו לאחרי זמן רב.</p>\n<p>התקוה אשר תלמד כל אחת ואחת מהן, בתוככי כללות נשי ובנות ישראל, ה' עליהן תחיינה, לקח פרשת ימי גאולה אלה ונקודתם.</p>\n<p>אשר כל איש ואשה הרוצים באמת לקיים התורה ומצותי' - אפשריות מלאה ויכולת ניתנה להם <b>למלאות</b> רצונם זה במילואו.</p>\n<p>ויהי רצון שיהי' כל האמור מתוך בריאות הנכונה שמחה וטוב לבב, וזכות כל זה גם יעמוד להן לראות פרי טוב בעמלן, עמל קודש זה.</p>\n<p>בברכה לבשו\"ט בכהנ\"ל,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתס</b></i></h4>\n<p><b>וזו.. באידיש:</b> ראה גם לעיל ח\"י אגרת ג'רמג.</p>"],[1200970186,"ח'תתסא\n\n<p>ב\"ה, ימי הגאולה, תמוז ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>ל\"גן ישראל\"<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>תהא פתיחת \"גן ישראל\" וכל משך שהותם בו בהצלחה רבה בכל הענינים ובפרט בבריאות הגוף והנפש - על ידי התחזקות והוספה בתורה ומצות והרי בזה גם מקרבים וממהרים קיום היעוד שבפרשתנו וקם שבט מישראל, זה מלך המשיח, וישראל עושה חיל.</p>\n<p>בברכת הצלחה.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתסא</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 410.</p>\n<p><b>בשיחתו הידועה:</b> ראה גם לעיל חי\"ח אגרת ו'תשעא, ובהנסמן בהערות שם.</p>\n<p><b>הגוף והנפש: </b>שברוחניות הם מצות (אברים, גרמוהי) ותורה (דם - <b>הוא הנפש</b> - חיוהי) ראה תניא פכ\"ג (ובהגהות הצ\"צ לשם). לקו\"ת במדבר יג, א.</p>\n<p><b>התחזקות והוספה: </b>ובפרט בתקופתנו שכביאור כ\"ק מו\"ח אדמו\"ר בשיחתו הידועה היא בדוגמת המטפס על הר משופע ביותר שאפשר או עלי' או כו'.</p>\n<p><b>בתורה ומצות: </b>ענין של גאולה (תניא רפמ\"ז).</p>\n<p><b>זה מלך המשיח: </b>רמב\"ם הל' מלכים רפי\"א.</p>\n<p><b>וישראל עושה חיל: </b>ראה זהר סוף פרשת שבוע זה.</p>"],[1200970187,"ח'תתסב\n\n<p>ב\"ה, י\"ט תמוז, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד הוו\"ח אי\"א נו\"מ בחור מעם ומורם<br>\nמעם ודורש טוב<br>\nלעמו בעל מדות תרומיות ענף עץ אבות<br>\nמו\"ה שניאור זלמן<br>\nשליט\"א</p>\n<p>שלום וברכה!</p>\n<p>קבלתי ידיעה כללית ממר דובער שי' מינדל על ידי אחיו מזכירי מר ניסן שי' בנוגע השתדלותם להוציא בני משפחתם שי' ממדינתינו לפנים, ואשר פנה לכ' לעזור בזה באופן אישי.</p>\n<p>ואף שבודאי לא נצרך כ' לזירוז בענין של אהבת ישראל ועשית טובה בכלל, ועל אחת כמה וכמה בענין כזה להוציא אסירים בכושרות, שכל המדינה ההיא ה\"ה בית אסורים גדול (ה' ירחם), אבל בהכירי את בני המשפחה אביע בזה גודל קורת רוחי שמשתתף בפעולה של פדיון שבויים האמורה. ויהי רצון שגם בפעולה זו יקויים מה שנאמר וברכך ה\"א בכל אשר תעשה.</p>\n<p>בהוקרה בכבוד ובברכה.</p>\n<p>כיון שצא\"ח דכאן הוציאו לאור כרך ד' של לקוטי שיחות, ביקשתים לשלחו לכ' ובטח נתקבל כבר.</p>\n<p><i>ח'תתסב</i></p>\n<p><b>מו\"ה שניאור זלמן:</b> שזר. אגרות נוספות אליו - לעיל ח'תרפב, ובהנסמן בהערות שם.</p>"],[1200970188,"ח'תתסג\n\n<p>ב\"ה, כ\"ו תמוז ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיום כ\"א תמוז.</p>\n<p>ובבואנו מימי הגאולה י\"ב-י\"ג תמוז גאולת כ\"ק מו\"ח אדמו\"ר נשיא ישראל שהיא גם גאולתנו.</p>\n<p>שבודאי ידוע לו אודות העבודה במסירת נפש של בעל השמחה והגאולה עבודה קדושה בהפצת התורה הנגלה והחסידות ובאופן דמוסיף והולך.</p>\n<p>התקוה אשר ילמוד מפרשת ימים אלו לקח המתאים והמעשה עיקר - להוסיף בהתמדה ושקידה בלימוד התורה לימוד הנגלה ולימוד החסידות ומובן שצריך להיות - כהוראת חז\"ל - באופן שהלימוד יביא לידי מעשה הידור בקיום המצות והובטחנו הבא לטהר מסייעין לו.</p>\n<p>בטח יודע משלשת השיעורים השוים לכל נפש בחומש תהלים ותניא ושומר עליהם ועכ\"פ יעשה כן מכאן ולהבא.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א,</p>\n<p>מזכיר</p>\n<h4><i><b>ח'תתסג</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 374 והושלמה עפ\"י העתקה..</p>\n<p><b>והמעשה עיקר:</b> אבות פ\"א מי\"ז.</p>\n<p><b>כהוראת חז\"ל:</b> קידושין מ, ב.</p>\n<p><b>והובטחנו:</b> יומא לח, ב.</p>"],[1200970189,"ח'תתסד\n\n<p>ב\"ה, ער\"ח מנחם אב, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הרה\"ג והרה\"ח וו\"ח אי\"א נו\"מ בעל מדות<br>\nרב פעלים איש<br>\nהמעלה בנש\"ק וכו' מוה\"ר יצחק מאיר<br>\nשליט\"א הכהן</p>\n<p>שלום וברכה!</p>\n<p>במענה להזמנת כת\"ר \"לכנסי' הגדולה החמישית\" העתידה להתקיים בחודש מנחם אב הבע\"ל בירושלים עיה\"ק ת\"ו ע\"י משיח צדקנו בב\"א.</p>\n<p>הנני בזה להביע ברכתי לכת\"ר ולכל המשתתפים בכנסי', ה' עליהם יחיו. ויהי רצון שיקויים בקרוב היעוד, המבוקש והמקווה והמובטח - אשר כל הברואים ייעשו כולם אגודה אחת לעשות רצונך בלבב שלם.</p>\n<p>ואת\"ל הרי בסגנון ובנוסח האמור - כלולה תכנית שלמה לכל כינוס לשם שמים, בכל עת ובכל מקום, ומכל שכן כינוס אחב\"י החרדים לדבר ה' ולתורתו ומצוותיו, בתקופתנו זו, ובארצנו הק' ועיה\"ק - ת\"ו:</p>\n<p>(א) וייעשו כולם אגודה אחת - שהעשות כל בנ\"י אגודה אחת באמת, תיתכן רק על ידי קיום מצות ואהבת לרעך כמוך לכל נפש מישראל למגדול ועד קטן, שכל נפשות בני ישראל מתאימות ואב אחד לכולנה, רק שהגופים מחולקים; והרי הנפש היא העיקר והגוף אינו אלא טפל (כמבואר כ\"ז בספר התניא פרק לב).</p>\n<p>(ב) לעשות רצונך - זאת אומרת, שמטרת התאגדות זו וההתאחדות של בני ישראל היא אך ורק לעשות רצון אבינו שבשמים.</p>\n<p>(ג) בלבב שלם - היינו שאופן העשי', ההחלטות והפעולות צריך להיות בכל לב ונפש, בלי היסוס, כ\"א ברור ובהחלט.</p>\n<p>ושלימות בכל שלשת השלבים: מחשבה דיבור ומעשה, התחל מהתבוננות מעמיקה שתגלה דעת תורתנו הנצחית והוראותי' ברורות בכל בעיות דורנו הנבוך, השמעת קול ברמה, הקול קול יעקב \"בהגיון תורה\" ודעתה האמור, ועד לסוף מעשה ומעשה עיקר - בתוצאות מעשיות להחדרת התורה והמצוות בחיי היום יום בכל ענפי החיים לכל פרטיהם ופרטי פרטיהם.</p>\n<p>ואם בכל עידן ועידן הדברים אמורים, על אחת כמה וכמה בימינו אלה שהוא צו השעה וצורך השעה, הן מצד המצב - הדורש התאמצות יתרה והן מצד כושר השעה שלב בני ובנות ישראל ער הוא בפרט בתקופתנו זו רבת המאורעות והזעזועים והאכזבות, שעוררו בכמה חוגים ובפרט בחוגי הנוער, צמאון עז לדבר אמת ויציב.</p>\n<p>ואין אמת אלא תורת אמת ומצוותי' שניתנו מה' אלקים אמת, תורה ומצוות בלי פשרות ובלי וותרניות, שאז לא רק שאמת מארץ תצמח ומתקבלת - אלא שגם משמים נשקף ונמשכת סייעתא מיוחדת להצלחה רבה.</p>\n<p>בכבוד ובהוקרה ובברכה להצלחה ולבשורות טובות.</p>\n<p>ענותו תרבני לחוו\"ד מה הן הבעיות העקריות העומדות עתה על הפרק ואשר להן דין קדימה בסדר היום של הכנסי' -</p>\n<p>ותקצר היריעה מהכיל ואמנה רק אחת אחת מה שנראה לפענ\"ד:</p>\n<p><b>בשטח הכללי ועיוני:</b></p>\n<p>הצהרה ברורה אשר בכל מקום ובכל זמן <b>אך</b> התורה היא חיינו - של היחיד של הצבור ושל הכלל.</p>\n<p>ולהיותה תורת אחת ותורת אמת הנתונה מה' אחד ה' אלקינו אמת - אין מקום לשיתוף התורה עם עוד דבר מה - איזה שיהי', ושוללת היא את כל הפשרות.</p>\n<p>ואדרבא, אלו שהשלו את עצמם ואת אחרים אשר בירידת הדור - הדרך לקירוב הלבבות ליהדות ומצותי' היא ע\"י פשרות - באה המציאות המרה וטפחה על פניהם בראותם כי מפשרה בכלל ולמחצה נתדרדרו לשליש וכו' ועד - להשטה דכלל הגוים בית ישראל וממנה - לכריעה וביטול לפני כל גוי קטן וממנה - לטמיעה ר\"ל, בין העכו\"ם.</p>\n<p>ומכבר הזהירו חכמינו ז\"ל שבאם \"בקעה מצא\" - העצה היעוצה היא \"לגדור בה גדר\".</p>\n<p><b>באה\"ק בפרט:</b></p>\n<p>קשר מעשי - ומתמיד - עם הנוער שלאחרי הגיל דחינוך חובה ע\"פ החוק, אשר רובו אינו נמצא לע\"ע במסגרת בי\"ס, ועזובים לנפשם ולהשפעת הרחוב - כמובן, קשר ע\"מ להחדירו רוח של יר\"ש, אהבת התורה וחיבת המצות ועד לקיומן בחיי יום יום.</p>\n<p><b>בתפוצות ושהזמן גרמא במיוחד:</b></p>\n<p>יהדות דרום אמריקא (וכיו\"ב) המשוועת לעזר במצבם הרוחני. וכמובן, עזר לא ע\"י אנחות, כ\"א ע\"י שליחות לשם - כאו\"א למשך זמן מתאים - של מחנכים יר\"ש, מדריכים ומורי דרך (המלך מלכו של עולם) ראוים לשמם וכו' וכו' שיישבו עמהם ובתוכם ויעודדו אותם ויחזקו רוחם רוח ישראל סבא. וילמדו אותם - ואת דור הצעיר ביחוד - אורח חיים, בחיי יום יום, ע\"פ תורתנו תורת חיים וקיום מצותי' עליהן נאמר וחי בהם.</p>\n<p>נ.ב. <b>בהגיון תורה:</b> ומוקדם לזה (פדר\"א ספל\"ב) צ\"ל \"קול יעקב ביחוד השם\" - עבודת התפלה ועד שמייחדים שמו - שאז הגיון תורה (ע\"ז יט, א) הוא בסדר וככתוב בתורה (ראה רש\"י ותוס' ברכות ה, ב. לקוטי תורה לרבנו הזקן פ' ברכה צו, ב).</p>\n<p><b>בקעה מצא וגדר בה גדר:</b> שאך זו עצה היעוצה <b>בכל</b> עניני היהדות, וכהוראת חז\"ל בזה בשלשת הסוגים, ועל הסדר: בדרבנן שצריכין חיזוק (עירובין ו, א. ר\"ה יט, א). ואפילו בדאורייתא שנתגלה טעמן (עירובין ק, ב. וראה סנה' כא, ב) ואפילו בחוקים ובחידוש שבחוקים (חולין קי, א. ח\"פ להרמב\"ם פ\"ו ור\"ח ביומא סז, ב. חולין קח, א ובתוד\"ה מבשר שם).</p>\n<h4><i><b>ח'תתסד</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חט\"ו ע' 495 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מוה\"ר יצחק מאיר:</b> לוין. אגרות נוספות אליו - לעיל ח'תשמט, ובהנסמן בהערות שם.</p>\n<p><b>ואין אמת:</b> ירושלמי ר\"ה פ\"ג ה\"ח.</p>\n<p><b>אמת.. בלי פשרות:</b> ראה גם לעיל אגרת ח'תרצד, ובהנסמן בהערות שם.</p>\n<p><b>בקעה מצא:</b> ראה גם לעיל חי\"ב אגרת ג'תתיב. לקמן אגרת שלאח\"ז.</p>"],[1200970190,"ח'תתסה\n\n<p>ב\"ה, ד' מנ\"א ה'תשכ\"ד</p><p>ברוקלין.</p><p>כבוד הרב הגאון המפורסם חו\"ב הוו\"ח אי\"א<br>\nנו\"מ וכו'<br>\nמוהרא\"י שליט\"א<br>\nרב ראשי</p>\n<p>שלום וברכה!</p>\n<p>מועתק בזה נוסח המברק שהואיל כ\"ק אדמו\"ר שליט\"א לשלוח לכהדר\"ג שליט\"א, ובטח נתקבל בעתו ובזמנו:</p>\n<p>לרגל חזרתם לארץ הקודש אביע איחולי לנסיעה כשורה ובהצלחה ואשר מתוך בריאות הנכונה ינצל כהדר\"ג במילואן כל האפשריות שישנן לחזק בדק היהדות האמיתית לבסס ולהפיץ התורה ומצותי' שהיא תורת אמת והרי אמת שוללת כל פשרה ונראה במוחש בדורנו ששיטת הפשרות פשטה את הרגל וכו' ואדרבה הורו חכמינו ז\"ל דבמקום שבקעה מצא הנה התיקון הוא לגדור בה גדר והורינו שלש פעמים ועל הסדר בענינים דרבנן וגם במצות שכליות וגם בחוקים ויעשה כהדר\"ג בהאמור לאורך ימים ושנים טובות ובאופן דמוסיף ואור וזכות ארץ הקודש תבנה ותכונן במהרה בימינו על ידי משיח צדקנו מסייעתו.</p>\n<p>בכבוד ובהוקרה ובברכה.</p>\n<p><b>מנחם שניאורסאהן</b></p><p>בכבוד ובברכה</p>\n<p>מזכיר</p>\n<h4><i><b>ח'תתסה</b></i></h4>\n<p><b>מוהרא\"י:</b> אונטרמן.</p>\n<p><b>אמת.. פשרה:</b> ראה גם לעיל אגרת ח'תרצד, ובהנסמן בהערות שם.</p>\n<p><b>הורו חכמינו:</b> ראה גם אגרת שלפנ\"ז, ובהנסמן בהערות שם.</p>"],[1200970191,"ח'תתסו\n\n<p>ב\"ה, ה' מנחם אב, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"נ רב פעלים וכו'<br>\nמוה\"ר שלמה יהודא ליב שי' אדלר<br>\nיו\"ר אגודת השוחטים בת\"א</p>\n<p>שלום וברכה!</p>\n<p>בעתו קבלתי מכתבו מא' בתמוז, וחכיתי עם המענה שלי עד לאחרי הפגישה עם הרה\"ג והרה\"ח וו\"ח אי\"א נו\"מ בעל מדות ורב פעלים הרא\"י שליט\"א אונטרמן רב הראשי.</p>\n<p>וכנראה מקטעי מכתבי העתים וגם ממכתב כ' וכן מרושם השיחה האמורה, המצב בהענין עליו כותב הולך ומשתנה מיום ליום, מצד כמה גורמים שמתערבים בזה ומטעמים שונים ומשונים.</p>\n<p>ויהי רצון שזכות הרבים יסייע שכל הענין יסתדר באופן הכי טוב באמת, וידוע גודל ענין הכשרות וגודל הזהירות שצריך להיות בזה, בכל מקום ובכל זמן, ובפרט בתקופתנו ובארץ הקדש, ארץ אשר עיני ה\"א בה מראשית השנה ועד אחרית שנה.</p>\n<p>בכבוד ובברכה לבשורות טובות בכל האמור.</p>"],[1200970192,"ח'תתסז\n\n<p>ב\"ה, ה' מנחם אב, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"מ עוסק בצ\"צ וכו' מוהרש\"ז<br>\nשי' שרגאי</p>\n<p>שלום וברכה!</p>\n<p>הנני בזה לאשר קבלת מכתבו מכ\"ט תמוז והקודמו.</p>\n<p>ות\"ח על שימת לבבו להודיעני בנוגע החבילות וכולי. ומסתם גם בעתיד יעשה כן ותודה למפרע.</p>\n<p>להערתו אודות החשיבות המיוחדת של מדת אהבת ישראל, שהרי להבדיל בין ישראל לעמים גם אצל אומות העולם אנגלי אוהב את האנגלים וכו' - החילוק, חילוק עקרי, מובן מלשון הכתוב ואהבת לרעך <b>כמוך,</b> שכמו שאהבת האדם לעצמו אינה תלוי' בזה שרואה מעלות עצמו - בשכל או מדות שבלב או במחשבה דיבור ומעשה, ואדרבה על כל פשעים תכסה אהבת עצמו - כן הציווי בנוגע לאהבת רעהו, שתהי' גם כן אהבה עצמית בלתי תלוי' בדבר ובמעלה וכולי.</p>\n<p>על פי זה מובנת התמי' איך אפשר שתהי' דרגת אהבת זולתו \"כמוך\", ועל זה בא ביאור רבנו הזקן בספר התניא פרק לב, שמתחיל בביאורו ממדרגת אהבת הזולת שבקל יותר להשיגה \"כי מי יודע גדולתן ומעלתן\" כולי, אבל סו\"ס הרי זו ג\"כ אהבה תלוי' במעלה, לכן מוסיף ביאור \"שכולן מתאימות ואב אחד לכולנה\" כולי \"אחים ממש\".</p>\n<p>עיי\"ש.</p>\n<p>הדגשה מיוחדת עפ\"י תורת החסידות בכל האמור מבוארת בספר המצוות לאדמו\"ר הצמח צדק, מצות אהבת ישראל פרק ב. עיי\"ש.</p>\n<p>ומגלגלין ענין לימים מתאימים, שהרי נמצאים אנו בין המצרים דחורבן בית שני שקרה מפני שנאת חינם. ופשוט שזה שנצטוינו לעשות זכר לחורבן, ביחוד בימים אלו, כוונתו בשביל התיקון, שהרי החורבן הוא כנוסח התפלה ומפני חטאינו גלינו מארצנו כו', ואי אפשר לביטול המסובב כי אם על ידי ביטול הסיבה, וכל גרעון וחלישות בסיבה מביאה גרעון וחלישות בהמסובב, אפילו אם הוא - כמבואר בתורת החסידות - לעת עתה רק בעולמות העליונים. וכיון שעיקר החטא, כהודעת חכמינו ז\"ל, הי' בשנאת חינם, הרי תיקונו באהבת חינם היינו בלתי תלוי' בדבר. ויהי רצון שבקרוב ממש נזכה לקץ גלותנו ולגאולה האמתית והשלימה על ידי משיח צדקנו, ויהפכו ימים אלו לששון ולשמחה.</p>\n<p>בכבוד ובברכה.</p>\n<p>בשיחתי עם הרה\"ג והרה\"ח וו\"ח אי\"א נו\"מ עוסק בצ\"צ וכו' הרא\"י שליט\"א אונטרמן רב הראשי, נסבה השיחה גם בענין הספינות הישראליות ובמענה על שאלתי אמר ברור שמעולם לא הוא ולא רבנות הראשית נתנו היתר לנסיעה בספינות אלו.</p>\n<h4><i><b>ח'תתסז</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ב ע' 245 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מוהרש\"ז שי' שרגאי:</b> אגרות נוספות אליו - לעיל חכ\"ב ח'תכט, ובהנסמן בהערות שם.</p>\n<p><b>ומגלגלין:</b> ראה גם אגרת ח'תתסט.</p>\n<p><b>כהודעת חכמינו:</b> יומא ט, ב.</p>\n<p><b>בשיחתי:</b> ראה לעיל אגרת ח'תתמז.</p>\n<p><b>בענין הספינות הישראליות:</b> ראה גם לעיל אגרת ח'תשלא, ובהנסמן בהערות שם.</p>"],[1200970193,"ח'תתסח\n\n<p>ב\"ה, ה' מנ\"א, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>מר שמואל יצחק הכהן שי' אבידור</p>\n<p>שלום וברכה!</p>\n<p>לפלא קצת שמאז מכתבו מכמה חדשים קודם לכן לא קבלתי מכתב מכ', אף שתקותי חזקה שלא מדקדק עמי שמתעכב מכתבי מפני הטרדות, ולמרבה הצער לא כל הטרדות מסוג שמחה.</p>\n<p>בהתאם לסגנון מכתבו, תקותי שהשתתף בכמה התועדויות חסידותיות באה\"ק ת\"ו ולכן הי' לי לפלא שלא נזכר שמו בין אלו שהשתתפו בחגיגת (זיכרון ל)י\"ב תמוז בכפר חב\"ד. ובודאי השתתף בחגיגה כזו במקום אחר באה\"ק ת\"ו.</p>\n<p>ולמותר להדגיש לדכוותי' שענין הזכירה הוא ההתעוררות למעשים בפועל, ובנידון דידן - ברוח בעל השמחה והגאולה די\"ב-י\"ג תמוז, אשר מסר נפשו בעד החזקת והפצת התורה ומצוותי', מבלי להתחשב במניעות ועיכובים. ובימים אלו שבין המצרים בודאי שראוי והגון לעשות ולפעול בכיוון זה, שזכרון החורבן מזכיר ומעמידנו על הסיבה, וכנוסח התפלה ומפני חטאינו גלינו מארצנו כו' וכוונת הזכרון הוא בשביל התיקון, ואי אפשר לביטול כי אם על ידי ביטול הסיבה. ויהי רצון שבקרוב ממש נזכה לקץ גלותנו ולגאולה האמתית והשלימה על ידי משיח צדקנו, וימים אלו יהפכו לששון ולשמחה.</p>\n<p>בפ\"ש אחיו שי' ובכבוד וברכה ובת\"ח על מסירת הפ\"ש.</p>"],[1200970194,"ח'תתסט\n\n<p>ב\"ה, ה' מנחם אב תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>מר שניאור זלמן שי' מסחרי</p>\n<p>שלום וברכה!</p>\n<p>בנועם הנני לאשר קבלת מכתבו מכ\"ו תמוז, ות\"ח בעד שימת לבבו.</p>\n<p>... בראותי הרגש לבו ואהבתו לכפר חב\"ד, בתוככי אהבת ישראל בכלל, הרי ההתחזקות בזה היא דבר בעתו בפרט בימים אלו שבין המצרים דחורבן בית שני שקרה מפני שנאת חינם, כהודעת חכמינו ז\"ל. ופשוט שזה שנצטוינו לעשות זכר לחורבן, בימים אלו ביחוד, הכוונה היא בשביל התיקון, שהרי החורבן הוא כנוסח התפלה ומפני חטאינו גלינו מארצנו, ואי אפשר לביטול המסובב כי אם על ידי ביטול הסיבה, וכל גרעון וחלישות בסיבה מביאה גרעון וחלישות בהמסובב, אפילו הוא - כמבואר בתורת החסידות - לעת עתה רק בעולמות העליונים. וכיון שעיקר החטא הי' שנאת חינם, הרי תיקונו באהבת חינם.</p>\n<p>ויהי רצון שבקרוב ממש נזכה לקץ גלותנו ולגאולה האמתית והשלימה על ידי משיח צדקנו, ויהפכו ימים אלו לששון ולשמחה.</p>\n<p>בכבוד ובברכה לבריאות.</p>\n<h4><i><b>ח'תתסט</b></i></h4>\n<p><b>מר שניאור זלמן מסחרי:</b> אגרות נוספות אליו - לעיל ח'תשיב, ובהנסמן בהערות שם.</p>\n<p><b>כהודעת חכמינו:</b> יומא ט, ב.</p>"],[1200970195,"ח'תתע\n\n<p>ב\"ה, עש\"ק ט' באב (נדחה), ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הרה\"ח הוו\"ח אי\"א נו\"מ רב פעלים וכו'<br>\nהרמ\"פ שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>נעם לי להוודע, אשר ימים אלה מסיימים הם -</p>\n<p>קבוצת הלומדים תורה ברבים - ובמקום תפלה - בביהכנ\"ס עדת יעקב - ה' עליהם יחיו -</p>\n<p>מסכת ביצה וממשיכים בקודש - לימוד מסכת סוכה,</p>\n<p>ומגלגלין כו' שיהי' הסיום ביום היאצ\"ט הראשון של חותנו - יבלח\"ט - הרה\"ח הוו\"ח אי\"א נו\"מ בעל מדות ועוסק במצות ובמיוחד בעניני ביהכנ\"ס וכו' מוה\"ר דוד הלוי תנצב\"ה,</p>\n<p>והרי כל עניני ביהכנ\"ס וביהמ\"ד שייכות מיוחדה להם לחדש זה וכנבואת יחזקאל הכהן \"כה אמר אד' אלקים כי הרחקתים בגוים וכי הפיצותים בארצות - ואהי להם למקדש מעט (אלו בתכנ\"ס ובמד\"ר) בארצות אשר באו שם\".</p>\n<p>כי בעמדנו בימי זכרון לימים ההם בזמן הזה, חורבן בית מקדשנו, בית ראשון ובית שני,</p>\n<p>הנה ע\"פ הוראת חז\"ל שהמעשה הוא העיקר, ומקרא מלא דבר הכתוב, את האלקים ירא ואת מצותיו שמור <b>כי זה כל</b> האדם, מובן שכוונת זכרון זה הוא - שישפיע ויביא למעשה בפועל,</p>\n<p>ולכל לראש - בתוכן זכרון זה, הוא ענין החורבן וסיבתו, שהם כמפורש בכ\"מ בתנ\"ך ובלשון חז\"ל: מפני חטאינו - גלינו מארצנו וכו' היד שנשתלחה במקדשך,</p>\n<p>שמזה המסקנא אשר \"המלחמה\", החלישות, והגירעון בהסיבה (חטאינו) - מחלישים וגורעים את המסובב (גלינו מארצנו, היד שנשתלחה) ומקרבים את הגאולה, גאולה האמיתית והשלימה על ידי משיח צדקנו,</p>\n<p>אשר כהוראת מורה הנבוכים (מאז בדורו - ועד בדורנו) ופסק דינו הברור - ב\"ידו החזקה\", המלך המשיח הוא אך הוא מקבץ נדחי ישראל, ומקודם לזה ובתור הקדמה והכנה לזה, הרי נוסף על היותו \"הוגה בתורה ועוסק במצות כדוד אביו\" - \"יכוף כל ישראל לילך בה ולחזק בדקה\", ולאחרי זה (ועל הסדר) - \"ילחם מלחמת ה'\" וינצח, \"כל האומות שסביביו\", ו\"יבנה מקדש במקומו ויקבץ נדחי ישראל\".</p>\n<p>ויהי רצון שכל אחד ואחת, \"ילחם בהסיבה - בחטאינו\" - ע\"י קיום התומ\"צ, לילך בה ולחזק בדקה -</p>\n<p>וע\"פ ההבטחה אשר הבא לטהר מסייעין אותו - יצליח,</p>\n<p>ועי\"ז ימהר קץ גלותינו ויקרב ביאת משיח צדקנו וגאולתנו,</p>\n<p>ונזכה לקיום היעוד אשר יהפכו ימים אלו לששון ולשמחה.</p>\n<p>בברכה כי בקרוב ממש נזכה לגאולה האמתית של כל בנ\"י ממדבר העמים הוא מדבר הגלות, כי על כאו\"א נאמר ואתן צאני צאן מרעיתי, כי לד' הארץ ומלואה ולכן כולן ביתיות הן, ואפילו הנמצאים בעשתרות קרנים - ל' חוזק ועשירות - שטועה לומר כוחי ועוצם ידי עשה לי גו' - סו\"ס בל ידח ממנו, ודל עשתרות קרנים ואיכא צל סוכה, המלמדת את האדם ענוה ושפלות לבלתי רום לבבו לומר ידינו עשו לנו, שזוכר נפלאותיו ונוראותיו, זוכר יצי\"מ, וכימי צאתך מארץ מצרים אראנו נפלאות - בגאולתנו הקרובה.</p>\n<p>ובפ\"ש כל המשתתפים בהלימוד שליט\"א ובכבוד.</p>\n<h4><i><b>ח'תתע</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ח ע' 357 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>הרמ\"פ:</b> כ\"ץ, ברוקלין. אגרות נוספות אליו - לעיל חכ\"א ז'תשסה, ובהנסמן בהערות שם.</p>\n<p><b>דוד הלוי:</b> שטאקהאמער.</p>\n<p><b>מכ' כ\"ק אדנ\"ע:</b> אג\"ק שלו ח\"א אגרת קכט.</p>\n<p><b>ט' באב (נדחה): </b>להעיר אשר נדחה רק ענין התענית וכו' שבו, אבל ענין הנחמה - בתוקפו עומד, שלכן א\"א צדקתך אף שזהו בפרהסיא (או\"ח החדש סו\"ס תקנ\"ב) .</p>\n<p><b>ובמקום תפלה: </b>ברכות ח, א.</p>\n<p><b>אלו בתכנ\"ס ובמד\"ר: </b>מגילה כט, א.</p>\n<p><b>הוראת חז\"ל: </b>אבות פ\"א מי\"ז.</p>\n<p><b>ומקרא מלא: </b>קהלת יב, יג.</p>\n<p><b>ב\"ידו החזקה\": </b>הל' מלכים פי\"א.</p>\n<p><b>הוגה בתורה: </b>ראה ע\"ז יט, א. ובפדר\"א ספל\"ב דקול יעקב (שהוא המבטל ידי עשיו) היינו \"הגיון תורה\".</p>\n<p><b>ועוסק במצות: </b>ראה ר\"ן לסוכה (כח, א) בדיוק הל' עוסק במצוה (ולא מקיים מצוה).</p>\n<p><b>כדוד אביו: </b>ל' הרגיל בנ\"ך בנוגע למלכי בית דוד. וי\"ל הכוונה שתהי' התורה בדרך עול והמצות בהקדמת עולה של תשובה \"תשובה ומעש\"ט\" - שזה הוקם ע\"י דוד דוקא (ע\"ז ה, א. מדרש שמואל ויל\"ש לש\"ב כג, א. וראה תו\"א ריש מגילת אסתר).</p>\n<p><b>יכוף כל ישראל: </b>יל\"פ השייכות לתיקון ענין החורבן - שהי' על שלא מיחו (שבת קיט, ב. איכה רבה א, ה).</p>\n<p><b>לילך בה ולחזק בדקה: </b>לאלה שלא חטאו, לאלה שעברו ופרצו; צדיקים ובע\"ת.</p>\n<p><b>וינצח \"כל האומות שסביביו\": </b>כ\"ה בדפוס רומי - שלא שלטו בו ידי המבקרים מטעם או\"ה.</p>\n<p><b>ויבנה מקדש: </b>ע\"פ ויק\"ר פ\"ט, ז דמשיח בונה ביהמ\"ק. וראה ג\"כ ירוש' מגילה פ\"א הי\"א.</p>\n<p>ופרש\"י ותוס' (סוכה מא, סע\"א) דיבוא משמים - הוא ע\"פ תנחומא (נח, יא). זח\"א כח, א.</p>\n<p>ובכ\"מ.</p>\n<p><b>ויקבץ נדחי ישראל: </b>לבסוף (זח\"א קלד, א. קלט, א - וכ\"פ רש\"י בברכות מט, א - ופליג אתנחומא הנ\"ל - וראה בארוכה מכ' כ\"ק אדנ\"ע בקובץ מכתבים א' ס\"ט).</p>\n<p><b>ההבטחה: </b>יומא ספ\"ג.</p>\n<p><b>ואתן צאני: </b>יחזקאל לד, לא.</p>\n<p><b>ביתיות הן: </b>ביצה בסיומה.</p>\n<p><b>ל' חוזק ועשירות: </b>רש\"י עקב ז, יג.</p>\n<p><b>דל עשתרות קרנים: </b>סוכה בתחלתה.</p>\n<p><b>המלמדת.. עשו לנו: </b>מו\"נ ח\"ג פמ\"ג. רשב\"ם ויקרא כג, מג.</p>\n<p><b>זוכר.. יצי\"מ: </b>שו\"ע רבנו הזקן סתרכ\"ח.</p>"],[1200970196,"ח'תתעא\n\n<p>ב\"ה, עש\"ק ט' באב (נדחה), ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ צנמ\"ס<br>\nכו' מו\"ה<br>\nשלמה יוסף שי'</p>\n<p>שלום וברכה!</p>\n<p>... נבהלתי להידיעה שידידנו שליט\"א הנה דוקא בכינוס (<b>היחידי</b> באופי שלו) של כו\"כ רבנים מטיפוסם של דורות שקדמונו (וגם במעלה) - שלח שלישו לייצגו! [ואי\"ז מספיק, וכאילו להדגיש הענין עוד יותר - בתוך ימים <b>ספורים</b> והייתה אסיפת רופאי שיניים - בא דוקא בעצמו!]. וכדאי לברר מיהו הלוחץ על הנ\"ל ומעבירו על דעתו העצמית - ולתקן עכ\"פ בעתיד.</p>\n<p>בברכה - שכדברי הררא\"ל שי' געלמאן שמוכנים כבר עוד <b>ב'</b> כרכי האנצ' - יו\"ל בעגלא של הציבור (ולא דהמו\"ל),</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתעא</b></i></h4>\n<p><b>מו\"ה שלמה יוסף:</b> זוין. אגרות נוספות אליו - לעיל ח'תשלא, ובהנסמן בהערות שם.</p>\n<p><b>שידידנו:</b> מוהש\"ז שזר.</p>\n<p><b>בכינוס:</b> דכנסי' הגדולה החמישית (ראה לעיל אגרת ח'תתסד). ראה גם לקמן אגרת ח'תתפ.</p>"],[1200970197,"ח'תתעב\n\n<p>ב\"ה, י\"א מנ\"א תשכ\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>... ולשאלתו אופן העבודה בענינו ובכלל.</p>\n<p>ידועה ההוראה מעט מעט אגרשנו, אשר כשהולכים מדרגא לדרגא (ובהחלטה תקיפה) - הרי זה בר קיימא, וק\"ל.</p>\n<p>ולכתבו אודות הצלחתו בלימוד בנגלה וחסידות - כיון שהבטיחונו חכמינו ז\"ל יגעת ומצאת, הנה ילמוד בהתמדה ושקידה ועד לאופן שהתורה קוראה זה יגיעה - ותקוים ההבטחה ומצאת.</p>\n<h4><i><b>ח'תתעב</b></i></h4>\n<p>נדפסה ב\"היכל מנחם\" חלק א ע' קט.</p>\n<p><b>שהבטיחונו חכמינו:</b> מגילה ו, ב.</p>"],[1200970198,"ח'תתעג\n\n<p>ב\"ה, י\"ד מנ\"א תשכ\"ד</p><p>ברוקלין.</p>\n<p>ברכה ושלום!</p>\n<p>מאשר הנני קבלת מכתבי' עם הפ\"נ שיקראו בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ויהי רצון שתבשר טוב בתוכנו וכן בתוכן מכתבי'.</p>\n<p>ובפרט אשר יצאנו כבר מימים הראשונים דחדש מנ\"א ונכנסנו לימי הנחמה ומהם לחדש אלול חדש הרחמים רחמיו המרובים של יוצר האדם ומשגיח עליו בעין פקיחה ועין טובה וזן ומפרנס כל צרכיו הן בגשם והן ברוח ובאור פני מלך (מה\"מ) חיים, (וכל צרכי החיים) וע\"פ המבואר בזהר הק' עלמא עילאה כגוונא דעלמא תתאה, ואור פני האדם למטה ממשיך אור ברכה וישועה מעולם העליון.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<h4><i><b>ח'תתעג</b></i></h4>\n<p><b>בזהר:</b> ח\"א כט, ב.</p>"],[1200970199,"ח'תתעד\n\n<p>ב\"ה, י\"ז מנ\"א תשכ\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מט\"ו מנ\"א, בו כותב ע\"ד בתו תחי'.</p>\n<p>וע\"פ כתבו כנראה ששואלים דעת רופאים מומחים, ובטח ממלאים ההוראות שלהם, שהרי על האדם לעשות התלוי בו בדרך הטבע.</p>\n<p>בעת רצון יזכירום על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע להמצטרך להם.</p>\n<p>וכיון שמשרתו בחינוך בני ישראל, התקוה שמחדיר בתלמידיו יראת ה' ואהבת ה' המביאים לידי קיום מצות עשה ומצות לא תעשה, ועוד יוסיף בזה.</p>\n<p>וגדול זכות האמור לעמוד לו בהמצטרך לו ולמילוי משאלות לבבו לטובה.</p>\n<p>ובפרט ע\"פ הידוע פתגם הבעל שם טוב, אשר אהבת השם לכל אחד מבני ישראל הוא באין ערוך יותר מאהבת הורים זקנים לבן יחידם שנולד להם לעת זקנותם.</p>\n<p>ומהנכון אשר יבדקו את התפילין שלו וכן את המזוזות בדירתם שתהיינה כולן כשרות כדין, וזוגתו תחי' תשמור על מנהגן הטוב של בנות ישראל הכשרות להפריש לצדקה קודם הדלקת הנרות בכל ערב שבת וערב יום טוב.</p>\n<p>בכבוד ובברכה לבשו\"ט בכל האמור.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>נ.ב. לכתבו אודות התראות פא\"פ, אין בדבר נחיצות כלל וכלל שהרי המענה כתוב הוא לעיל, והתורה חסה על ממונם של ישראל הוצאות כספיות דהנסיעה והרי בכגון זה גם הוצאה במרץ ובזמן וכו'.</p>\n<h4><i><b>ח'תתעד</b></i></h4>\n<p><b>יראת ה'.. המביאים:</b> ראה תניא פ\"ד.</p>\n<p><b>פתגם:</b> ראה גם לעיל חכ\"ב אגרת ח'שיז, ובהנסמן בהערות שם. לקמן אגרת ח'תתקג.</p>\n<p>ח'תתקסב.</p>\n<p><b>והתורה חסה:</b> ר\"ה כז, א.</p>"],[1200970200,"ח'תתעה\n\n<p>ב\"ה, כ\"א מנ\"א תשכ\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>ראיתי שורותיו המעטות בשולי מכתב...</p>\n<p>ומובן אשר תמהתי וגם נצטערתי על הסיום אשר נתק ח\"ו קשריו עם כפר חב\"ד.</p>\n<p>ומבלי להכנס על מה ומה הם הטעמים והנמוקים וכו' שהרי בודאי לא הי' עושה ענין כזה סתם בעלמא,</p>\n<p>הרי בודאי שאין האמור נכון כלל וכלל.</p>\n<p>דאם בכלל צ\"ל אהבת ישראל וקירוב הלבבות וכו' (כמבואר בארוכה בספר תניא קדישא פרק ל\"ב) עאכו\"כ בדורנו ובאה\"ק ת\"ו ועאכו\"כ בההולכים בדרכיו ואורחותיו של בעל התניא ואפילו להצודק במאה אחוז, דרישה האמורה מופנית, ובפרט שאמרו חז\"ל כל המעביר על מדותיו וכו'.</p>\n<p>והרי מתקרבים אנו לחדש אלול חדש הרחמים. ובודאי האריכות בכגון זה אין בה צורך, ואצפה לבשו\"ט בכל האמור.</p>\n<p>בכבוד ובברכה לבשו\"ט בהנ\"ל.</p>\n<h4><i><b>ח'תתעה</b></i></h4>\n<p><b>שאמרו חז\"ל:</b> יומא כג, א. וש\"נ.</p>"],[1200970201,"ח'תתעה*\n\n<p><i>[כ\"ד מנחם אב תשכ\"ד]</i></p>\n<p>ע\"פ הנ\"ל - נכון לדבר עם הבעה\"ב והפרעזידנט וכו' <b>שמזה</b> נראה <b>ברור</b> מהו ענין המחיצה, שאלו שמנגדים למחיצה כדבעי - ה\"ה <b>שגילו</b> דעתם עתה מה אמתית השקפתם, ומזה מובן שכל אלה המאמינים בתורה מן השמים (היפך הקונסרוטיבים) עליהם להלחם בעד המחיצה וכו'.</p>\n<p>אין זה מונעם <b>כלל</b> לערוך פעטישאן הנ\"ל - עתה או לאחר זמן. ואדרבה אז לא יוכל לצאת נגדם בחוזק כדעתה, כיון שע\"י קבלת המשרה מודה שלהם הדעה גם בענינים רוחנים, ואפילו אם יבטיחו זה בחוזה - הרי משנים החוזה דעתה.</p>\n<p>אין זה ענינו כלל, ובכלל צע\"ג אם מותר ע\"פ דין.</p>\n<h4><i><b>ח'תתעה*</b></i></h4>\n<p>מענה למו\"ה שמואל פסח שי' בוגומילסקי על גליון מכתבו מכ\"ד מנחם אב. אגרות נוספות אליו - לעיל ח'תשצה, ובהנסמן בהערות שם.</p>\n<p><b>ע\"פ הנ\"ל:</b> במכתבו: היום בערב צלצל אלי הרב... שבקרו אצלו הבעה\"ב מהבכ\"נ שלי והראו לו שהכינו \"פעטישאן\" לעשות הבהכ\"נ קונסרבטיב.</p>\n<p><b>אין זה:</b> במכתבו: בקונסטיטושן של הבהכ\"נ וגם בחוזה שלי כתוב שהרב בעצמו אחראי בעניני יהדות ולכן אמרתי להם... שאם אינם מסכימים לתיקון המחיצה נמצא שהם מבטלים החוזה שלי.</p>\n<p><b>אין זה ענינו:</b> במכתבו: שאלתי את הרב משה דובער שי' רבקין ואמר שא\"א לו לתת היתר למחיצה של 4 רגל, ולהיות הרב ע\"מ שבמשך הזמן לתקן זה... ובפרט להצילם מקונסרבטיב, שאלה רוחנית כזו שייך לכ\"ק אדמו\"ר שליט\"א.</p>"],[1200970202,"ח'תתעו\n\n<p>ב\"ה, כ\"ה מנ\"א, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ המכונה ד\"ר ש.<br>\nב. אולמאן</p>\n<p>שלום וברכה!</p>\n<p>בנועם קבלתי ספרו מסות \"חנוך ומדע\", ות\"ח על שימת לבבו לשלחו לי, שנוסף על הקורת רוח מהספר הרי מעיד הוא שכ' מנצל גם עתה כשרונותיו לחיזוק היהדות בכל מקום שידו מגעת, כמו שרואני ג\"כ מהמאמרים המתפרסמים ב\"דזשואיש פרעס\", ובודאי גם בזה ימשיך, כי יש מי שמגיעים אליהם על ידי ספר, ויש מי שמגיעים אליהם על ידי מאמר במכ\"ע.</p>\n<p>ויהי רצון שימשיך בכל הנ\"ל מתוך עבודה באהבה ובשמחה ובבטחון גמור בהשי\"ת שיצליחו בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה לבשורות טובות בכל האמור ובכבוד.</p>\n<h4><i><b>ח'תתעו</b></i></h4>\n<p><b>ד\"ר ש. ב. אולמאן:</b> אגרות נוספות אליו - לעיל חי\"ח ו'תתסח, ובהנסמן בהערות שם.</p>"],[1200970203,"ח'תתעז\n\n<p>ב\"ה, כ\"ה מנ\"א תשכ\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה חיים יונה<br>\nשי'</p>\n<p>שלום וברכה!</p>\n<p>נאך א ליינגערן איבעררייס בין איך געווען צופרידען צו באקומען אייער בריף פון יום השני, מיט דער גוטער בשורה, אז בקרוב וועט מען מסיים זיין דעם לערנען עין יעקב ברבים, וועלכעס קומט פאר אין אייער הויז.</p>\n<p>השם יתברך זאל העלפען ס'זאל בשעה טובה ומוצלחת בכל הפרטים, דער סיום פון עין יעקב און אויך דאס אנהויבען באלד פון דאסניי, ווי ס'פירט זיך בא אידען, שמנהג ישראל תורה הוא, שמתכיפין התחלה להשלמה.</p>\n<p>און בפרט ווי ערקלערט אין מערערע ערטער דער פארבונד פון <b>דעם</b> סיום מיט <b>דער</b> התחלה, אויף פערשידענע אופנים, און איינער פון זיי איז:</p>\n<p>לכאורה דארפמען פארשטיין ווי איז באמת מעגליך ערפילען די פאדערונג, א אמת'ן שלום צווישען מענשן, וואס <b>אין</b> דיעותיהם שוות וכו',</p>\n<p>א פאדערונג מיט אזא שטארקייט, ביז אז מ'זאגט, לא מצא הקב\"ה כלי מחזיק ברכה לישראל <b>אלא</b> השלום.</p>\n<p>איז אויף דעם די ערקלערונג, אז דאס ווערט ערמעגליכט דורך דעם לייענען קריאת שמע, גלייך באם אנהויב פון דעם מעת לעת, ווי די התחלה פון דער משנה, מאימתי קורין את שמע בערבית, וואס דער אינהאלט פון ק\"ש איז, צו ממליך זיין הקב\"ה, ביז מ'אנערקענט אז ה' אחד, אין אלע זיבען הימלען און אויף דער ערד און אויך בארבע רוחות העולם.</p>\n<p>וואס דאס ווירקט צו אויפגעבען און איבערגעבען דעם רצון פון יעדן איינעם צו דעם רצון פון ה' אחד, וואס דענסטמאל פארשווינדעט אלעס וואס קען צוטיילען און אונטערשיידען, און עס ווערט דער אמת'ר שלום, און השם יתברך גיט זיין פולסטע ברכה, ווי מיר זאגען באם <b>שלוס</b> פון שמונה עשרה, ברכנו אבינו (לפי) שכולנו כאחד (זעה תניא פרק ל\"ב).</p>\n<p>און ווי ערקלערט אויספירליך אין פילע ערטער בתורתנו הק' תורת חיים און מער טיפער בפנימיות התורה, וואס אין גמרא איז דאס אגדה שבספר עין יעקב, שרוב סודות התורה גנוזים בה (עיין אגרת הקדש לרבנו הזקן סי' כ\"ג).</p>\n<p>בברכה להצלחה בכל האמור, ובפ\"ש כל המשתתפים שליט\"א בלימוד הכי נעלה האמור,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתעז</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ט ע' 440 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>מו\"ה חיים יונה:</b> דן, ניו הייווען.</p>\n<p><b>שמנהג ישראל:</b> נסמן בלקו\"ש חכ\"ב ע' 56 הערה 2.</p>\n<p><b>שמתכיפין:</b> רשות לחתן בראשית.</p>\n<p><b>אין דיעותיהם שוות:</b> ראה ברכות נח, א.</p>\n<p><b>לא מצא:</b> עוקצין בסופה.</p>\n<p><b>אחד... העולם:</b> סמ\"ק הובא בב\"י או\"ח סס\"א. שו\"ע ואדה\"ז או\"ח שם ס\"ו.</p>"],[1200970204,"ח'תתעח\n\n<p>ב\"ה, כ\"ה מנחם אב, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד מר דוד נ\"י בן-נאים</p>\n<p>שלום וברכה!</p>\n<p>הנני לאשר בזה קבלת ספר שו\"ת רחמים פשוטים וקונטרס דרוש ארץ ישראל שחיברם אביו הרה\"ח וכו' ר' רפאל חיים משה ן' נאים ז\"ל. ותשואות חן לכ' בעד שימת לבבו לשלחם אלי.</p>\n<p>מאוחר יותר נתקבלו הספרים הנ\"ל גם על ידי מר שמואל שי' חסאן. ובראותי שרצונו בכך, וגם שיהי' לעילוי נשמת אביו המחבר תנצב\"ה, מסרתי את הכפולים לישיבת תומכי תמימים ליובאוויטש, בכדי שהתלמידים יוכלו לעיין בהם בכל עת מצוא.</p>\n<p>בטח למותר לעורר את כ' שאם הספרים אזלו מן השוק כדאי ונכון שכ' ושאר בני אביו ידפיסום עוה\"פ לזכות אביו ולתועלת הרבים.</p>\n<p>על פי סגנון מכתבו, התקוה שעושה כל התלוי בו להפצת היהדות במקומו עתה, בפרט על פי מה שאמרו חכמינו ז\"ל במשנתם שהאב זוכה לבניו וכולי, והובטחנו בכגון זה הבא לטהר מסייעין אותו.</p>\n<p>ובפרט שמתקרבים אנו לימי הסגולה דחודש אלול, שאז הוא בדוגמת מלך שקודם בואו לעיר יוצאין אנשי העיר לקראתו ומקבלין פניו בשדה ואז רשאין כל מי שירצה לצאת להקביל פניו והוא מקבל את כולם בסבר פנים יפות כו' כמבואר בלקוטי תורה, פ' ראה, לב, ב לרבינו הזקן בעל התניא והשולחן ערוך.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתעח</b></i></h4>\n<p><b>במשנתם:</b> עדיות פ\"ב מ\"ט.</p>\n<p><b>והובטחנו:</b> יומא לח, ב.</p>"],[1200970205,"ח'תתעט\n\n<p>ב\"ה, כ\"ח מנחם אב, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ ענף עץ אבות יושב על<br>\nמדין<br>\nדקהילתא רבתי אטלאנטיק סיטי, הרב משה<br>\nשי' שפירא</p>\n<p>שלום וברכה!</p>\n<p>בהתענינות גדולה ובשמחה קבלתי הידיעה שבהנהלתו במחנו הט' נתעוררו אנשי הקהילה להקים מקוה חדשה בעירו וביום א' הבע\"ל תתקיים הנחת אבן הפינה וכת\"ר יביע דברי ברכה בשם כל רבני ק\"ק דאטלאנטיק סיטי.</p>\n<p>והרי הזמן מסוגל בפרט לענין כגון זה, ראש חודש אלול המתחיל ארבעים ימי תשובה. וידוע כמה הפליגו חכמינו ז\"ל במשנתם בגודל ערך חשיבות המקוה, עד שהביאו דוגמא וראי' מזה לענין התשובה, בשלהי פרק יום הכיפורים (יום התשובה) - מה מקוה מטהר כולי אף הקב\"ה מטהר את ישראל.</p>\n<p>ואחתום באיחולי לבבי אשר בקרוב ממש יברכו על המוגמר וגם זה יקרב קיום היעוד וזרקתי עליכם מים טהורים וטהרתם (טהרה) ונתתי לכם לב חדש גו' (תשובה) וישבתם בארץ גו' (גאולה האמתית והשלימה על ידי משיח צדקנו).</p>\n<p>בכבוד ובברכת כתיבה וחתימה טובה.</p>\n<p>מוס\"ב העתק מכתבי לועד המקוה.</p>"],[1200970206,"ח'תתפ\n\n<p>ב\"ה, ערב ראש חודש אלול, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד הוו\"ח אי\"א נו\"מ בחור מעם ומורם<br>\nמעם ודורש טוב<br>\nלעמו בעל מדות תרומיות ענף עץ אבות<br>\nמו\"ה שניאור זלמן<br>\nשליט\"א</p>\n<p>שלום וברכה!</p>\n<p>מכתבי הקודמים בטח הגיעו לידי כ', וכן בודאי קבל הפ\"ש ע\"י האורחים שבקרו כאן בשעתם.</p>\n<p>לא אוכל להעלים מכ' כי נצטערתי רבות להידיעה שכ' לא הי' נוכח אישית באסיפת הפתיחה של ה\"כנסי' הגדולה החמישית\". ואף שבודאי היו טעמים ונימוקים בדבר, אבל העובדה במקומה נשארת.</p>\n<p>ובעמדנו ערב ראש חודש אלול, דבר בעתו הוא להעלות על הזכרון דברי אדמו\"ר הזקן בענין סגולת ימי חודש הרחמים, שהוא בדוגמת מלך שקודם בואו לעיר יוצאין אנשי העיר לקראתו ומקבלין פניו בשדה ואז רשאין כל מי שרוצה לצאת להקביל פניו והוא מקבל את כולם בסבר פנים יפות כו', כמבואר בלקו\"ת פ' ראה, לב, ב.</p>\n<p>ויהי רצון שגם ענין האמור יתמלא כלשון רבנו הזקן - בסבר פנים יפות, למעלה, וממילא נמשך גם למטה ספ\"י.</p>\n<p>ומענין לענין בעניני מלכו של עולם, אביע תקותי שבדברי הברכה שישמיע כ' לקראת ראש השנה הבע\"ל יזכיר בפירוש שם שמים, אשר לו הכל יכתירו וממנו כל הברכות (כולל גם סליחת כ' על הערתי זו).</p>\n<p>בהוקרה ובכבוד ובברכת כוח\"ט לשנ\"ט ומתוקה.</p>\n<h4><i><b>ח'תתפ</b></i></h4>\n<p><b>מו\"ה שניאור זלמן:</b> שזר. אגרות נוספות אליו - לעיל ח'תרפב, ובהנסמן בהערות שם.</p>\n<p><b>לא אוכל להעלים:</b> ראה גם לעיל אגרת ח'תתעא.</p>"],[1200970207,"ח'תתפא\n\n<p><i>[י\"א אלול תשכ\"ד]</i></p>\n<p>חבל שלא השתדלו שעכ\"פ יהי' בעשרה - וכדבריו הנפלאים של אדה\"ז</p>\n<p>באגה\"ק - בזה.</p>\n<h4><i><b>ח'תתפא</b></i></h4>\n<p>מענה למו\"ה שניאור זלמן הלוי דוכמאן, על גליון מכתבו מיום י\"א אלול תשכ\"ד. אגרות נוספות אליו - לעיל חכ\"ב ח'תפט, ובהנסמן בהערות שם. לקמן אגרת ח'תתפב. ט'ז.</p>\n<p><b>חבל:</b> במכתבו: כאשר הלימוד בכל יום א' בשבוע לא נפסק ח\"ו אך נתמעטו הלומדים, ע\"כ אני שולח הרשימה בעד ארבעה שבועות ונקוה להשי\"ת כי כאשר יבואו מנאות דשא יתרבו המשתתפים בענין זה בעזהשי\"ת.</p>\n<p><b>וכדבריו הנפלאים:</b> ראה גם אגרת שלאח\"ז.</p>\n<p><b>באגה\"ק:</b> סכ\"ג.</p>"],[1200970208,"ח'תתפב\n\n<p><i>[ח\"י אלול תשכ\"ד]</i></p>\n<p><b>רבותי</b> (הה\"מ והבעש\"ט) אימתה כו' \"בל\"ג ותכלית\" הנמשך ע\"י עשרה - היינו מה <b>שלמע'</b> מעשרה כ\"ז כתר - פלא - למע' מחכ' - קדוש. ועוד: פועל'ן אויך אויפן נפה\"ב - קל יותר ע\"י נפלאים מאשר ע\"י קדושים.</p>\n<h4><i><b>ח'תתפב</b></i></h4>\n<p>מענה למו\"ה שניאור זלמן הלוי דוכמאן על גליון מכתבו מיום ח\"י אלול תשכ\"ד. אגרות נוספות אליו - לעיל אגרת שלפנ\"ז, ובהנסמן בהערות שם.</p>\n<p><b>רבותי:</b> במכתבו: רצוף די רשימה פון היינטיקן יום א' קביעות... וואלט איך זייער וועלן וויסן דעם פשט פון דברי כ\"ק אדמו\"ר שליט\"א \"דבריו הנפלאים\" - מי שרייבט דאך אלע מאל קדושים, איז דאך געוויס א כוונה דער ווארט?</p>\n<p><b>רבותי... ותכלית:</b> אגה\"ק שם (קלו, ב).</p>\n<p><b>רבותי (הה\"מ והבעש\"ט):</b> ראה גם ס' השיחות תש\"ד ע' 98. ס' השיחות תש\"ה ע' 59.</p>"],[1200970209,"ח'תתפג\n\n<p>ב\"ה, כ\"ה אלול, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד הרה\"ג וו\"ח אי\"א נו\"מ בעל מדות רב<br>\nפעלים ורב<br>\nמרץ הרב ישראל שליט\"א המכונה ד\"ר ברוידי<br>\nרב הראשי למדינות בריטני'</p>\n<p>שלום וברכה!</p>\n<p>נעם לי לקבל פ\"ש מכת\"ר על ידי הנוסעים הרבנים הרה\"ח וו\"ח אי\"א נו\"מ עוסקים בצ\"צ וכו' וכו' מוהר\"ר בן ציון שם טוב ומוהר\"ר יונה איידלקופ, שליט\"א.</p>\n<p>ובהזדמנות זו חובתי נעימה להביע קורת רוח מיוחדת בשמעי בפרוטרוט על דבר פעולות כת\"ר לעזר אנשי חב\"ד אשר במחנו הט' בעבודתם המסורה להפצת היהדות והחנוך על טהרת הקדש. וכמים הפנים לפנים ובמדה כנגד מדה יברכהו ה' ויצליחו בכל המצטרך.</p>\n<p>וארשה לעצמי להביע תקותי אשר בהתחשב עם המצב המתוח ביהדות העולם בכלל, ובמדינות מסוימות בפרט, לא יתחשב עם הנוהג וישאר על כהונתו עוד משך שנים, כי עת דרישה היא ולא עת פרישה, והרי זכות הרבים מסייעתו להצליח לחזק בדק הדת ומסורת אבות בשלמותה מבלי פשרות ח\"ו, שהרי כל פשרה נוטה מן האמת, תורתנו תורת אמת הנתונה מה' אלקים אמת. ויהי רצון שיעשה ויצליח מתוך בריאות הנכונה ובשמחה ובטוב לבב.</p>\n<p>ולקראת השנה החדשה, הבאה עלינו ועל כל ישראל לטובה ולברכה, הנני בזה להביע ברכתי לכת\"ר ולכל אשר לו, ברכת כתיבה וחתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות גם יחד.</p>\n<p>בכבוד ובברכה.</p>"],[1200970210,"ח'תתפד\n\n<p>ב\"ה, כ\"ה אלול, תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר אני קבלת מכתבו מט\"ו באלול, ולכל לראש עלי להביע גודל הקורת רוח שקבלתי בראותי ממכתבו יחסו לעניני חב\"ד ובתי ספר חב\"ד וכולי, ועוד וגם זה עיקר אשר כלשונו במכתבו \"גם רוח חב\"ד ותורתה קרובים אלי מאד ואני משתדל ללמוד אותה\", שבודאי כהודעת חכמינו ז\"ל הרי לימוד מביא לידי מעשה, ובפרט כשהמדובר במחנך ולא עוד אלא מפקח על מחנכים, שכל מינוי משמיא קא ממני לי', שמזה מובן שניתנים הכוחות והאפשרויות למילוי התפקיד והמינוי בהצלחה גמורה. ויהי רצון שישפיע בכיוון האמור גם על כל הנמצאים בפיקוחו, והרי הובטחנו הבא לטהר - וידוע דיוק רבינו הזקן בעל התניא והשו\"ע, לא רק ליטהר אלא גם לטהר אחרים - מסייעין אותו.</p>\n<p>לעצם השאלה אודות ניהול בית הספר, צודק בכתבו שלכל לראש ועיקר בכל בית ספר היא תועלת התלמידים והצלחתם בלימודם ובחינוכם, שלכן מוכרח שהמנהל יהי' היותר מתאים לתפקיד האמור. וכיון שהמסקנא היא כאמור, בודאי שישנה האפשריות להביאה בפועל, ולא עוד אלא ככל עניני תורתנו שדרכי' דרכי נועם וגו' גם בזה האפשריות להביא בפועל באופן האמור. וכנ\"ל כיון שכ' הוא המפקח והענין נמסר לטיפולו, הנה סוף סוף ימצא הדרך להביא המסקנא לפועל לתועלת התלמידים, והשי\"ת יצליחו, וההבטחה הבא לטהר מסייעין אותו בודאי כוללת שטח זה.</p>\n<p>והתקוה חזקה שסוף סוף גם אלו שמאיזה טעם שיהי' אינם מתחשבים כדרוש בתועלת התלמידים יראו האמת וגם יודו לו אשר בשעת ההחלטה עמד על דעתו ולא שמע לתביעתם.</p>\n<p>וינעם לי להתבשר טוב בכל האמור.</p>\n<p>ולקראת השנה החדשה הבאה עלינו ועל כל ישראל לטובה ולברכה, הנני בזה להביע ברכתי לו ולכל אשר לו, ברכת כתיבה וחתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות גם יחד.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתפד</b></i></h4>\n<p><b>כהודעת חכמינו:</b> קידושין מ, ב.</p>\n<p><b>שכל מינוי:</b> ראה ברכות נח, א. וש\"נ.</p>\n<p><b>הובטחנו... דיוק:</b> יומא לח, ב. לקו\"ת דרושים לשמע\"צ פח, ב.</p>"],[1200970211,"ח'תתפה\n\n<p>ב\"ה, ימי הסליחות, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד מר קדיש שי' לוז<br>\nירושלים עיה\"ק ת\"ו</p>\n<p>שלום וברכה!</p>\n<p>נעם לי לקבל הידיעות מאנשי כפר חב\"ד על דבר בקורו בכפר חב\"ד והתרשמותו מהמוסדות שם, בהמשך ליחסו הטוב כל העת לאנשי חב\"ד. ובטוחני שימשיך כך להבא ועוד יוסיף בזה בכל עת מצוא בהתאם להתפתחות כפר חב\"ד ועניניו. והרי כלל הוא שבכל עניני טוב צריך להיות מוסיף והולך ומעלין בקדש. ובפרט שיש לכ' אפשרויות מיוחדות עפ\"י מעמדו ומצבו, וכל ענין בהשגחה פרטית הוא.</p>\n<p>ולקראת השנה החדשה, הבאה עלינו ועל כל ישראל לטובה ולברכה, הנני בזה להביע ברכתי לו ולכל אשר לו, ברכת כתיבה וחתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות.</p>\n<p>בכבוד ובברכה רבה.</p>\n<p>מאשר אני קבלת ספרו \"אבני דרך\", בהקדמת בקשת רוב הסליחה על איחור האישור מפני כמה סיבות. ות\"ח על שימת לבבו לשלוח את ספרו, והרי יצירתו של אדם - במדה חשובה משקיפה את המחבר, ובפרט שזה הספר מכיל גם פרקים מתולדות ימי חייו, ובריחוק מקום - יש בזה גם משום היכרות אישית עם מחבר הספר.</p>\n<p>רגיל אני לחשוב, בקבלי ספר ממחבר, שלא \"בכדי\" שלח אלי את ספרו ובודאי כוונת המחבר שאעיין בספרו ואם יהי' לי מה להעיר - יקבל הערותי בספ\"י אפילו אם איני מזדהה עם השקפת עולמו של המחבר. וכן בנוגע לספרו ארשה לי לציין אי איזו הערות, ובפרט - בנקודה הפנימית של הספר, ציור הקבוצה וחיי הקבוצה שלנושא זה בפרט מייחד כ' את ספרו.</p>\n<p>אקוה שכ' יסכים שענין הקבוצה אינו מטרה בפני עצמה, ואצ\"ל המטרה האחרונה; אלא תכליתה להשיג סדר חיים רצוי ומקווה על ידי שיתוף פעולה קיבוצית.</p>\n<p>כשלעצמה הקבוצה ענינה, לכאורה, להשוות קטן וגדול, שזהו בעצם היפך טבע האדם; באשר בני אדם כשם שאין פרצופיהם דומים כך אין דיעותיהם דומות זו לזו.</p>\n<p>ולכן היחיד מוצא סיפוק ושלימות כשאפשר לו להוציא לפועל כל מה שיש לו בכח, ובמדה הכי מלאה, לא כל כך בענינים המשותפים שיש לו עם בני חברתו, אלא דוקא בשטח האינדיבידואלי שלו שבו מצטיין הוא מחבריו וסביבתו, כי הלא זוהי העצמיות שלו. לאידך, אין האדם בטבעו מתבודד ולא טוב היות האדם לבדו, והוא מחפש חיי חברה אשר בה ועל ידה ובעזרתה יוכל להגיע לשלימותו הוא.</p>\n<p>מתוך הנחה האמורה, הנה מחד גיסא יש לחיי הקבוצה חשיבות גדולה בזה שמהוים רקע לשיתוף כוחות של כמה וכמה אנשים ועל ידי כך להישגים גדולים יותר, וכמובן, אפילו מסכום כל הכחות הפרטיים, וכידוע שפעילות שני אנשים בצותא גדולה יותר מכפלים מפעילותו של כל אחד מהם לחוד. ועוד מהענינים החיוביים שבקבוצה שהיא מסירה אותה קנאה ותחרות בלתי רצוי' המביאה פעמים תכופות להתדרדרות היחסים שבין אדם לחברו, משא\"כ פעולה קיבוצית שבדרך כלל מקרבת הלבבות וכולי.</p>\n<p>לאידך גיסא, אין תכלית הקבוצה לבטל כל התחרות בכלל, שהרי אחד מהענינים המעוררים למאמצים יתרים ולהתקדמות וניצול כל הכחות ובזריזות וכולי - הוא דוקא מזה שיש לו לאדם אתגר והתחרות. אלא שעל הקבוצה לצנר את ההתחרות הטבעית לשטח עליון יותר. במלים אחרות, תמורת זה שבחברה אינדיבידואלית מתחילה ההתחרות בצרכים הכי פשוטים, הגשמיים והחומריים, ועד שכלשון חכמינו ז\"ל אלמלא מוראה של מלכות (- הכרח החברה) איש את רעהו חיים בלעו, הנה בקבוצה אפשר להעביר את הכח הזה להישגים גדולים יותר, אם בתוספת מרובה על הצרכים ההכרחיים או בשטח נעלה יותר - בחיי הרוח.</p>\n<p>המורם מהאמור לעיל הוא שענין הקבוצה וחיי הקבוצה אינו מטרה והישג בפני עצמו, אלא שלב והכנה ודרך לפיתוח האינדיבידואליות והיחידות שבכל אחד ואחד והתגשמותם באופן הכי טוב ובמדה הכי מלאה.</p>\n<p>הערכה יסודית זו של ענין הקבוצה נוגעת לא רק לאחר שהשיגו כבר סדר חיים קיבוצי מלא וצריך להחליט למעשה כיצד לנצל את יתרון הכחות ואיך להבליט אצל כל אחד את התכונות והכשרונות הפרטיים שלו בכל היקפם, אלא נוגעת היא ג\"כ תיכף בהתחלת חיי הקבוצה, כיון שלעתים תכופות ואולי גם ברוב הפעמים, עצם סדר חיי הקבוצה מוכרח, כאמור, לעורר התנגדות פנימית נגד הסדר והמשטר המתאמץ להכניע את היחיד בתור יחיד ולהפכו לחלק של הגוש, היינו הקבוצה. לעומת זאת, אם היחיד יודע שאין זה אלא שלב בהתפתחותו והדרך המגדילה את אפשריותו להגיע להישגים אינדיבידואליים גדולים יותר, על ידי כך שמשחררים אותו מדאגות בשלב נמוך מזה (בהנוגע לצרכיו ההכרחיים המושגים בקל יותר ובלי בזבוז כוחות וזמן הודות לפעולה המשותפת הקיבוצית), הרי הכרה זו לא זו בלבד שתבטל התנגדותו הטבעית אלא עוד זאת שתוסיף בו התלהבות והתמסרות במילוי תפקידיו בקבוצה.</p>\n<p>האמור לעיל נוגע לא רק להצלחת הקבוצה בכלל, אלא גם לתוכן החיים ואופן החיים בקבוצה, אשר כ' נוגע גם בזה בספרו, כגון היחסים שבין ההורים והבנים וכיו\"ב (וביותר - שעלול ההיזק להיות מרובה על השכר בשטח זה), כיון שיחסים אלו נמצאים בשטח החיים \"הרוחניים\" של האדם שבהם עצמאות היחיד חשובה ועיקר.</p>\n<p>עוד יש נקודה, שלדעתי חשובה, והיא בשנוי הרגש והיחס לקבוצה מצד מייסדי הקבוצה ומצד אלה שנולדו בקבוצה. שאם מייסדי הקבוצה, או אלו שבאו לחיי הקבוצה מקרוב לפי ערך, יכולים לקבל סיפוק נפשי בהכירם שהגיעו לזה, כמו שכותב, מחיים שונים בהחלט ובתכלית, ומסביבה חדורה השקפת עולם הפכית, והשיגו חיי קבוצה מתוך עמל ויגיעה וקרבנות וסיגופים וכולי, שכל זה מוסיף יוקר והערצה לדבר המושג, הנה אלה שנולדו בקבוצה או נתגדלו בה רואים סדר חיים זה כטבעי, ואצל אלה בודאי שההגבלות של חיי הקבוצה, שהוזכרו לעיל, בולטות יותר מאשר הצדדים החיוביים, מה שמחוייב לעורר אצלם אי-סיפוק נפשי או אפילו התמרדות, ועכ\"פ חיכוכים, כלפי אלה הכופים עליהם משטר קיבוצי (והבלטת הקבוצה כשלב והכנה - גם בזה תועיל).</p>\n<p>ומכאן הבעי' הנוקבת, שדרך אגב לא מצאתי בספרו מענה עלי': מה \"נותנים\" לדור הנולד בקבוצה בתור מטרה או אידיאל שירצו להגיע לזה אפילו מתוך עמל ויגיעה ומסירות נפש במסגרת חיי החברה?</p>\n<p>ואחרון אחרון, מובן שקראתי בהתענינות בסוף ספרו את \"פרקי חיים\". וגם בזה ארשה לי לבוא בהערה, אשר צר וחבל שלא הכניס ברשימותיו אלו</p>\n<p>האוטוביאוגרפיות - רשימה על דבר \"המקור\" שכתוצאה ממנו חבש כיפה בעת קראו פסוקי תנ\"ך בכנסת, בפרט - שבודאי שיער מראש שתהי' תגובה מצד שמאל, תגובה שלילית, ובכל זה עשה מעשה רב, והיסוד לזה בודאי מעורה ומונח בראשית ימי חייו, בבית אבא או זקנו, וכיו\"ב.</p>\n<p>כדרך בני ישראל לשלב ולקשר את הענינים שדנים עליהם עם ימי השנה, ובפרט ימי מועד וחג, הרי גם בראש השנה הדגישו חכמינו ז\"ל את האדם בתור יחיד, ולא רק בראש השנה הראשון יום ברוא אלקים אדם הראשון, אלא כלימוד והדגשת חכמינו: לפיכך נברא האדם יחידי, ללמדך (שבכל הדורות ובכל המקומות) נפש אחת כעולם מלא, והמשיכו עוד בזה ביאור שאין אחד מהם דומה לחברו, לפיכך כל אחד ואחד חייב לומר בשבילי נברא העולם. במלים אחרות, דוקא בזה שאין אדם דומה לחברו חשוב הוא כעולם מלא (סנהדרין סוף פ' ד'). ענין זה שימש גם נקודה תיכונית למכתבי לראש השנה המצורף בזה, אשר תקותי שיענין את מר.</p>\n<h4><i><b>ח'תתפה</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ג ע' 243 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>ומעלין בקודש:</b> ברכות כח, א. וש\"נ.</p>\n<p><b>כשם שאין:</b> ראה סנהדרין לח, א.</p>\n<p><b>אין האדם:</b> ראה מו\"נ ח\"ב פ\"מ. ח\"ג פכ\"ז.</p>\n<p><b>וכידוע שפעילות:</b> סוטה לד, א.</p>\n<p><b>שכלשון חכמינו:</b> אבות פ\"ג מ\"ב.</p>"],[1200970212,"ח'תתפו\n\n<p>ב\"ה, ימי הסליחות, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>אל בני ובנות ישראל אשר בכל מקום ומקום</p>\n<p>ה' עליהם יחיו</p>\n<p>שלום רב וברכה!</p>\n<p>ראש השנה איז באשטימט דורך דעם בורא (באשעפער) - ניט אין דעם טאג ווען די וועלט אין אלגעמיין איז באשאפן געווארן, נאר אין דעם טאג ווען אדם הראשון - דער מענש - איז באשאפן געווארן.</p>\n<p>די ערקלערנוג פון דעם:</p>\n<p>מיט דער באשאפונג פון דעם מענטשן איז די גאנצע בריאה פון אלע זעקס ימי בראשית ניט נאר פארענדיגט געווארן, נאר זי איז אויך דערגענצט און פארפולקאמט געווארן.</p>\n<p>דערמיט איז דערגרייכט געווארן די שלימות פון דער בריאה - ניט נאר מצד דעם וואס דער מענש איז די העכסטע באשעפעניש, נאר צוזאמען דערמיט אויך דערפאר וואס דער מענטש איז די באשעפעניש וואס <b>קען</b> און <b>דארף</b> און <b>וועט,</b> סוף כל סוף, ברענגען <b>אלע</b> אנדערע טיילן פון דעם באשאף צו <b>זייער</b> שלימות.</p>\n<p>וואס דאס ווערט דערגרייכט ווען דער מענטש ניצט אויס און אין דער <b>פולער</b> מאס אלע זיינע אייגענע כוחות און אלע כוחות פון דער נאטור - סיי אין דער וועלט פון <b>דומם</b> (אומבאוועגלעכע זאכן: ערד, מינעראלן, אד\"ג), סיי אין דער וועלט פון <b>צומח</b> (פלאנצן), סיי אין דער וועלט פון <b>חי</b> (לעבעדיגע באשעפענישן) - פאר טוב און קדושה.</p>\n<p>* * *</p>\n<p>די באשאפונג פונם מענטשן טיילט זיך אויס, צווישן אנדערע זאכן, ספעציעל אין דעם וואס נברא יחידי (ער איז באשאפן געווארן אן <b>איינצעלנער</b>), ניט ווי אנדערע באשעפענישן וועלכע זיינען באשאפן געווארן אין א גרויסער צאל.</p>\n<p>דאס ווייזט אונז און אונטערשטרייכט, אז <b>איין איינצעלנער</b> מענטש האט די מעגלעכקייט צו ברענגען די גאנצע בריאה צו איר תכלית און שלימות, ווי דער ערשטער מענטש - אדם הראשון - האט עס געטאן. אדם הראשון האט באלד נאך זיין באשאפונג, דעם ערשטן ראש השנה - אויפגעפאדערט און <b>אויסגעפירט</b> אז אלע באשעפענישן פון דער וועלט זאלן אנערקענען די הערשאפט פון דעם באשעפער, אויסרופנדיג:</p>\n<p><b>בואו נשתחוה ונכרעה, נברכה לפני ה' עושנו -</b></p>\n<p>(קומט, לאמיר זיך בוקן און בויגען, לאמיר קניען פאר ג-ט אונזער באשעפער), וואס דורך נשתחווה, דורך זעלבסט-ביטול און נאר דורך דעם קען א נברא זיך פאראייניגען און פאראיינציגן מיט דעם בורא, און אזוי ארום דערגרייכן די העכסטע שלימות.</p>\n<p>און אונזערע חכמים, זכרונם לברכה, לערנען אונז, אז פון אדם הראשון לערנט מען אפ און מען ווייס בנוגע <b>יעדער</b> מענטשן: לפיכך נברא האדם יחידי ללמדך - נפש אחת כאילו עולם מלא.</p>\n<p>דאס מיינט: יעדער איד, אויך אין אונזער צייט - אין וואס פאר אן ארט און צושטאנד ער זאל זיך ניט געפינען, האט ער די פולסטע מעגלעכקייט (ובמילא אויך די פליכט) שטייגן און דערגרייכן די העכסטע מדרגה פון שלימות און אויפטאן דאס זעלבע אין דעם עולם מלא - אין דעם גאנצן באשאף.</p>\n<p>ראש השנה - דער טאג פון דער באשאפונג פון דעם ערשטן און איינצלנעם מענטשן - דערמאנט יעדן אידן וועגן דער דאזיגער פליכט.</p>\n<p>ראש השנה - באווייזט די ניט ריכטיקייט פון די תירוצים פון די וועלכע ערפילן ניט זייער פליכט, אז ס'איז אוממעגלעך איבערצומאכן די וועלט, אדער אז זייערע עלטערן האבן זיי ניט געגעבן דעם נויטיגען חינוך און צוגרייטונג, אדער אז די וועלט איז א גרויסע און ער איז אליין איז ווי קען ער עפעס אויפטאן?</p>\n<p>ראש השנה - גיט די כוחות אויף צו דערפילן די פליכט, ווארום אין דעם טאג ווערט די גאנצע בריאה באנייט. עס הויבט זיך אן א ניי יאהר, מיט פרישע כוחות, ווי אין דעם טאג פון ערשטן ראש השנה.</p>\n<p>און ווי דער אינהאלט און סדר פון דער <b>תפלה</b> פון ראש השנה - וואס דער עצם בעטן באווייזט דאך, אז עס <b>קען</b> ערפילט ווערן די בקשה, און אז <b>די תפלה</b> קען דאס אויפטאן - אז יעדער <b>יחיד</b> בעט אין יעדער תפלה פון ראש השנה:</p>\n<p><b>מלוך על העולם כולו... וידע כל פעול כי אתה פעלתו -</b> אז דעם אויבערשטענס הערשאפט זאל אנערקענט ווערן איבער <b>דער גאנצער וועלט,</b> ביז אז <b>יעדער</b> זאך וועט וויסן אז ג-ט איז זיין באשעפער.</p>\n<p>* * *</p>\n<p>געווען צייטן ווען דער אויבנדערמאנטער געדאנק אז איין מענש קען \"איבערמאכן\" די וועלט - האט ארויסגערופן ספיקות און עס האט זיך געפאדערט ברענגען אויף דעם ראיות און באווייזן א.ז.וו.</p>\n<p>גראדע אין אונזער תקופה, דארף מען ליידער ניט זוכן א סאך ראיות צו איבערצייגען, אז ווען ניט דער אויבערשטער וואס ער איז דער מלך העולם און ה' מלך - תכון תבל בל תמוט (ער קיניגט אין א וועג, אז די וועלט איז באפעסטיגט און וועט ניט פאלן) - קען איין מענטש צעשטערן ר\"ל די גאנצע וועלט.</p>\n<p>אויב דאס איז אזוי אין דעם צד פון פארקערט פון גוט - איז דאך זיכער, אז אין צד הטוב קען איין מענטש אויפטאן פיל, פיל מער. ווארום באמת - איז דאך די בריאה גוט בפנימיות, און דערפאר מער גענויגט צו גוט ווי צום היפך.</p>\n<p>* * *</p>\n<p>זאל דער אויבערשטער העלפן <b>יעדער איינער און איינע</b> אנצונעמען אין דעם טאג פון ראש השנה פעסטע החלטות (באשלוסן) אין דעם גייסט פון ראש השנה, ווי אויבנדערמאנט; און די דאזיגע החלטות זאלן זיי מקיים זיין בפועל אלע טעג און יעדן טאג פון דעם קומענדן יאהר.</p>\n<p>דעם נשתחווה פארן אויבערשטן, וואס דריקט זיך אויס אין אלע ענינים פון דעם טאג טעגליכן לעבן, דורך מקיים זיין די מצות פון דעם אויבערשטן, ביז אז - <b>בכל</b> דרכיך דעהו (אין אלע דיינע וועגען זאלסטו אים דערקענען).</p>\n<p>און אויפטאן דאס זעלבע אין דער ועולט ארום זיך,</p>\n<p>לויט דעם אינהאלט פון ראש השנה, וואס ער איז ניט נאר דער אנהייבס פון יאהר, נאר בעיקר - דער \"ראש\" (קאפ) פונ'ם יאהר,</p>\n<p>וואס אזוי ווי די קאפ פירט אן מיט יעדער אבר פון דעם גאנצן גוף, אזוי דארף דער חיות און די החלטות פון ראש השנה אנפילן און אנפירן מיט די טעג פון יאהר.</p>\n<p>און דאמאלס איז דער גאנצער גוף - (יאהר) - א געזונטער אין אלע הינזיכטן.</p>\n<p>בברכה לכתיבה וחתימה טובה לשנה טובה ומתוקה.</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ח'תתפו</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ט ע' 438.</p>\n<p><b>מכתב לר\"ה תשי\"ד:</b> נדפס לעיל ח\"ז אגרת ב'רלח.</p>\n<p><b>מכתב לר\"ה... תשט\"ז:</b> נדפס לעיל חי\"א אגרת ג'תתג.</p>\n<p><b>די ערקלערונג: </b>בקצרה ובאופן אחר קצת - ראה מכתב לר\"ה תשי\"ד, תשט\"ז.</p>\n<p><b>אויך דערגעצנט: </b>בחדא\"ג מהרש\"א (ר\"ה כז, א): כאילו לא נברא שום דבר קודם בריאת האדם. ועיין המשך זה היום דשנות תש\"ד, תש\"ט.</p>\n<p><b>ברענגען אלע אנדערע: </b>ראה ב\"ר (פי\"א, ו): <b>כל</b> מה שנברא כו' צריכין עשי'. בלקו\"ת נשא כו, ב.</p>\n<p><b>אין איינקלאנג מיט דעם רצון: </b>ראה אבות ספ\"ו. יומא לח, א.</p>\n<p><b>נברא יחידי: </b>משנה סנהדרין ספ\"ד.</p>\n<p><b>אדם הראשון האט: </b>זח\"ג ס\"פ אמור. וראה ג\"כ פדר\"א פי\"א.</p>\n<p><b>ניט ריכטיגקייט: </b>להעיר ג\"כ מרמב\"ם הל' תשובה פ\"ה, וא\"ו. קונטרס ומעין מי\"ג ואילך.</p>\n<p><b>וידע: </b>ראה תניא ספ\"ג.</p>\n<p><b>כל פעול: </b>עולם העשי' (סי' האריז\"ל).</p>\n<p><b>ה' מלך: </b>אמרו אדם ביום שנברא כשהמליך אותו וכל הבריות אחריו (פדר\"א פי\"א).</p>\n<p><b>קען איין מענש: </b>להעיר מקידושין מ, ב.</p>\n<p><b>פיל מער: </b>ראה יומא לח, ב.</p>\n<p><b>די בריאה גוט: </b>בראשית א, לא. וראה מו\"נ ח\"ג פכ\"ה (ופי\"ג).</p>\n<p><b>בכל דרכיך דעהו: </b>ראה טושו\"ע או\"ח סרל\"א.</p>\n<p><b>\"ראש\" (קאפ): </b>עטרת ראש בתחלתו.</p>"],[1200970213,"ח'תתפז\n\n<p>ב\"ה, ימי הסליחות ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>המשתתפים במסיבת הסיום דמסכת שבת<br>\nאשר בכפר<br>\nארגנטינה (ניר צבי) - שליט\"א</p>\n<p>שלום וברכה!</p>\n<p>הפ\"נ שלהם נתקבל.</p>\n<p>ולקראת השנה החדשה הבאה עלינו ועל כל ישראל לטובה ולברכה, הנני בזה להביע ברכתי להם ולכל אשר להם ברכת כתיבה וחתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות.</p>\n<p>בכבוד ובברכה - שע\"פ סיום מס' שבת - יתעסקו מתוך (שבת) מנוחה ומתוך הרחבה וגדלות (כהנהגת בי ריש גלותא) במצות ובהכנות להן, כדי לטהר אשה - זו כנסת ישראל - לבעלה - זה הקב\"ה ע\"י שיהיו כל עשיותיהם במדידה דמצוה (בעניני מצוה) ואפילו בהתעסקותם בעלמא - יעשו מזה דיני תורה (שבעל פה) וכביאור חז\"ל (בתושבע\"פ) בהנהגת בכל דרכיך דעהו, ובברכת כוח\"ט.</p>\n<h4><i><b>ח'תתפז</b></i></h4>\n<p><b>וכביאור חז\"ל:</b> ברכות סג, א.</p>"],[1200970214,"ח'תתפח\n\n<p>ב\"ה, ימי הסליחות, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>האברך עזרא בנימין שי'</p>\n<p>שלום וברכה!</p>\n<p>... לשאלתו ע\"ד בי' בתניא - עיין (סוף) הקדמת הרמב\"ן לפי' עה\"ת.</p>\n<h4><i><b>ח'תתפח</b></i></h4>\n<p>נדפסה ב\"היכל מנחם\" חלק א ע' עב והושלמה עפ\"י צילום האגרת.</p>\n<p><b>האברך עזרא בנימין שי':</b> שוחט. אגרות נוספות אליו - לעיל ח'תשג, ובהנסמן בהערות שם.</p>\n<p><b>לשאלתו:</b> מענה על שאלה במה שביאר בקונטרס עץ חיים בהוספות ע' 87 דמאי שנא תניא מספר אחר שנכתב ברוה\"ק אשר כיון שנכתב ברוה\"ק הרי נכלל בו בדרך ממילא כל הסברה והשכלה שהיא נכונה כשלעצמה גם אם המחבר לא התכוין אלי'.</p>"],[1200970215,"ח'תתפט\n\n<p><i>[תשכ\"ד]</i></p>\n<p>... לההערות בספרי ר\"פ ברכה: מה שאמר הקב\"ה לבני עשיו (על השאלה מה כתיב בתורה) - לא תרצח ועד\"ז לבני עמון ומואב - לא תנאף ולבני ישמעאל - לא תגנוב, והרי לא זהו החידוש במתן תורה, כי כהנ\"ל הם מז' מצות ב\"נ.</p>\n<p>- ולהעיר מיבמות (מז, ב) אסיר לן ע\"ז וראה שם במפרשים.</p>\n<p>י\"ל כי הוכרח לומר להם דוקא ע\"ד מצות אלו. כי הם דוקא החמורות בשבילם היפך ענינם (כדמוכח מהמענה דכאו\"א מהנ\"ל \"כל עצמו\").</p>\n<p>ואף שבלאה\"כ נצטוו ע\"ז (בז' מצות ב\"נ) - י\"ל בפשטות שהרי בשעת מ\"ת שאלם הקב\"ה היקבלו תורה <b>ברצון</b> וע\"ז ענו כל עצמו כו' ולכן אי\"א לקבל כו'.</p>\n<p>ועפ\"ז מובנת בפשטות המכילתא (יתרו כ, ב) דגם שם איתא כהנ\"ל בספרי ומסיים: ארשב\"א אם בז' מצות שנצטוו ב\"נ שקבלו עליהן אינן יכולין לעמוד בהן ק\"ו למצות שבתורה. ועד\"ז משמע גם בספרי שמסיים יכול שמעו וקבלו (התורה) ת\"ל ואותם לא יעשו ואומר כו' אלא אפילו ז\"מ שקיבלו עליהם ב\"נ לא יכלו לעמוד בהם עד שפרקום ונתנום לישראל. וק\"ל.</p>\n<p>לתרץ הספרי שכוונת הכתוב בהלא תרצח כו' היינו מה שמוסיף בציווי זה לבנ\"י - על האיסור דשפ\"ד דב\"נ - דוחק קצת, דא\"כ העיקר חסר מן הספר. אלא שקצת ראי' לזה ממענה בני עמון ומואב בשלילת לא תנאף ממש\"נ ותהרינה שתי בנות לוט מאביהן, דניתוסף איסור זה בג\"ע במ\"ת, אבל מותר לב\"נ. כן ממענה בני עשיו ממש\"נ על חרבך תחי', דפשיטא דלא תהי' ברכת יצחק לעבור על מצות ב\"נ.</p>\n<p>למרז\"ל בשמו\"ר (פ\"ל, ט) דלעכו\"ם ניתנו מצות גולמיות - יש להעיר מפי' הרמב\"ן (וישלח לד, יג): ועל דעתי הדינין שמנו כו'. וראה ג\"כ חולין (צב, סע\"א) ל' מצות שקיבלו עליהם ב\"נ כו'.</p>\n<h4><i><b>ח'תתפט</b></i></h4>\n<p>האגרת היא להג\"ר ישראל יצחק פיקרסקי. אגרות נוספות אליו - לעיל ח\"כ ז'תקעב. חי\"ט ז'רמב.</p>"],[1200970216,"ח'תתצ\n\n<p>ב\"ה, ערב חג הסכות, בעלות המנחה,</p><p>ה'תשכ\"ה. ברוקלין, נ.י.</p>\n<p>הרה\"ג אי\"א חו\"ב נבון ומסביר איש</p>\n<p>האשכולות ורב רבנן</p>\n<p>וכו' מהרי\"ד הלוי - וכל המשפחה - שליט\"א</p>\n<p>ת\"ח על מכ' הברכה מיום השלישי עיוהכ\"פ, יום שלימות דוינחם ה', ברצון דוקא, ולא עוד אלא ששכרו הרבה ומעלתו גדולה כו', יום שמחת לבו.</p>\n<p>וכבר מילתי' דמר אמורה ואברכה מברכיך, בברכת ה' שהיא מרובה על העיקר.</p>\n<p>ויהי רצון אשר בקרוב בימינו נזכה, בתוך כלל ישראל, לראות בנחמת ציון וירושלים,</p>\n<p>ולקיום היעוד בלע גו' ומחה ה\"א דמעה מעל כל פנים גו',</p>\n<p>והקיצו ורננו שוכני עפר שיחיים ה' בטל של אור גדול של מעלה.</p>\n<p>בהוקרה בכבוד ובברכת החג ששמחתו משולשת בתורה.</p>\n<p>בהמשך להמדובר - מצאתי לאח\"ז בפיה\"מ לדמאי (פ\"א, מ\"ב) דלא אכלתי באוני היינו קודם הקבורה (וכ\"פ הרא\"ש סוף מע\"ש*).</p>\n<p>ולסיום המכ' דמר לראות כהן כו' - וללוי אמר, להעיר ממש\"כ האריז\"ל (בלקוטי תורה ובשער הפסוקים ליחזקאל) שלעת\"ל יהיו הלוים כהנים. - ועיין תניא פ\"נ שהוסיף בזה \"שהלוים <b>של עכשיו יהיו</b> כהנים לעתיד\" - וי\"ל דבזה מיישב הקושיא שהרי התורה אמרה לנו ולבנינו עד עולם [רמב\"ם הל'] יסוה\"ת רפ\"ט. ומבאר דאלה <b>שעכשיו</b> (ולא בזמן ההוא) הם לוים יהיו (כי יולדו) כהנים לעתיד.</p>\n<p>זה עתה ראיתי בפיה\"מ שהו\"ל הרב קאפח (ירות\"ו. תשכ\"ג) שמעיר המו\"ל שבכת\"י שביד המו\"ל מחק הרמב\"ם (?) הנוסח שהעתקתו בדפוסים שלנו כנ\"ל, וכתב בשולים נוסח שמעתיקו \"ביום המיתה בלבד הוא אונן מה\"ת\" - כלשונו ביד החזקה. ומסיימים בטוב:</p>\n<p>בריש ס' המאמרים תרכ\"ט (ברוקלין, תשי\"ט) מבואר (וכנראה מיוסד על מאמר אדמו\"ר הצמח צדק) איך שברכתו של ה' יש בה גם המעלה דתפלה, יהי רצון, להמשיך רצון <b>חדש</b> לרפאות ולברך.</p>\n<h4><i><b>ח'תתצ</b></i></h4>\n<p><b>מהרי\"ד הלוי:</b> סולוויצשיק, בוסטון.</p>\n<p><b>מכ' הברכה... עיוהכ\"פ:</b> ברכת נחום אבלים על פטירת אמו הרבנית הצדקנית מרת חנה ע\"ה שנפטרה ביום הש\"ק ו' תשרי בעלות המנחה.</p>\n<p><b>יום שמחת לבו:</b> ראה תענית כו, ב.</p>\n<p><b>שהיא מרובה:</b> ב\"ר פס\"א, ד. וראה בארוכה לקו\"ש ח\"ה ע' 422 ואילך.</p>\n<p><b>ויהי רצון:</b> ראה גם אגרת שלאח\"ז, ובהנסמן בהערות שם.</p>\n<p><b>בהמשך להמדובר:</b> בעת הביקור לניחום אבלים. וראה גם לקמן אגרת ח'תתצא.</p>\n<p>ח'תתצט.</p>\n<p><b>ועיין תניא פ\"נ:</b> ראה גם שיעורים בספר התניא שם הערה 15.</p>\n<p><b>וכנראה מיוסד:</b> ראה בהנסמן בסה\"מ שם בתחלתו - הוצאת תשנ\"ב.</p>\n<p><b>מיוסד... הצ\"צ:</b> ראה ד\"ה כה תברכו באוה\"ת נשא ע' ער.</p>\n<p>*) פ\"ה מי\"ב (ופליג על הרע\"ב שם).</p>"],[1200970217,"ח'תתצא\n\n<p>ב\"ה, ערב חג הסוכות, בעלות המנחה,</p><p>ה'תשכ\"ה. ברוקלין, נ.י.<br>\nהרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ צנמ\"ס<br>\nכו'<br>\nמו\"ה שלמה יוסף שי'</p>\n<p>שלום וברכה!</p>\n<p>ת\"ח בעד דברי הנחומים ששלח כת\"ר,</p>\n<p>ויהי רצון אשר בקרוב בימינו נזכה, בתוך כלל ישראל, לראות בנחמת ציון וירושלים,</p>\n<p>ולקיום היעוד בלע גו' ומחה ה\"א דמעה מעל כל פנים גו',</p>\n<p>והקיצו ורננו שוכני עפר שיחיים ה' בטל של אור גדול של מעלה,</p>\n<p>לפלא קצת שלא מצאתי ציון לפיהמ\"ש (דמאי א, ב) באנצ' [מסייע לפי' הרא\"ש (סוף מע\"ש)] דמותר במע\"ש לאחר הקבורה [אלא שבפיה\"מ שהו\"ל הרב קאפח כותב - שהרמב\"ם העביר קולמוס ע\"ז].</p>\n<p>בברכה לבשורות טובות ולחג שמח</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתצא</b></i></h4>\n<p>חלקה נדפס בלקו\"ש ח\"י ע' 212 וחלקה בחכ\"ד ע' 522 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>מו\"ה שלמה יוסף:</b> זוין. אגרות נוספות אליו - לעיל ח'תשלא, ובהנסמן בהערות שם.</p>\n<p><b>בטל של אור:</b> ראה גם לעיל חכ\"ב אגרת ח'שז, ובהנסמן בהערות שם.</p>\n<p><b>באנצ':</b> אנציקלופדי' תלמודית כרך ב' ערך אנינות ע' סו ציון 11.</p>\n<p><b>אלא שבפיה\"מ:</b> ראה גם אגרת שלפנ\"ז. לקמן אגרת ח'תתצט.</p>\n<p><b>בעלות המנחה: </b>ראה ברכות ו, ב. ונת' באור התורה להצ\"צ וישלח (רלד, ב) <b>וש\"נ.</b> <b>בלע גו'.. פנים גו': </b>ישעי' כה, ח. סוף מו\"ק.</p>\n<p><b>הקיצו ורננו: </b>ישעי' כו, יט.</p>\n<p><b>בטל של אור: </b>זח\"א קיח, סע\"א. וראה ג\"כ חגיגה יב, סע\"ב. כתובות קיא, ב. תניא ספל\"ו.</p>"],[1200970218,"ח'תתצב\n\n<p>ב\"ה, ערב ר\"ח מ\"ח, תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>מרת מרים תחי'</p>\n<p>ברכה ושלום!</p>\n<p>מאשר הנני קבלת מכתבה מי\"ח תשרי.</p>\n<p>ומאחר שבאים הננו מחדש תשרי, אשר סיומו וחותמו זמן שמחתנו וביחוד שמחת תורה, אשר ענינם לקחת משמחה זו על כל השנה כולה,</p>\n<p>יהי רצון שיהי' כן בתוכן מכתבה ובכלל ותבשר טוב בטוב הנראה והנגלה.</p>\n<p>בברכה לבשו\"ט בכל האמור</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>ש.מ. סימפסון</p>\n<p>מזכיר</p>\n<p>בטח ממשיכות - ומסיפות כהציווי להעלות בקודש - בפעולות נשי חב\"ד.</p>\n<h4><i><b>ח'תתצב</b></i></h4>\n<p><b>מרת מרים:</b> ובר, ירושת\"ו.</p>\n<p><b>אשר ענינם:</b> ראה גם אגרת ח'תרפח, ובהנסמן בהערות שם.</p>\n<p><b>כהציווי:</b> ברכות כח, א.</p>"],[1200970219,"ח'תתצג\n\n<p>ב\"ה, ל' תשרי, תשכ\"ה</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מיום השני, בו כותב אודות הבחורה תחי' אשר נפגשה עם א\"י וכו' ולאחרי רוב הדבורים ואריכות זמן, אומר הא\"י שרוצה להתגייר כדרוש ומוכן לקבל עליו עול מצות וכו' וכו', ומסופק איך יהי' היחס להצעה האמורה, כיון שתחלת הענין בא ע\"י ההיכירות עם הבחורה האמורה וכו'.</p>\n<p>והנה בכלל אין עניני לפסוק דינים, והרי כו\"כ הראוים לשמם לזה בעיר רבתי כנויארק, ובכ\"ז כיון שכבר כתב, ובתור הצעת סברא, ולא פסק דין, אבוא בשורות דלהלן.</p>\n<p>כנראה ממכתב כת\"ר השייכות שבין הנ\"ל חזקה ביותר ומי יודע וכו', ולאידך גיסא אפילו בנוגע לגירות שאין בה כל פקפוק, ידוע מאמר חז\"ל אודות סורם וכו', ובכהאמור בודאי יש מקום גם לשאלת פגם המשפחה וכו'.</p>\n<p>ולכאורה המוצא הכי ישר בהאמור הוא, להציע להא\"י, כיון שלדבריו - כוונתו גירות לשמה, ובודאי גם הוא מודה שאי אפשר לשער מראש עול המצות בחיי היום יום עד שמנסים זה בפועל, ובפרט שגם הוא מודה שתחלת הסיבה היתה שלא לשמה, ובמילא משוחד הוא בההשערה אודות עצמו שיקיים כל האמור בפועל,</p>\n<p>לכן העצה הכי ישרה, שההתחלה תהי' הנהגתו בחיי היום יומים עפ\"י השו\"ע משך זמן חשוב, ושבמשך זמן זה לא יבלבלו זא\"ז (הוא והבחורה) ע\"י פגישות וכו', ומה טוב שלא יהיו בעיר אחת, ולאחרי נסיון האמור יוכל להחליט בעצמו, האם באמת יחי' חיים כדת משה וישראל או וכו',</p>\n<p>ומה טוב שבינתים ישתדלו שהבחורה תסע לאה\"ק ת\"ו וכיו\"ב, וההסברה כאמור בכדי שכל אחד מהם ישער בעצמו אמיתת כוונתו בהאמור.</p>\n<p>כבקשת כת\"ר נשלח המכתב מבלי לחכות על התור.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתצג</b></i></h4>\n<p><b>א\"י:</b> אינו יהודי.</p>\n<p><b>מאמר חז\"ל:</b> בבא מציעא נט, ב.</p>"],[1200970220,"ח'תתצד\n\n<p>ב\"ה, ל' תשרי, אדר\"ח מ\"ח, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>ובעמדנו ביום איחוד חדש השביעי, חדש המשובע בכל טוב, וחדש מרחשון, חדש ירידת הגשמים לברכה לחיים ולשובע,</p>\n<p>אשר הגשמים וירידתם הם תחלה ראש ומקור לכל הברכות וירידתם והמשכתם למטה,</p>\n<p>יהי רצון אשר הכתיבה וחתימה טובה של כל אחד ואחת מבני ישראל, בתוככי כללות ישראל, שהייתה בחדש השביעי תומשך למטה בטוב הנראה ונגלה לנו, בהמצטרך לכל אחד ואחת בגשמיות וברוחניות.</p>\n<p>וכחותם המועדים של חדש השביעי, זמן שמחתנו -</p>\n<p>מתוך שמחה כפולה, שמחת הנותן, הוא השי\"ת מקור הברכות, ושמחת</p>\n<p>המקבל - עמו בני ישראל.</p>\n<p>בברכה לבשו\"ט.</p>\n<h4><i><b>ח'תתצד</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש חכ\"ד ע' 542.</p>\n<p><b>אדר\"ח מ\"ח: </b>להעיר דלדעת הט\"ז ולגרסת הדפוס שבידינו - דוקא אדר\"ח מ\"ח מצוין בשו\"ע (או\"ח סתכ\"ח) <b>ודלא</b> כבכל החדשים (וכקושית הפר\"ח).</p>\n<p><b>השביעי חדש המשובע: </b>ויק\"ר פכ\"ט, ח.</p>\n<p><b>חדש ירידת הגשמים: </b>ראה ערוך ע' מרחשון. רד\"ק (מ\"א ו, לח). ולהעיר מרש\"י ד\"ה בשלשה (תענית ד, ב), שו\"ע אדה\"ז סקי\"ז סוס\"א: וה\"ה אם בארצות אלו כו'.</p>\n<p><b>הם תחלה ראש ומקור: </b>בספרי לדברים (יא, יד): ונתתי מטר גו' ברכה שכל הברכות כלולות בה. וראה ג\"כ ויקרא (כו, ג-ד) וברמב\"ן שם. דברים (כח, ב) ובדב\"ר פ\"ז, ו. תענית ז, ב. ובכ\"מ.</p>\n<p><b>וברוחניות: </b>ראה לקו\"ת רד\"ה ביום הח' שלח (דברים פו, ג). שם (צו, א).</p>\n<p><b>שמחה כפולה: </b>עיין לקו\"ת דברים פח, ד.</p>\n<p><b>עמו: </b>ראה לקו\"ת שם פז, ג.</p>"],[1200970221,"ח'תתצה\n\n<p><i>[תחלת מר חשון תשכ\"ה]</i></p>\n<p>להערתו במרז\"ל דאין המת משתכח מן הלב: א) ל' יום (מו\"ק ח, א). ב) י\"ב חודש (ברכות נח, ב),</p>\n<p>הענין עצמו מוכיח דבמו\"ק המדובר בשכחת הצער ובברכות - בשכחת האיש.</p>\n<p>[ועפ\"ז יש להסביר: א) דדוקא בזה צ\"ל <b>גזירה</b> שישתכח (רש\"י וישב לז, לה). ב) השינוי במרז\"ל הנ\"ל, דבברכות הל' <b>אלא</b> - שחוזר מדלעיל - מטבעיות הענין].</p>\n<p>אלא שמעולם תמהתי על שאין מחלקים בהנ\"ל בנוגע לאו\"א <b>דחיוב</b> האבלות (צער - ואי\"ז שייך ל\"להצטער\" (רש\"י סוכה כה, א ד\"ה טרדא) שאינו חייב בו). הוא יב\"ח.</p>\n<p>ומסיימים בטוב.</p>\n<h4><i><b>ח'תתצה</b></i></h4>\n<p>האגרת היא למו\"ה הלל מדלי', ונכתבה על גליון מכתבו מאור לכ\"ו תשרי תשכ\"ה. אגרות נוספות אליו - לעיל ח\"כ ז'תריב, ובהנסמן בהערות שם.</p>\n<p><b>להערתו במרז\"ל:</b> במכתבו: לאות חבה יתירה ארשום: במוע\"ק (ח, א) שנינו: \"לא יעורר אדם וכו' קודם הרגל ל' יום\", וגרסינן עלה: \"מ\"ש ל' יום? - אר\"כ אר\"י א\"ר מעשה וכו'; ושמואל אמר לפי שאין המת משתכח מן הלב ל' יום וכו' וא\"ב דקעביד בחנם\", עכ\"ל.</p>\n<p>ולכאו' צ\"ע מדוע לא חייש רב דקא אתי למיספדי ברגל אפי' בדקא עביד בחנם? ועוד קושית התוס'.</p>\n<p>ואמר אבא מארי זצ\"ל דרב לשיטתי' אזיל בברכות (נח, ב): \"אין המת משתכח מן הלב אלא לאחר י\"ב חדש וכו'\". א\"כ אין נ\"מ אם לרגל זו או אחרת, ולכן בדקעביד בחנם מותר, ואינו אסור רק משום טעמא דמעשה האמור במוע\"ק.</p>"],[1200970222,"ח'תתצו\n\n<p>ב\"ה, ו' מרחשון, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לכבוד הוו\"ח אי\"א נו\"מ בחור מעם ומורם<br>\nמעם ודורש טוב<br>\nלעמו בעל מדות תרומיות ענף עץ אבות<br>\nמו\"ה שניאור זלמן<br>\nשליט\"א</p>\n<p>שלום וברכה!</p>\n<p>זה עתה ראיתי הידיעה בעתון שאחיו שי' קבל רשיון לצאת ממדינתו להתיישב באה\"ק ת\"ו. וכנראה שזהו המשך להידיעה שכתב לי כ' במכתבו הקודם. ואברכה את כ' בברכת מזל טוב, והרי שמחת כל אחד מישראל היא שמחת הכלל, ובפרט אשר נפש אחת מישראל היא כעולם כולו, שזהו מהטעמים שנברא האדם יחידי.</p>\n<p>ויהי רצון אשר מגאולת הפרט נגיע לגאולת הכלל, ויציאתו של אחיו שי' תהי' הקדמה לפתיחת שערי המדינה ההיא, פתיחה לרחבה ובקרוב, ומתוך חסדי ה' כי לא תמו.</p>\n<p>ומבשורה לבשורה, בשורה משמחת מכאן שסו\"ס יצא מהדפוס הספר \"מאמרי אדמו\"ר הזקן - תקס\"ב, ונשלח לכ' בפ\"ע.</p>\n<p>כמדומה לי, כשהראיתי את הכת\"י לכ' הערתי שהוא כת\"י מיוחד במינו, שהמאמרים הם של אדמו\"ר הזקן, הכת\"י של אדמו\"ר האמצעי, והי' ברשותו של הצ\"צ, המעיד על הכת\"י שהוא של אדמו\"ר האמצעי, וגם הכניס בו הגהות בכמה מקומות. שכל זה מעיד על אמתיות הענינים וכו' עד שלולא זחלתי ואירא לחוות דעה מוחלטת בדברי דא\"ח ועל אחת כמה וכמה בנוגע מאמרי אדמו\"ר הזקן, שאפילו אדמו\"ר הצ\"צ אשר לבו כלב הארי אומר עליו \"כשם שבין קד\"ק לחולי חולין כך גבהו דרכיו מדרכינו\" (צ\"צ יו\"ד סי' ס\"ג, אות ח) והמדובר שם בנוגע לנגלה דתורה ועאכו\"כ בפנימי' התורה - הייתי אומר שהנחות כמה מאמרים אשר בספרי מאמרי אדה\"ז תקס\"ב מתאימות יותר ועולות על הנחות המאמרים אשר נדפסו בלקוטי תורה, אף על פי שנדפסו בימי הצ\"צ וכנראה בעריכתו. ואולי בעת הדפסת הלקו\"ת לא הי' ספר כת\"י זה אצל הצ\"צ.</p>\n<p>מכתבי הקודמים בטח נתקבלו במועדם, וכן ספר השיחות תש\"ב שמסרתי על ידי הרב מחיפה הרב דוד שי' אסף שהי' בביקור כאן וחזר לאה\"ק ת\"ו.</p>\n<p>דרך אגב, אף שחששתי לזמנו של כ' בידעי טרדותיו והי' לבי מהסס במסירת הספר לכ' אישית על ידי הרב אסף, אבל לא יכולתי להשיב פניו בזה, בפרט אחרי אשר הראני שנמצא הצירוף \"חב\"ד\" - חכמה בינה דעת ביחד - בדברי המורה הגדול הוא הרמב\"ם, בספרו משנה תורה, הל' יסודי התורה (פרק ב' הלכה ב') -</p>\n<p>הלכה הפוסקת בהחלט שמוכרח לימוד יסודי התורה בהתבוננות, בחכמה בינה דעת, ולא עוד אלא שנוגע זה לקיום המצוות בפועל, ומדבריו הברורים והגלויים שם: היאך היא הדרך לאהבתו ויראתו (של השם) בשעה שיתבונן האדם כולי ויראה מהם חכמתו כולי ומתאוה תאוה גדולה לידע השם הגדול.</p>\n<p>וידוע דיוק המוחלטי של הרמב\"ם בדבריו בספרו האמור, ובפרט כשהמדובר ביסודי התורה, שמזה מובן שלשונו \"היאך היא הדרך\" שוללת האפשריות לבוא לאהבת ה' ויראתו בדרך אחרת, והקדים לזה (הרמב\"ם) אשר האהבה והיראה הן מצוות מן התורה וכביאור הפירוש על אתר שם הן גם היסודות לקיום המצוות.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתצו</b></i></h4>\n<p>חלקה נדפס בלקו\"ש ח\"י ע' 235 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מו\"ה שניאור זלמן:</b> שזר. אגרות נוספות אליו - לעיל ח'תרפב, ובהנסמן בהערות שם.</p>\n<p><b>נפש אחת:</b> סנהדרין לז, א.</p>\n<p><b>הכת\"י של אדמו\"ר האמצעי:</b> ראה בפתח דבר למאמרי אדה\"ז - תקס\"ב ח\"א. וברשימת המאמרים דשנת תקס\"ב במאמרי אדה\"ז - תקס\"ב ח\"ב ע' תרסג.</p>"],[1200970223,"ח'תתצז\n\n<p>ב\"ה, ט' מרחשון, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לכבוד מר א. רון שי'</p>\n<p>שלום וברכה!</p>\n<p>הנני לאשר בתודה קבלת מכתבו מיום ה' בחשון, בו כותב ע\"ד חלוקי דעות בין המנהלים של שני בתי ספר בירושלים.</p>\n<p>הברקתי להרב זוין שליט\"א ובקשתיו אשר בהשתתפות ידידינו היודעים פרק בחינוך הנמצאים במקום ומכירים אישית את שני המנהלים וכו' יתווכו ביניהם ויסדרו הענין בכי טוב. ומובטחני אשר לא יאחרו לדון בדבר בשימת לב הראוי' וימצאו הפתרון הנכון לטובת התלמידים-ות (שהרי סו\"ס הם העיקר), וגם לטובת ההנהלה וכולי, ועוד וגם זה עיקר באופן שתהי' הסכמה משני המנהלים, שהרי בשטח החינוך בפרט חשוב ביותר שכל העובדים בו יעבדו מתוך שביעת רצון והסכמה מלאה ולא בדרך הכרח, כיון שהתלמיד רגיש הוא ומגיב לא רק על דברים וענינים שבגלוי אלא גם על רגש הלב של המורה והמחנך, מצב רוחו, היחס שלו וכולי. ובודאי לדכוותי' דמר האריכות אין בה צורך.</p>\n<p>נעם לי לראות במכתבו התענינות כ' בבתי ספר האמורים, ומזה דן אני גזרה שוה על דבר התענינותו גם בשאר בתי הספר. וכאן מקום אתי להביע לו תודה מיוחדת על הביאו לתשומת לבי הבעי' של שני בתי הספר האמורים במיוחד שמפרש אני את זה כיחס של אהדה וידידות נאמנה לחב\"ד ועניני'. ועל פי הוראת חכמינו ז\"ל להעלות בכל דבר טוב, אקוה אשר גם ביחס זה יתוסף עוד יותר, ותודה לבבית למפרע, נוסף על העיקר אשר שכר מצוה מצוה.</p>\n<p>ומענין לענין באותו ענין, אף שאיני יודע אם נכנס זה בשטח פעולות מר, והוא בנוגע לביה\"ס במנחת, אשר כתבו לי קס\"ד וסברה לחסל בו את הכתות הגבוהות (על מנת להעבירן לאזבסטונים). ואף שכמובן שמעבר לים קשה להיות בקי בבעי' האמורה לכל פרטי', אבל הרי בודאי שהאוכלוסי' במנחת תגדל בעתיד הקרוב, ולכן אדרבה השעה דורשת להרחיב מסגרת החינוך שבהוה שתוכל לקלוט גם ילדי המתיישבים החדשים, והרי הוספת האוכלוסי' אינה מוגבלת לתחילת שנת הלמודים, וכל השנה זמנה הוא.</p>\n<p>ארשה לעצמי לצרף בזה העתק מכתבי-כללי לראש השנה הזאת, שתקותי שיענין את מר. והשייכות להכתוב לעיל - אם תמצא לומר שצריכה להיות שייכות - גם היא פשוטה, והיא שעל פי תוכן המכתב האמור ביכולת מר לפעול בשני הענינים האמורים כאן הרבה יותר משמשער.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתצז</b></i></h4>\n<p><b>הברקתי להרב זוין:</b> ראה גם אגרת ח'תתצט.</p>\n<p><b>הוראת חכמינו:</b> ברכות כח, א. וש\"נ.</p>\n<p><b>מכתבי כללי:</b> דלעיל ח'תתפו.</p>"],[1200970224,"ח'תתצח\n\n<p>ב\"ה, י\"ב מ\"ח תשכ\"ה</p><p>ברוקלין.</p><p>הנהלת בית הכנסת \"הראשון\" אשר בכפר<br>\nחב\"ד<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבם מכ\"ז תשרי, בו כותבים אודות בתי הכנסיות בכפר חב\"ד, מיסודו ובהנהלתו של כ\"ק מו\"ח אדמו\"ר נשיא ישראל, התפתחותם והרחבתם וכו'.</p>\n<p>ומובן שבכגון זה צ\"ל התייעצות כולם יחד - הנהלות בתי הכנסיות - וועד הרוחני בראשיתו של הרה\"ג הרה\"ח בעל מדות וכו' שליט\"א מרא דאתרא,</p>\n<p>בה ידונו ע\"ד האמור והקשור בזה.</p>\n<p>וגדול זכות הרבים אשר יכוונו בהחלטותיהם לתכלית האמיתית, כיוון לרצון כ\"ק מו\"ח אדמו\"ר מייסד הכפר ומנהלו.</p>\n<p>בברכת הצלחה בכל עניני בית הכנסת בתוככי כללות עניני כפר חב\"ד</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתצח</b></i></h4>\n<p><b>הרה\"ג הרה\"ח:</b> שניאור זלמן גרליק.</p>"],[1200970225,"ח'תתצט\n\n<p>ב\"ה, י\"ד מ\"ח, תשכ\"ה</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ עוסק בצ\"צ צנמ\"ס<br>\nוכו'<br>\nמוהרש\"י שי'</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מו' מ\"ח עם המצורף אליו, ומצו\"פ העתק מכתבי בהנוגע להנ\"ל (וגם לבי\"ס מנחת, שבטח גם עד\"ז ידוע לכת\"ר שי').</p>\n<p>בנוגע להועד שבחרו בו, מפני עניני חדש תשרי, אישור קבלת ההודעה נתעכב עד עתה.</p>\n<p>בנוגע לפועל, מה שקשה בעיני, שאחד מחברי הועד הוא אחיו של אחד מהמנהלים, שלכאורה אין זה ענין, ואף שכפי שהכרתיו בהיותו כאן, איש ישר הולך הוא, אבל בכ\"ז וכו', כן כמובן יש בזה עוד תמי' (ועיקרית ואולי עוד יותר), והיא, שלא ראיתי שם כת\"ר שי' בהועד, ואף שבודאי אין זה מענינו להתעסק בבחירת מורים וכו' [ובפרט לשיטתי אני, אשר מצוה דהוא זהיר בה טפי, היא האנציקלופדיא תלמודית לחוד, כמו שכתבתי זה כ\"פ], בכ\"ז לדעתי צ\"ל הוא בהועד בתור מכריע, כשלא יוכלו לבוא לעמק השוה שאר ד' חברי הועד. ובשתי הקושיות האמורות הרי האחת מתרצת את חברתה באופן של נועם וכבוד. ואל בינת כת\"ר שי' אשען אם צריך לגלות שהערה האמורה באה מצדי, או שיותר דיפלומטי - שלא מכאן תבוא ההערה להשינוי. והרי טעמים האמורים גלוים הם ואין צריכים וזקוקים להביא ממרחק - מעבר לים - לחמו...</p>\n<p>למענתו בנוגע להערתי בפירוש המשניות להרמב\"ם דמאי (פ\"א מ\"ב), שמתרצה בזה, שהרי הרמב\"ם העביר קולמוס ע\"ז: הנה לא היתה בזה פליטת הקולמוס וכיו\"ב, כ\"א הפסק (בין הכתיבה והעברת הקולמוס) של כמה זמן כנראה, שהרי <b>כל</b> דפוסי המשניות נכנסה בהם דוקא הגירסא של המשנה הא' ונלמד פירוש המשניות באופן כזה. ולא מצאתי ע\"ע מי שיעורר בדבר, ז.א. שלפי גירסא האמורה דעת הרמב\"ם בפירוש המשניות שלו כדעת רש\"י בזה [וכפי שיתורץ אליבא דרש\"י מקרא דואכלתי חטאת היום - מתורץ ג\"כ להרמב\"ם].</p>\n<p>הענין שהביאני לכל האמור הוא שלא לחלק בין \"אונן\" ו\"מי שמתו מוטל לפניו\" - ל\"אכלתי באוני\", כי אף שביד החזקה מערב בנוגע לאונן, מעש\"ש וקדשים ביחד וגם הפסוקים ביחד, לכאורה אין זה מוכרח כלל וכלל - שהרי מעשר שני אינם קדשים, ומה שהרמב\"ם מביא כתוב באוני, הוא כידוע הכלל שמביא הדרשה הפשוטה יותר, ואז יש להתאים להמובא באחרונים אשר אונן ואבילות אין נפגשים יחד, שאבילות מתחילה לאחרי שעברה האנינות, ז.א. בקבורה, ועלה בדעתי לאמר, שלדעת גירסתנו בפירוש המשניות* - חלוק בזה מעשר שני שאיסורו מלא אכלתי באוני, משא\"כ קדשים שאיסורם מאכלתי חטאת היום. ומה שלא מביא חילוק זה בפירוש ביד החזקה - הוא ע\"פ כללי הרמב\"ם, שלפעמים תכופות אינו כותב דינים חדשים, כיון שלא הובאו בפירוש בש\"ס.</p>\n<p>בכבוד ובברכה</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתצט</b></i></h4>\n<p>חלקה נדפס בלקו\"ש ח\"ט ע' 361 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>מוהרש\"י:</b> זוין. אגרות נוספות אליו - לעיל ח'תשלא, ובהנסמן בהערות שם.</p>\n<p><b>כמו שכתבתי:</b> ראה גם לעיל אגרת ח'תתיט. חכ\"א אגרת ח'יז*. חי\"ח ו'תתקכה. ח\"ח ב'שעג.</p>\n<p><b>להערתי:</b> דלעיל אגרת ח'תתצא.</p>\n<p>*) ולהעיר מפי' הרא\"ש (סוף מעש\"ש) - אלא שי\"ל דס\"ל לגמרי כרש\"י (גם בקדשים).</p>"],[1200970226,"ח'תתק\n\n<p>ב\"ה, י\"ד מ\"ח, תשכ\"ה</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ מלאכתו מלאכת שמים וכו'<br>\nמו\"ה יהושפט שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה על הודעתו אודות מצב זוג' תי',</p>\n<p>השי\"ת ימלא ימי הריונה כשורה ובנקל ותלד זחו\"ק בעתה ובזמנה כשורה ובקל.</p>\n<p>בברכה.</p>\n<p>במענה לשאלתו - פשוט שאין מקום כלל לפעילות של ארגון מפלגתי איזו שיהי' בבי\"ס הרשת. ולפלא <b>גדול</b> על מפליגה איזו שתהי' שתפנה בבקשה כזו, אף שמפורסמת עמדת חב\"ד בזה מעת הווסדה, וביחוד באה\"ק ת\"ו [נוסף, על הטפל, שאין זה לטובת המפליגה ג\"כ, כיון שהיתר זה בבי\"ס אחד ולמפליגה אחת - מתירה את האמור בכל בתה\"ס דהרשת ולכו\"כ מפליגות, וק\"ל]. <b>ובפירוש</b> אמרו מנהיגי המפליגה שמזכירה - <b>וכו\"כ</b> פעמים - שלא יערבו <b>כלל וכלל</b> עניני מפליגה בבי\"ס האמורים. ולפלא גדול עוד יותר מה <b>שתומ\"י</b> לא שללו בקשה זו. ומה שכותב שמאיימים וכו' - הרי מעת היות בנ\"י לגוי ומעת שאחד הי' אברהם - תמיד נמצאו מאיימים ולוחצים עליהם וכו' ומעשה אבות סימן לבנים.</p>\n<h4><i><b>ח'תתק</b></i></h4>\n<p><b>מו\"ה יהושפט:</b> אלפרט, בני ברק. אגרות נוספות אליו - לעיל ח\"כ ז'תקלח. חט\"ו ה'תכ.</p>\n<p><b>שמפורסמת עמדת חב\"ד:</b> ראה גם לעיל אגרת ח'תרפא.</p>\n<p><b>ומעשה אבות:</b> ראה ס' השיחות תשנ\"ב ח\"א ע' 79 הערה 82. וש\"נ.</p>"],[1200970227,"ח'תתקא\n\n<p>ב\"ה, כ' מ\"ח, תשכ\"ה</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה<br>\nשמואל שי'</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיום השלישי עם המצורף אליו ומוסג\"ב הקבלה.</p>\n<p>והפ\"נ יקרא בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>ת\"ח על הערתו אודות מקור לדברי אדה\"ז בשולחנו הזהב בנוגע לזמן כניסת נפש הקדושה באדם, ומציין לספר החינוך בשרשי מצות מילה.</p>\n<p>ואף שאין משיבין על הדרוש, הרי הענין דכניסת נפש הקדושה נוגע להלכה ככתוב בשו\"ע לאדה\"ז שם, הרי בספר החינוך משמע דאדרבה, דאין זמן המילה מכוון לענין כניסת הנפש בשני השרשים שכתב:</p>\n<p>א) דהמילה להבדילם בצורת גופם (שזהו בעת המילה) כמו שהם מובדלים מהם בצורת נפשותם (לשון עבר בערך זמן המילה)</p>\n<p>ב) לרמוז כי כאשר תשלים צורת הגוף ע\"י (בעת המילה) כן בידו להשלים צורת נפשו בהכשר פעולותיו (זמן רב לאחרי זה כשיהי' מחויב בפעולות במצות, וק\"ל).</p>\n<p>ולהעיר ג\"כ מטעמי מצות מילה לדעת הרמב\"ם במו\"נ חלק ג' סוף פרק מ\"ט.</p>\n<p>נעם לי לקרות בסיום מכתבו אשר מתקדמת הדפסת ספרו, ויהי רצון שיברך בקרוב על המוגמר דחלקים אלו וגם אחרי כן ילך מחיל אל חיל כצווי תורה\"ק, והרי ציווי התורה הוא גם נתינת כח.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתקא</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ב ע' 232 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מו\"ה שמואל:</b> ילוב, סירקוז. אגרות נוספות אליו - לעיל ח'תתט, ובהנסמן בהערות שם.</p>\n<p><b>מקור לדברי אדה\"ז:</b> ראה לקו\"ש ח\"ג ע' 763. ח\"כ ע' 246.</p>\n<p><b>אין משיבין:</b> שער הפסוקים שמות א, יד.</p>"],[1200970228,"ח'תתקב\n\n<p>ב\"ה, ביום השני פרשת חיי שרה בעשרים לחדש</p><p>מרחשון שנת תשכ\"ה. ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>בעמדנו ביום הולדת כ\"ק אדמו\"ר (מהורש\"ב)</p>\n<p>מייסד ישיבת תומכי תמימים ומנהלה ע\"י וביחד עם כ\"ק מו\"ח אדמו\"ר -</p>\n<p>אשר מסרו נפשם על יסודה והנהלתה ובאופן עד למסירת נפש על עניני הישיבה ועיקרה - התלמידים התמימים,</p>\n<p>והרי דברי צדיקים ועאכו\"כ העשי' שלהם, קיימים לעולם ופועלים פעולתם,</p>\n<p>יהי רצון שביום זכאי זה וממנו ולהבא, יושפע בכאו\"א מתלמידי התמימים ובכל ההולכים בדרכיו ואורחותיו תוספת אור וחיות וכח בעניניהם הרוחנים ובעניניהם הגשמים,</p>\n<p>ובהנקודה - להיות נרות להאיר,</p>\n<p>כתקות מייסדי ומנהלי הישיבה, כ\"ק אדמו\"ר (מהורש\"ב) וכ\"ק מו\"ח</p>\n<p>אדמו\"ר - זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>בברכה</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתקב</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ה ע' 415 (בתאריך מחרתיים ליום השני). והושלמה עפ\"י צילום האגרת.</p>\n<p><b>ביום... מרחשון: </b>אותה הקביעות שבשנת הולדת כ\"ק אדנ\"ע (ראה \"חנוך לנער\").</p>\n<p><b>ביום השני פרשת חיי שרה: </b>להעיר משיעור היומי (בחומש עם פרש\"י): ואברהם זקן (ויושב בישיבה - יומא כח, ב) וה' ברך את אברהם בכל (ופירש\"י) שהי' לו בן (שעולה בגימט' בכל).</p>\n<p><b>בדרכיו ואורחותיו: </b>ראה אגה\"ק סי' זך. זח\"ב רטו, א. לקו\"ת שה\"ש יב, ב.</p>\n<p><b>אור וחיות וכח: </b>ראה ד\"ה אתם נצבים רדע\"ת [המשך תער\"ב ח\"א ע' תרלג].</p>\n<p><b>נרות להאיר: </b>להעיר משו\"ע אדה\"ז או\"ח סרצ\"ח סי\"ז.</p>"],[1200970229,"ח'תתקג\n\n<p>ב\"ה, כ\"א מ\"ח, תשכ\"ה</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>כנראה אשר הסכסוך בנוגע... שי' עדיין לא שקט, וזה מכריחני להביע צערי הכי גדול על האמור, וצער גדול ואולי גדול עוד יותר, אשר כנראה מי שהוא מושך את כ' להביט על ענין זה כענין של יקוב הדין את ההר, וכאילו בזה תלוי הצלחה רבה, באם יהי' הפתרון באופן כך, והיפך הצלחה וכו' באם יהי' הפתרון באופן אחר, וכנראה שבמילא לוקח זה כמה מזמנו ומרצו ושימת לבבו מה יש לפעול וכו'.</p>\n<p>בודאי מכיר וראה במוחש איך שהצליח באופן למעלה מדרך הטבע... ואף שבטח גם אז לא היו כל הענינים באופן של שלום שלוה ושקט, שהרי נמצאים אנו בעוה\"ז שכדברי כ\"ק מו\"ח אדמו\"ר מעת חטא עץ הדעת, אין טוב בלא וכו' ולפתע פתאום נותן חשיבות גדולה לענין שחשיבות קטנה לו ואולי עוד פחות מזה.</p>\n<p>ובב\"א איני מתערב בחשיבות הענינים שהרי אינני נמצא על המקום, אבל מובן וגם פשוט, שכשיש ועד, בן כמה אנשים, ועד שנמנה לפני מאורע פלוני, אי אפשר לבטל החלטה שלו, אפילו באם לא נראית לצד א' החלטת הועד, אין לגרוע סמכות הועד, שהרי סו\"ס אין דרך אחרת לנהל ענינים בם מעורבים כמה אישים, מבלי שיהי' איזה גוף שיתווך ביניהם ויחליט במקום שיש חילוקי דיעות, החלטה (ע\"פ תורה) דאחרי רבים להטות.</p>\n<p>ובאם כאו\"א הדבר אמור, עאכו\"כ בהנוגע אליו, שכל שעה וחצי שעה וכו' שמנצלה לסכסוך, הרי יכול לנצלה ביעילות וכ\"פ ככה בהוספה בעניני בתי הספר, אשר השגחה העליונה זיכתו והצליחתו להיות מנהלם, ותוכפל חצי שעה ושעה זו במספר ובהצלחת התלמידים-ות של בתי הספר...</p>\n<p>תקותי חזקה שאין צורך באריכות בכל האמור, וישמחני בבשורה הטובה שהסיח דעתו לגמרי מכל הענין ומתוך שמחה וטוב לבב ממשיך בעבודתו הק' חינוך על טהרת הקדש של בני ובנות ישראל, שעל כ\"א מהם נאמר בנים אתם לה' אלקיכם, ואשר חיבה יתירה נודעת להם, וכפי ששמעתי מכ\"ק מו\"ח אדמו\"ר פתגם הבעש\"ט, אשר אהבת השם לכל אחד בן ובת ישראל היא הרבה באין ערוך מאהבת הורים זקנים לבן יחידם שנולד להם לעת זקנותם.</p>\n<p>ויהי רצון שמכאן ולהבא לא יהי' כל צורך במכתבים כמו אלה.</p>\n<h4><i><b>ח'תתקג</b></i></h4>\n<p><b>יקוב הדין:</b> יבמות צב, א.</p>\n<p><b>שכדברי:</b> ראה ס' השיחות תרפ\"ז ע' 84. וראה גם לעיל חט\"ו אגרת ה'שלט. ח\"ט א'תקד.</p>\n<p><b>פתגם:</b> ראה גם לעיל אגרת ח'תתעד, ובהנסמן בהערות שם.</p>"],[1200970230,"ח'תתקד\n\n<p>ב\"ה, כ\"א מ\"ח, תשכ\"ה</p><p>ברוקלין.</p>\n<p>ברכה ושלום!</p>\n<p>במענה למכתבה אודות הסכסוך בין בעלה הוו\"ח אי\"א נו\"נ בעל מרץ שי' עם מנהל השני.</p>\n<p>כבר כתבתי במכתבי לבעלה שי' [שפלא גדול ביותר על שמגדיל הענין לממדים שאינם הולמים כלל, אלא שאין זה עיקר והעיקר הוא] שהצליח בעלה שי' למעלה מדרך הטבע בחינוך על טהרת הקדש... וע\"פ הציווי ונתינת כח מה' להעלות בקדש - צפוי' לו הצלחה גם בעתיד ועוד יותר בעבודת הקדש האמורה, ובלבד שלא יבלבלוהו ולא יסיחו דעתו מפעולותיו בחינוך וכו' אפילו לסכסוך כהאמור... וכנ\"ל יצליח בעבודתו האמורה גם להבא, ובודאי מצדה תעשה כל התלוי בה שימשיך בהנ\"ל מתוך שמחה וטוב לבב.</p>\n<p>והשי\"ת יצליח את כאו\"א מהם ושניהם יחד בכל המצטרך להם, ובנקודה העיקרית נחת אמיתי נחת יהודי חסידותי מכל יו\"ח שי'.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<h4><i><b>ח'תתקד</b></i></h4>\n<p><b>במכתבי:</b> שלפנ\"ז.</p>\n<p><b>הציווי:</b> ברכות כח, א. וש\"נ.</p>"],[1200970231,"ח'תתקה\n\n<p>ב\"ה, כ\"ד מ\"ח, תשכ\"ה</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מט\"ו מ\"ח,</p>\n<p>בעת רצון יזכירו אותו ואת זוגתו תחי' על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע למילוי משאלות לבבו לטובה מתאים לתוכן כתבו.</p>\n<p>וע\"פ סגנון מכתבו, בודאי למותר להדגיש ע\"ד הכרח הנהגה בחיי היום יומים שתהא מתאימה להוראות תורתנו תורת חיים ובקיום מצותי' עליהם נאמר וחי בהם, ולא באתי אלא להוסיף, אשר בעניני תורה ומצות ככל שיהי' המצב גם טוב בזה, תמיד יש מקום להוסיף, והובטחנו (בכגון זה) מחז\"ל כל המוסיף מוסיפין לו (בהמצטרך לו).</p>\n<p>וכיון אשר מלאכתו בהוראה למורים, הרי זכות גדולה ביחד עם אחריות גדולה, לזה שקורא במכתבו מלאכה ובסגנון חז\"ל מלאכת ה', ובנקודה הפנימית להחדיר בהתלמידים יראת ה' ואהבת השם ובפרט שמתכוננים הם (התלמידים) להיות מורים, ז.א. שכל הטבה והוספה בהם, נכפלת פי כמה בתלמידיהם לעתיד.</p>\n<p>ומהנכון אשר יבדקו את התפילין שלו וכן את המזוזות בדירתם שתהיינה כולן כשרות כדין, וזוגתו תחי' תשמור על מנהגן הטוב של בנות ישראל הכשרות להפריש לצדקה קודם הדלקת הנרות בכל ערב שבת וערב יום טוב.</p>\n<p>ולאחרי בקשת סליחתו, עלי להוסיף, שזה שקורה לפעמים עכוב בכענינו, בא לצד שחסר הידור וזהירות מלאה בחוקי ודיני טהרת המשפחה (נדה, הפסק טהרה, טבילה במקוה כשרה וכו') מאי ידיעה מלאה בהפרטים בזה, ולכן עליהם לברר זה אצל רב מורה הוראה באם לא חסר מה בהידיעות שלהם בזה.</p>\n<p>בכבוד ובברכה לבשו\"ט בכל האמור.</p>\n<h4><i><b>ח'תתקה</b></i></h4>\n<p><b>והובטחנו:</b> ראה תענית בסופה.</p>\n<p><b>ובסגנון חז\"ל:</b> בבא בתרא כא, ב.</p>\n<p><b>שקורה לפעמים:</b> ראה גם לעיל אגרת ח'תרפז, ובהנסמן בהערות שם.</p>"],[1200970232,"ח'תתקו\n\n<p>ב\"ה, כ\"ז מרחשון, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לוי יצחק שי' רבקה לאה תחי'<br>\nסאשע תחי' שטערנא שרה תחי'</p>\n<p>שלום וברכה!</p>\n<p>בקשר עם יום ההולדת של כל אחד ואחת מכם, אזכירכם על ציון כ\"ק מו\"ח אדמו\"ר שתגדלו לתורה ולחופה ולמעשים טובים והוריכם שיחיו ישבעו רוב נחת אמתי חסידותי מכל או\"א מכם - מתוך שמחה וטוב לבב והרחבה בגשמיות וברוחניות, לאורך ימים ושנים טובות.</p>\n<p>בברכת שנת הצלחה לכאו\"א</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתקו</b></i></h4>\n<p><b>לוי יצחק... שרה:</b> גרליק.</p>"],[1200970233,"ח'תתקז\n\n<p>ב\"ה, כ\"ז מרחשון, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>מר פ. יוסף שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו מיום ט' מרחשון, בו כותב איך שהכיר את תנועת חב\"ד עוד בהולנד, ועל דבר מקום לימודו עתה איך שקשה לו לראות לפעמים היחס הבלתי מתאים בנוגע למצוות מצד אלו שלמדו יותר ממנו.</p>\n<p>תקותי חזקה - על פי מה שהורונו חכמינו ז\"ל שמעשה הוא העיקר - שרגש זה שלו, שמצטער לראות היחס האמור, יבוא לתשומת לב של אלו שכותב עליהם באופן שישפיע עליהם לשנות יחסם. והרי הובטחנו שדברים היוצאים מן הלב נכנסים אל הלב ופועלים פעולתם. ובפרט כשהדברים יהיו מלווים בדוגמא חי' מחיי היום-יום שלו, חיי תורה ומצוות. ואין לך דבר העומד בפני הרצון, שאם בכל מקום גדולה מצוות ואהבת לרעך כמוך שהיא כלל גדול בתורה, להורות דרך התורה והמצוה לאלה הטועים ונבוכים, על אחת כמה וכמה בארץ אשר עיני ה' אלקיך בה מראשית השנה ועד אחרית שנה, ובפרט לאלה שלומדים במוסד למדריכים ומחנכים שעליהם יהי' להשפיע על כמה וכמה תלמידים. וידוע אשר בכדי להשפיע על תלמידים במקצוע מסוים מוכרח אשר אצל המשפיע יהי' הדבר במידה גדולה ביותר.</p>\n<p>תקותי אשר ראה את מכתבי הכללי לראש השנה שנתפרסם באה\"ק ת\"ו בלה\"ק, שאחת הנקודות המרכזיות במכתב זה היא איך שאפילו אדם יחידי יכול לפעול גדולות ונפלאות בעניני טוב אם רק ינצל כל כוחותיו כדבעי.</p>\n<p>בטח יודע על שעורי חת\"ת (חומש, תהלים, תניא) שהם שוים לכל נפש, ומקיימם בכל יום.</p>\n<p>ברכה להצלחה ולבשורות טובות.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>נ.ב. כיון שכאן כותבים לה\"ק, אנגלית ואידיש, מטובו להודיע באיזו שפה לכתוב לו להבא.</p>\n<h4><i><b>ח'תתקז</b></i></h4>\n<p><b>שהורנו חכמינו:</b> אבות פ\"א מי\"ז.</p>\n<p><b>מכתבי הכללי:</b> דלעיל ח'תתפו.</p>"],[1200970234,"ח'תתקח\n\n<p><i>[שלהי מרחשון תשכ\"ה]</i></p>\n<p>סדר החיים כשהבעל לומד תורה חלק מיומו (עכ\"פ) - מובן <b>שזוהי</b> ההתחלה הנכונה ושצ\"ל בבנ\"י [כיון שהחתונה היא ההתחלה דבנין עדי עד] - אבל מובן ג\"כ, שזהו קשור בהגבלה ומדידה וקצת צמצום בנוגע לגשמיות, וכיון שזהו נרגש בחיי יום יום ומאידך - צ\"ל החיים דבנ\"י - כמש\"נ - מתוך שמחה וט\"ל ובטחון -</p>\n<p>הרי צ\"ל ההסכמה על סדר חיים כזה - <b>מראש והסכמה מלאה ומתוך שמחה</b> (על שמתחילים חייהם - בחיי תורה, תורת חיים).</p>\n<p>ואם יסכימו שניהם ע\"ז ובאופן הנ\"ל - יה\"ר שיהא כ\"ז בשטומו\"צ.</p>"],[1200970235,"ח'תתקט\n\n<p><i>[שלהי מרחשון תשכ\"ה]</i></p>\n<p>במענה לשאלותיו מאז: ג' הענינים שבמילה (פעולה, מהול, אינו ערל) - אין עושים אותה <b>לג'</b> מצות. והקביעות אם זהו הזמן גרמא א\"ל - צ\"ל <b>בהמצוה</b> (שאחת היא) ולא בפרטי'. ואין לך זמן (מיום הח' והלאה) שאין מחוייב במצוה זו.</p>\n<p>- ענין הבחירה שייך רק בבר שכל כי בא\"ל - עושה מצד טבע וכיו\"ב, או שאינו עושה כלל, אבל אין שייך לומר בנדו\"ד <b>שרואה</b> שני ענינים <b>שווים ובוחר</b> באחד אחד. וכמו שאין לומר שסומא <b>בוחר</b> בצבע אחד מבין כמה צבעים. אבל זה הבר שכל נמצא במצב שאין השכל <b>מכריחו</b> באיזה צבע (סברה) לבחור ורק שמראהו הצבעים (הסברות).</p>\n<h4><i><b>ח'תתקט</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חל\"ב ע' 231 והושלמה עפ\"י גוכי\"ק.</p>\n<p>האגרת היא אל מו\"ה יצחק זלמן שי' פויזנר, ונכתבה על גליון מכתבו מיום כ\"ב חשון תשכ\"ה. אגרות נוספות אליו - לעיל חט\"ז ו'עט ובהנסמן בהערות שם.</p>\n<p><b>במענה לשאלותיו:</b> על המדובר בלקו\"ש ח\"ג ע' 760 דע\"פ המבואר בצפע\"נ שמילה היא פעולה נמשכת מתורצת קושיית התוס' (קידושין כט, א), כי אין מילה מצוה שהזמ\"ג (ע\"ש) - הרי סו\"ס פעולת המילה היא ביום הח' דוקא.</p>\n<p><b>ענין הבחירה:</b> על המדובר בלקו\"ש ח\"ד ע' 1309 שאמיתית ענין הבחירה הוא שאין שום טעמים וסיבות להבחירה, כי כאשר ישנם טעמים לבחירתו הרי הוא מוכרח בזה, ולכאורה עפ\"י המבואר בסה\"מ תר\"ס ע' י ואילך שענין הבחירה שייך דוקא בבר שכל.</p>"],[1200970236,"ח'תתקי\n\n<p><i>[שלהי מרחשון תשכ\"ה]</i></p>\n<p>זמן החתונה ומקומה - כפי שיתדברו שני הצדדים. ופשוט שמה טוב שתהי' בכחב\"ד, אשר שם ציווה ה' את הברכה.</p>\n<p>בנוגע לטבילתו במקוה (בקשר לאוזן) משימים באזן מוך שרוי במים. ובכו\"כ מקרים מתירים זה הרופאים אפילו לכתחלה.</p>\n<h4><i><b>ח'תתקי</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חל\"ב ע' 242 והושלמה עפ\"י גוכי\"ק.</p>"],[1200970237,"ח'תתקיא\n\n<p>ב\"ה, ראש חדש כסלו, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>ובעמדנו בראש חדש כסלו, חדש הנסים והגאולה, יהי רצון אשר כבימים ההם בזמן הזה - כן יהי' גם בימינו אלה בזמן הזה, הן בנוגע לנר מצוה ותורה אור (ענין חנוכה) והן בנוגע במיוחד להפצת פנימיות התורה, תורת החסידות (ענין י\"ט כסלו, יו\"ד כסלו).</p>\n<p>ויהי' כל זה באופן של קיימא, וכמחז\"ל בנרות חנוכה: הנרות לעולם אל מול פני המנורה יאירו.</p>\n<p>בברכה לבשו\"ט בכל האמור,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתקיא</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"י ע' 216 (וצריך לתקן התאריך שם) והושלמה עפ\"י צילום האגרת.</p>\n<p><b>בראש חדש: </b>שהוא הראש (הכולל) כל ימי החדש (עטרת ראש שער ר\"ה פ\"ב).</p>\n<p><b>ענין חנוכה: </b>שלא \"הניחו אותם לעסוק בתומ\"צ\" (רמב\"ם ריש הל' חנוכה) והנס ופרסומו בנר ואור.</p>\n<p><b>פנימיות התורה: </b>שזהו ודרך חיים שבסיום הכתוב (משלי ו, כג) כי נר מצוה ותו\"א (ראה סוטה כא, א. קונטרס עה\"ח בתחלתו ופט\"ו).</p>\n<p><b>י\"ט כסלו: </b>שאז התחיל עיקר הפצת המעינות חוצה (תורת שלום, י\"ט כסלו תרס\"ח).</p>\n<p><b>וכמחז\"ל: </b>במדב\"ר וכפי' הרמב\"ן ר\"פ בהעלתך.</p>\n<p><b>הנרות... יאירו: </b>נש\"י לעולם יהי' לבם מכוון לפנימיות רצון העליון (לקו\"ת ד\"ה בהעלתך ספ\"ו. ועפ\"ז מתורץ מה שייך בנרות חנוכה אל מול גו').</p>"],[1200970238,"ח'תתקיב\n\n<p>ב\"ה, ראש חדש כסלו, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ כו' מו\"ה יצחק<br>\nשי'</p>\n<p>שלום וברכה!</p>\n<p>... להערתו איך אפ\"ל תלד אשה בכל יום כיון שאיסור טומאתה לא ישתנה (אגה\"ק סכ\"ו) - הרי באווארענט שם על אתר והוסיף \"מביאה אחת\" (תהי' אח\"כ הלידה כמה ימים). ועיין עוד פי' בלקוטי הש\"ס להאריז\"ל והצ\"צ במילואים לתהלים (כ, יו\"ד) - ודלא כחדא\"ג מהרש\"א (שבת ל, ב).</p>\n<h4><i><b>ח'תתקיב</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ב ע' 178 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>מו\"ה יצחק:</b> דובאוו. אגרות נוספות אליו - לעיל ח'תשט, ובהנסמן בהערות שם.</p>\n<p><b>אגה\"ק סכ\"ו:</b> ראה גם שיעורים בספר התניא שם.</p>"],[1200970239,"ח'תתקיג\n\n<p>ב\"ה, ה' כסלו תשכ\"ה</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו - בלי הוראת זמן הכתיבה.</p>\n<p>יהי רצון אשר מכאן ולהבא לא ידעו עוד מכל צער ועגמ\"נ ואך טוב, בטוב הנראה והנגלה יבשר תכה\"י.</p>\n<p>ובזה כמובן ופשוט ג\"כ, שכציווי רבותינו נשיאינו יראה גם מעלת עצמו, ובפרט שכנראה במוחש נוגע זה לעבודת השם בכלל ולעבודה בשמחה ובטוב לבב, שזהו עיקר גדול, כמבואר הענין בכ\"מ בתורת החסידות.</p>\n<p>והדרך המביאה לעבודה בשמחה, הרי מבוארת בספר תניא קדישא באר היטב, ולפלא וואס מ'גיט זיך אזוי נאך טראכטען היפך מקו השמחה וכו' ואין צועקין על העבר, וכוונתי על להבא, ואין לך דבר העומד בפני הרצון.</p>\n<p>ובפרט אשר נכנסנו בחדש כסלו, חדש הנסים והגאולה.</p>\n<p>בברכה לבשו\"ט בכל האמור ובהקדם.</p>\n<h4><i><b>ח'תתקיג</b></i></h4>\n<p><b>שכציווי:</b> ראה גם לעיל חי\"ט אגרת ז'שנט. חי\"ח ו'תתלה. ו'תתקנח, ובהנסמן בהערות שם.</p>\n<p><b>ואין צועקין:</b> ראה ברכות נד, א.</p>"],[1200970240,"ח'תתקיד\n\n<p>ב\"ה, יו\"ד כסלו תשכ\"ה</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה יוסף שי'</p>\n<p>שלום וברכה!</p>\n<p>... להשמועה בשם הרגוצבי: ראי' דבע\"ת גדולים מצד\"ג מקדושין (מט, ב) - גם אני שמעתי', אבל נ\"ל דאינה אמתית, שהרי המקדש ע\"מ שאני לוי ונמצא כהן ג\"כ אינה מקודשת. [והטעם בקידושין עכצ\"ל מפני שבלשון בנ\"א גם בע\"ת נקרא צדיק. וגם בל' חז\"ל בל' המושאל שהרי זכה בדין -תניא פ\"א].</p>\n<h4><i><b>ח'תתקיד</b></i></h4>\n<p><b>מו\"ה יוסף:</b> הלל, לוד.</p>\n<p><b>להשמועה... ראי':</b> ראה גם לקו\"ש חי\"ז ע' 186 הערה 46 - 45.</p>"],[1200970241,"ח'תתקטו\n\n<p>ב\"ה, ימים שבין יו\"ד וי\"ט כסלו, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>ובעמדנו בין גאולה (דאדמו\"ר האמצעי) לגאולה (דאדמו\"ר הזקן).</p>\n<p>אשר שתיהן נקבעו למועד ולחג לדורותיהם אחריהם לזכר עולם,</p>\n<p>וקשורה הגאולה ותוכנה שייך לדברי דוד מלך ישראל בשם כאו\"א מישראל: פדה בשלום נפשי מקרב לי כי ברבים היו עמדי -</p>\n<p>יהי רצון אשר מתאים לדרשת רז\"ל בכתוב האמור: אמר הקב\"ה כל העוסק בתורה ובגמ\"ח ומתפלל עם הצבור מעלה אני עליו כאילו פדאני לי ולבני מבין אומות העולם,</p>\n<p>יתחזק כאו\"א, בתוככי כלל ישראל, בשלשה קווין האמורים: בעסק התורה, בעסק גמ\"ח (ומצות בכלל) ובעבודת התפלה. -</p>\n<p>מוארים באור תורתן של הנ\"ל - תורת החסידות.</p>\n<p>ויהי' כ\"ז במצב של גאולה מכל מניעות ועיכובים.</p>\n<p>ובאופן דהלוך והוסיף ואור בכל האמור - עדי גאולתנו השלימה והאמתית ע\"י משיח צדקנו במהרה בימינו.</p>\n<p>בברכת חג הגאולה ולבשו\"ט בפרט ובכלל,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתקטו</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"י ע' 221 (וצריך לתקן התאריך שם) והושלמה עפ\"י צילום האגרת. וראה גם לעיל אגרת ח'תשט. ח'תשכח.</p>\n<p><b>ימים שבין כו': </b>ראה שיחת יו\"ד כסלו תש\"ז (לקו\"ד [כרך ג] ע' 976).</p>\n<p><b>לדרשת רז\"ל: </b>ברכות ח, א.</p>\n<p><b>בשלשה קווין: </b>ראה חדא\"ג מהרש\"א שם. רשימות אדמו\"ר הצ\"צ לתהלים שם (נה, יט).</p>\n<p><b>גמ\"ח (ומצות בכלל): </b>דכל המצות נק' בשם צדקה (תו\"א סג, ג. ובכ\"מ).</p>"],[1200970242,"ח'תתקטו*\n\n<p><i>[נוסח המברק לקראת חג הגאולה י\"ט כסלו תשכ\"ה]</i></p>\n<p>לשנה טובה בלימוד החסידות ודרכי' ולהפצת המעיינות חוצה בהצלחה רבה תכתבו ותחתמו.</p>\n<p><b>/מקום החתימה/</b></p>"],[1200970243,"ח'תתקטז\n\n<p>ב\"ה, ערב חנוכה ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>בנות חב\"ד, סניף ירושלים ת\"ו<br>\nה' עליהן תחיינה</p>\n<p>ברכה ושלום!</p>\n<p>בודאי אין צורך להסביר להן על דבר פרשת ימי החנוכה הממשמשים ובאים, ובפרט מה שסיפרו חכמינו זכרונם לברכה שגם הנשים היו באותו הנס, ולא עוד אלא שהי' להן חלק חשוב בהנסים והתשועות שבימים ההם בזמן הזה. והרי זכרון הימים ההם הנזכרים ונעשים בזמן הזה צריך לעורר את הרצון וההחלטה ללכת בעקבות הנשים ההן להפיץ אור תורה ונר מצוה ובאופן שמוסיף והולך מוסיף ואור, כהוראת נר חנוכה. ויהי רצון שהתעוררות הימים האלה תאיר ותחדיר את פעולותיהן בכל ימי השנה.</p>\n<p>בברכה להצלחה ולבשורות טובות,</p>\n<p><b>מ. שניאורסאהן</b></p><p>נ.ב. בעתו נתקבל מכתבן ע\"ד הפעולות במסגרת עבודתן, והשי\"ת יצליחן וימלא משאלות לבן לטובה ולברכה בכל הענינים שכותבות עליהם.</p>\n<h4><i><b>ח'תתקטז</b></i></h4>\n<p>נדפסה בלקו\"ש חט\"ו ע' 542 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>שסיפרו חכמינו:</b> שבת כג, א.</p>"],[1200970244,"ח'תתקיז\n\n<p><i>[חנוכה תשכ\"ה]</i></p>\n<p>... נוהגין הנערים העניים לסבב על הפתחים כו'...</p>\n<p>מגן אברהם ריש הל' חנוכה - הועתק בדברי נחמי' - השלמה לשו\"ע אדה\"ז סו\"ס תר\"ע. - אבל עדיין צ\"ע בזה. כי לא ראיתי כל רמז לזה במנהגי חנוכה של כ\"ק מו\"ח אדמו\"ר. ואף שאין לא ראינו ראי', ובפרט בצדקה שמתן בסתר יפה בה - הרי, לכאורה מילתא הוא מה ש(לבד ממשנ\"ת בד\"ה בכ\"ה בכסלו - בתו\"א וביאוריו בשערי אורה ואוה\"ת - דמעשה הצדקה נק' כובע ישועה ומס\"נ דחנוכה המשיכה מתנה מרובה המשכת כובע ישועה להיות כו') לא אשתמיט להזכיר בשום מאמר חסידות (שראיתי ע\"ע) או שיחה ומכ' רבותינו ע\"ד צדקה במיוחד בחנוכה (אף <b>שכו\"כ</b> עניני חנוכה נזכרו ונתבארו בהם ובפרטיות). ובפרט שנמצא הוא בכמה מס' פולין וכו'. ומי שימצא עד\"ז בתורת נשיאינו ודאי יודיעני ות\"ח מראש מקול\"ע. - בסי' מהרי\"ד (ואולי קטע זה מהצ\"צ) מבאר הנ\"ל שבחנוכה חולקין \"מעות לעניים שמחזרין על הפתחים, שהוא על פתח הבית מבחוץ שהוא בחי' בכל מאדך בכל ממונך\".</p>\n<h4><i><b>ח'תתקיז</b></i></h4>\n<p>נדפסה בשערי הלכה ומנהג ח\"ב ע' רסה.</p>\n<p><b>מקול\"ע:</b> מקרב ולב עמוק.</p>"],[1200970245,"ח'תתקיח\n\n<p>ב\"ה, ימי חנוכה תשכ\"ה</p><p>ברוקלין.</p><p>הרבנית מרת בתי' תי'</p>\n<p>ברכה ושלום!</p>\n<p>במענה למכתבה בו כותבת אודות יום הולדת שלה,</p>\n<p>ובודאי מוסיפה בעניני יהדות ומצות, כציווי תורתנו הק' תורת חיים להעלות בקדש,</p>\n<p>ונוסף על העיקר מילוי הציווי - הרי זה גם הצנור והכלי לקבלת ברכות השי\"ת בהמצטרך.</p>\n<p>ויהי רצון מהשם יתברך שתהי' שנה הבאה עלי' לטובה שנת הצלחה בגשמיות וברוחניות. ותבשר טוב בכל האמור.</p>\n<p>בברכת הצלחה בעניניהם הפרטים והכלליים,</p>\n<p><b>מ. שניאורסאהן</b></p><p>באם תוכל לסדר ב\"ב שי' באופן מתאים (ובאם זהו בהסכמת בעלה הרב</p>\n<p>שי') - ובאם עוד די זמן מספיק להכנה, יהא ביקורה כאן ודקבוצת הנערות תי' בשעה טובה ומוצלחת.</p>\n<h4><i><b>ח'תתקיח</b></i></h4>\n<p><b>מרת בתי' תי':</b> גרליק, מילנו. אגרת נוספת אלי' - לעיל חי\"ח ו'תריד.</p>\n<p><b>כציווי:</b> ברכות כח, א. וש\"נ.</p>\n<p><b>בעלה הרב:</b> גרשון מענדל שי'.</p>"],[1200970246,"ח'תתקיט\n\n<p>ב\"ה, ימי חנוכה ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>בעמדנו בימי חנוכה הבאים בסמיכות לי\"ט כסלו, יום בשורה,</p>\n<p>יש לבאר הצד השווה אשר בימי החנוכה וי\"ט כסלו (בדא\"פ, עכ\"פ).</p>\n<p>דנס חנוכה הי' בשמן - הרומז על פנימיות התורה - של נרות המקדש, אשר מקומם בהיכל דוקא שלא כל אחד נכנס לשם, וזמן הדלקתם - ביום,</p>\n<p>ובימי מתתי' בן יוחנן כ\"ג כו' שמסרו נפשם על קידוש ה', הייחוד האמתי באומרם ובכל נפשך ואפילו נוטל את נפשך - הי' הנס ונצטוו עי\"ז בנרות חנוכה אשר מצוותם - להדליקם כל אחד ואחת (נפש) ועל פתח ביתו מבחוץ (עולם) ומשתשקע החמה דוקא (שנה).</p>\n<p>וככל הדברים האלה הוא בלימוד פנימיות התורה - שמן דתורה, אשר מתחלה היתה נסתרה ונעלמה מכל ת\"ח כ\"א ליחידי סגולה, ואף גם זאת בהצנע לכת ולא ברבים, (אבל) בדורות אלו האחרונים מצוה לגלות זאת - בימי האריז\"ל וכו' - ועד בגאולת י\"ט כסלו - שהתחיל עיקר ענין הפצת המעינות חוצה, עד אשר כאו\"א יבין וישיג איך אשר איהו ממלא כל עלמין ואיהו סוכ\"ע וכו'.</p>\n<p>ויהי רצון אשר יעשה בזה כאו\"א מאתנו, ובכל שלשת הפרטים: א) באופן דהפצה, ב) המעינות עצמם, ג) עד שיגיעו גם - חוצה.</p>\n<p>ומתוך חיות ואור ומוסיף והולך ואור.</p>\n<p>בברכת חנוכה שמח,</p>\n<p><b>מ. שניאורסאהן</b></p><p>* * *</p>\n<p>לההערה בכבוד או\"א דא\"א - <b>ויאמרו</b> שבפרש\"י (נח יא, לב). היינו <b>תביעת או\"ה,</b> ואאפ\"ל שהם <b>יתבעו</b> למה אין א\"א מקיים התורה קודם שניתנה וק\"ל.</p>\n<p>מענין חם ובתואל ולבן - אין ראי' כי בהם המדובר בבזיון, ובנדו\"ד - שב וא\"ת בכיבוד.</p>\n<h4><i><b>ח'תתקיט</b></i></h4>\n<p>כללי פרטי. וראה לעיל חכ\"ב אגרת ח'תקסא. שיחת ש\"פ מקץ תשכ\"ה (לקו\"ש ח\"ה ע' 442).</p>\n<p><b>המכתב:</b> נדפס לעיל ח\"ה אגרת א'רסב.</p>\n<p><b>לההערה... דא\"ח:</b> ראה בארוכה לקו\"ש ח\"ה ע' 154 ואילך. ע' 408 ואילך.</p>\n<p><b>מענין... ולבן:</b> ראה לקו\"ש שם.</p>\n<p><b>יום בשורה: </b>ג' י\"ט לחדש כסלו... יום בשורה (שו\"ת מן השמים ס\"ה. ולא פירש שם מהי הבשורה). ולהעיר אשר בשנת גאולת רבנו הזקן חל ג\"כ כקביעות שנה זו י\"ט כסלו ב\"יום ג' שנכפל בו כי טוב\" (מכתב אדה\"ז. נדפס בבית רבי ח\"א פי\"ח [אג\"ק שלו ח\"א אגרת לח]). וכן הי' גם בשנת (ויום) ההסתלקות של הה\"מ (קונטרס ח\"י אלול, ה'תש\"ג רשימה א). - ואף שהמאורע הי' כמה שנים לאחרי השו\"ת מן השמים, גדולה מזה מצינו (לדעת הראב\"ד בס' הקבלה) אשר הכתוב במגלת תענית (הועתק בטואו\"ח סתק\"פ) דמתענין בט' טבת ו\"לא כתבו רבותינו על מה הוא\" הוא \"שכיוונו ברוה\"ק\" שביום זה <b>(בשנת ד\"א</b> <b>תתכ\"ד)</b> יהרג ר' יוסף הלוי הנגיד וכו'. ויש לבאר זה ע\"פ מרז\"ל דישנם ימי הטוב וימי הרעה (זח\"א רד, א). ועפי\"ז יש לבאר ג\"כ מרז\"ל מגלגלין זכות ליום זכאי כו' (תענית כט, א). תוד\"ה יום (שם כט, ב) שרבים נתקשו בו. ועוד.</p>\n<p><b>שמן... פנימיות התורה: </b>ראה ברכות נז, א: שמן... מאור תורה. זח\"ג לט, א. ובכ\"מ.</p>\n<p><b>שלא כל אחד: </b>כלים פ\"א מ\"ט.</p>\n<p><b>הדלקתם - ביום: </b>ראה פסחים נט, א. נח, רע\"א. וראה רמב\"ן לשמות יב, ו.</p>\n<p><b>מתתי' בן יוחנן כ\"ג: </b>תיקן ההוד באלו הח' ימים כו' (פע\"ח ש' החנוכה).</p>\n<p><b>שמסרו נפשם... את נפשך: </b>צרור המור (פ' ואתחנן ו, ד).</p>\n<p><b>כל אחד ואחת: </b>טושו\"ע או\"ח סו\"ס תרע\"ח. וראה הערה ב' בסוף הקונטרס \"מאמר ברוך שעשה נסים\" להצ\"צ [ובס' המנהגים ע' 69].</p>\n<p><b>הייתה... לגלות זאת: </b>אגה\"ק סי' כו.</p>\n<p><b>שהתחיל עיקר... סוכ\"ע: </b>שיחת י\"ט כסלו תרס\"ח (תורת שלום ע' קיב ואילך).</p>\n<p><b>שלשת הפרטים: </b>ראה המכתב מער\"ח כסלו ה'תשי\"ב (נדפס בסוף החוברת י\"ט כסלו - בלה\"ק - ע' 30 ואילך).</p>"],[1200970247,"ח'תתקכ\n\n<p><i>[שלהי כסלו תשכ\"ה]</i></p>\n<p>... קראתי במכ\"ע שנסדרו ג\"פ ע\"י שמיעה בטליפון (מוינא) מהבעל: כתבו ותנו כו'.</p>\n<p>אתענין לדעת אם נכונה השמועה והנימוקים - כי לכאורה צע\"ג בזה, שהרי ע\"י טליפון אין זה קול הבעל <b>כלל</b> כ\"א שע\"י דבורו מתעוררים שינוים בזרם עלעקטרי (שעד היום אין איש יודע מה טיבו <b>ומהותו,</b> כ\"א רק אופן פעולתו. אבל \"ידוע\" שאין זה כלל גלי אויר או תנועות מעין אלו שבעת הכתיבה) <b>ולאח\"כ</b> שינויים אלה מפעילים קרום דק <b>שרצה</b> האומן והתקינו באופן מסוים.</p>\n<p>ומובן שאין זה נוגע לענין סמכות פוטוגרפיא וכיו\"ב בנוגע לעגונות וכיו\"ב - כי בזה צ\"ל סימן וידיעת הב\"ד, משא\"כ בגט שצ\"ל אמירת הבעל.</p>\n<p>וה\"ה שאין מקום לשמיעת קריאת מגילה וכו' ע\"י טליפן ורדיא וכיו\"ב - כי אין זה <b>קול</b> אדם <b>כלל</b> (אפילו לא כהתוקע לתוך הבור). ופשוט שחידוש גדול וגם מוזר הוא לאמר שכח כחו ושינוי <b>עקרי</b> במהות וכו' יבוא במקום דבור.</p>\n<p>ואף שישנם מהאחרונים פוסקי וגדולי ישראל [...] - מוכח מהשו\"ת שלהם עצמם שאלה שביארו לפניהם מהות ואופן פעולת הטליפון טעו בזה טעות עקרי ואכמ\"ל.</p>\n<h4><i><b>ח'תתקכ</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ט ע' 336.</p>\n<p><b>וה\"ה... מגילה:</b> ראה גם לקו\"ש חכ\"א ע' 496.</p>"],[1200970248,"ח'תתקכא\n\n<p>ב\"ה, זאת חנוכה, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>אל קהל עדת ישורון חובבי ומוקירי תורה<br>\nומצוה<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>די פארבארייטונגען צו דער פארשטייענדער יערלעכער אונטערנעמונג פון מרכז הישיבות תומכי תמימים ליובאוויטש (כ\"א שבט הבע\"ל) זיינען אין פולן גאנג. איך וויל האפן, אז יעדער איינער און איינע, וועמען דער ענין פון תורה ומצוות איז נאענט און טייער, וועט זיכער זיך באלד מאביליזירן בייצוטראגן זיין (און איר) חלק צו דעם דערפאלג פון דער יערלעכער אונטערנעמונג.</p>\n<p>אלע אידישע ימים-טובים און טעג פון דערמאנונג, אריינברענגענדיג פריש לעבן אין טאג-טעגלעכן לעבן פון דער געגנווארט, פארבינדן די אידישע צוקונפט מיר דער אידישער פארגאנגענהייט. דאס איז אזוי אויך בנוגע די טעג פון חנוכה, ווי עס ווערט ספעציעל אונטערשטראכן אין נוסח ההודאה <b>בימים ההם בזמן הזה.</b></p>\n<p>חנוכה דערמאנט אונז דעם פארזוך פון דער אויסערלעכער וועלט אריינצודרינגען אין דער אינערלעכער אידישער וועלט - ניט אזוי דורך א באמיאונג אויסצוווארצלען תורה ומצוות אינגאנצן, ווי דורך א שטרעבונג אויסצוליידיגען תורה ומצוות פון זייער אינערלעכן גייסט פון קדושה און ג-טלעכקייט. דאס ווערט אונטערגעשטראכן אין דער חנוכה-תפילה: די יוונים האבן זיך באמיט <b>להשכיחם תורתך</b> - צו מאכן אידן פארגעסן <b>דיין</b> (ג-טלעכע) תורה, <b>ולהעבירם מחוקי רצונך</b> - און אראפפירן זיי פון די געזעצן פון <b>דיין</b> (ג-טלעכן) רצון. די תורה אלס א \"חכמה\", אדער אלס א \"ליטערארישע קונסטווערט\", אד\"ג, איז ניט געווען אין סכנה; אויך ניט די אזוי-גערופענע \"עטישע\" און \"שכליות'דיגע\" מצוות. געשטעלט געווארן אין סכנה איז די טיפע אידישע אמונה אין <b>תורת השם,</b> דעם <b>אויבערשטנ'ס</b> תורה, <b>תורה מן השמים,</b> און <b>מצות השם,</b> דעם <b>אויבערשטנ'ס</b> מצוות. די דאזיגע סכנה איז פונקט אזוי ערנסט היינט ווי אמאל; די היינטיגע \"יוונים\" און זייערע אידישע מיטהעלפער און נאכטענצער די \"מתיוונים\", זיינען ניט ווייניגער געפערלעך פאר דעם אידישן קיום ווי די אמאליגע.</p>\n<p>דעריבער איז היינט אזוי וויכטיג צו פארשטארקן און אויסברייטערן אזא מוסד ווי די ליובאוויטשער ישיבה, וואו לימוד התורה איז דורכגעדרונגען מיט קדושה און יראת שמים והידור מצוה, ועל כולם - מיט א געפיל פון אחריות און אהבת ישראל און מסירת נפש, ווי די חשמונאים פון אמאל, ארויסצוגיין אין גאס צו פארשפרייטן דעם <b>נר מצוה</b> <b>ותורה אור,</b> אלץ מער און מער, לויט דער הוראה פון <b>נר חנוכה.</b></p>\n<p>עס איז צו האפן, אז די עסקני הישיבה וחובבי תורה ומצוה בכלל וועלן אויסנוצן די געציילטע וואכן צום יערלעכן דינער צו פארשטארקען זייערע באמיאונגען און זייער אנטייל, אויך אין א שטייגענדער מאס, צו פארזיכערן די פינאנציעלע און גייסטיגע הצלחה פון דער יערלעכער אונטערנעמונג. בזכות זה וועט יעדער איינער און איינע פון די טוער און שטיצער זוכה זיין צו א <b>תשועה גדולה</b> אין אלץ וואס מען נויטיגט זיך, פאר זיי און זייערע בני בית שיחיו, בגשמיות וברוחניות גם יחד.</p>\n<p>בכבוד ובברכה להצלחה ולבשורות טובות,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתקכא</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"י ע' 297.</p>\n<p><b>חנוכה:</b> ראה גם לעיל אגרת ח'תשכג, ובהנסמן בהערות שם.</p>"],[1200970249,"ח'תתקכב\n\n<p>ב\"ה, זאת חנוכה, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>צו דער רעדאקציע פון \"די אידישע היים\"<br>\nה' עליהם יחיו</p>\n<p>ברכה ושלום!</p>\n<p>צו דער געלעגנהייט פון דעם פינף-יאריגען יובילעאום פון \"די אידישע היים\", שיק איך מיין באגריסונג און ברכה צו די חשובע מיטגלידער פון דער רעדאקציע, ווי אויך צו די חשובע לייענער, פון דער פארדינסטפולער צייטשריפט.</p>\n<p>אין פארלויף פון די עטלעכע יאר פון דערשיינונג, האט \"די אידישע היים\", סיי מיטן אינהאלט און סיי אין אנדערע הינזיכטן, בארעכטיגט איר נאמען אלס אן עכט תורה-טרייע צייטשריפט פאר דער אידישער היים; א צייטשריפט וואס שטרעבט צו זיין אין איינקלאנג מיט דעם גייסט פון א אידישער היים, ווי א אידישע היים דארף זיין, און אויך פארשטארקען און בארייכערען דעם דאזיגען גייסט, דעם גייסט פון ריינקייט און קדושה, און מאכן ליכטיגער די אידישע היים מיט נר מצוה ותורה אור.</p>\n<p>און זאל מען זיך ניט איינריידן, אז עס איז שווער צו פירן א אידישע היים ווי עס באדארף צו זיין. אדרבה, - באמת איז שווער פאר א אידן, מצד זיין גאנצן מהות אלס איד, צו פירן זיך אנדערש, ווייל אלץ וואס עס איז פרעמד, קעגן דעם גייסט פון תורה און מצוות איז אין קעגנזאץ צו זיין אינערלעכער נאטור און אינערלעכן וועזן. ווי דער אלטער רבי, בעל התניא והשולחן ערוך, האט זיך אויסגעדריקט: א איד, ניט ער קען און ניט ער וויל, זיין אפגעריסן פון ג-טלעכקייט.</p>\n<p>די דאזיגע גרונט-השקפה ווערט אויך דייטלעך ארויסגעבראכט אין רמב\"ם (ספר נשים הלכה ב' סוף פרק ב), אין צוזאמענהאנג מיט דער הלכה, אז ווען מען צווינגט א אידן צו טאן א מצוה, טוט ער די מצוה מיט <b>אייגענעם ווילן.</b> אויבערפלעכלעך שיינט דא צו זיין א ווידערשפרוך. דערקלערט אבער דער רמב\"ם, אז <b>יעדער</b> איד וויל זיין א איד, און וויל טאן אלע מצוות און דערווייטערן זיך פון די עברות - נאר מצד איינרעדעניש מיינט ער אז ער וויל ניט. דער צוואנג איז דעריבער בלויז אום אראפצונעמען דעם צוואנג פון די פאלשע איינרעדעניש, וואס דאמאלס ווערט באפרייט זיין אמת'ער רצון צו טאן די מצוה פרייוויליג און גערן.</p>\n<p>די אויפגאבע פון \"די אידישע היים\" איז צו העלפן די לייענער צו פארשטיין טיפער און בעסער ווי און וואס אן אמת-אידישע היים דארף זיין; צו פארדינען און בארעכטיגען דעם דאזיגען נאמען אין דער פולסטער מאס, אזוי אז עס זאל זיין א היים פאר דער ג-טלעכער שכינה, ווי דער אויבערשטער האט צוגעזאגט <b>ושכנתי בתוכם</b> - איך וועל רוען צווישן זיי, בא יעדן אידן און אין יעדער אידישער היים.</p>\n<p>און וואו די שכינה רוט, דארט רוט אויך ברכה און הצלחה, מאטעריעל און גייסטיג.</p>\n<p>לויט דער אנווייזונג פון אונזערע חכמים אין דער משנה (אבות, סוף פרק ה) איז פינף יאר א תקופה וואס באווייזט די פרוכט פון הצלחה אין דעם געביט פון השפעה און דערציאונג. דער אויבערשטער זאל העלפן, אז די הצלחה פון \"די אידישע היים\" אין די ערשטע פינף יאר זאל זיין א סימן ברכה און הצלחה אויף ווייטער, און אין א שטייגענדער מאס, ווי עס ווערט גראדע אין די טעג - ספעציעל אונטערשטראכן אין דער מצוה פון נר חנוכה: יעדע נאכט פון חנוכה דארף צוקומען נאך א ליכטל, וואס דערמאנט אונז, אז מ'דארף כסדר פארשפרייטן נר מצוה ותורה אור אין א שטייגענדער מאס,</p>\n<p>און ווי דער רבי דער שווער כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע זאגט: \"מען דארף זיך צוהערן וואס די ליכטלעך דערציילען\".</p>\n<p>בברכה להצלחה - און אין אן אופן פון - מוסיף והולך ואור,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתקכב</b></i></h4>\n<p><b>אלטער רבי... אויסגעדריקט:</b> ראה גם לעיל ח\"כ אגרת ז'תרס, ובהנסמן בהערות שם.</p>\n<p><b>הלכה:</b> הל' גירושין.</p>\n<p><b>ושכנתי בתוכם... אידן:</b> הובא בשל\"ה פ' תרומה. ובכ\"מ.</p>\n<p><b>כ\"ק אדמו\"ר... זאגט:</b> ראה גם לעיל חי\"ד אגרת ד'תתקלט, ובהנסמן בהערות שם.</p>"],[1200970250,"ח'תתקכג\n\n<p>ב\"ה, י\"א טבת ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לכבוד הד\"ר שלמה שי' קודש</p>\n<p>שלום וברכה!</p>\n<p>הנני לאשר בתודה רבה קבלת מכתבו מכ' בכסלו וכן הספרים שהו\"ל. ובודאי אם יש לו עוד פרסומים ישלח אותם לספרי' שלנו שהיא לתועלת הרבים, ות\"ח מראש.</p>\n<p>כמנהג ישראל לקשר הענינים עם עניני דיומא, וכיון שמכתבו הגיע בימי החנוכה, הרי מהוראות נר חנוכה להיות מוסיף והולך בנר ואור, וכמבואר בכמה מקומות נר חנוכה הוא סמל נר מצוה ותורה אור וגם נר ה' נשמת אדם, שכל המוסיף בנר מצוה ואור תורה מוסיפין לו בכל המצטרך לו מנפש ועד בשר גם יחד.</p>\n<p>ועל פי כתבו על דבר גזע צור מחצבתו, האריכות בהאמור לדכוותי' בודאי אך למותר.</p>\n<p>בכבוד ובברכה.</p>\n<p>בנוגע לראיון נמסר למזכירות, ובודאי יתקשרו אתו.</p>"],[1200970251,"ח'תתקכד\n\n<p><i>[כ\"ג טבת תשכ\"ה]</i></p>\n<p>... רואה אני חובה להדגיש הפרצה הגדולה השוררת בשטח הענינים עליהם מדובר בסימני שו\"ע אבן העזר אלו, עקב חסרון הידיעה בזה בין המוני עם בנ\"י. שלכן ודאי שעל ידי פרסום חומר הענין יזהרו כמה וכמה בזה ויתקנו כפי הדרוש. ואציע נקודות אחדות לתשומת לבם:</p>\n<p>(א) בנוגע לניתוח הפרוסטטה, רובם ככולם של הרופאים כורתים (או מנתקים באופן אחר) כמה משבילי הזרע, ולא עוד אלא שמתחילים בזה (ניתוק השבילים) עוד קודם להניתוח עצמו. ובדברי עם כמה רבנים בעלי הוראה לא ידעו אשר יש כאן מקום לשאלה. ואף אם כי בכרך ראשון של אוצר הפוסקים בסופו נגעו בהאמור, הנה מפני שבא בחלק ההערות ולא קבעו מדור לענין זה בפני עצמו כי אם ביחד עם ענינים אחרים, מעטים ביותר היודעים ע\"ד השקו\"ט אשר שם, וגם אלו היודעים אין בידם מסקנא ברורה בנוגע לפועל.</p>\n<p>צריך עיון אם רוב הרופאים המנתחים יסכימו שלא לנתק כלל את שבילי הזרע, אבל בודאי רובם יסכימו שיבוא הניתוק בסיום הטיפול, אלא כדי שיתפרסם הדבר צריכה לבוא מסקנא ובאופן דקביעת מקום בפ\"ע, ולא בסוף כרך ובתוככי כו\"כ ענינים, כי אם במקום מתאים, ואולי גם בהוראה על זה במפתח כללי ובמפתח ענינים וכולי.</p>\n<p>ועוד להוסיף, שבאם יבואו רופאים מנתחים בעדות שעשו הטיפול האמור בלי ניתוק שבילי הזרע והצליחו, קרוב לומר שזה ישפיע על כמה רופאים אחרים שלא ינתקו כלל. והרי אפילו משום ספק ספקא כדאי הפרסום.</p>\n<p>(ב) מעין האמור ובהמשך לזה, כמה וכמה מקרים ישנם שביצה אחת נמצאת שלא במקומה והרופאים מטפלים בהורדתה לכיס, ויש עוד טיפול לבחון איפה נמצאת הביצה השני' וכו', אשר לפעמים גם במקרים אלו מנתחים ואופן הניתוח לפעמים תכופות קשור באיסור דאורייתא דכרות ונתוק וכו', אף שהטיפול אפשר שייעשה באופן אחר, ובכמה מקרים באופן המותר גם לכתחילה. אלא שאין ההורים יודעים שיש כאן מקום לספק ולשאלת רב. ומה שנוגע עוד יותר הוא שכמה רבנים מורי הוראה אינם יודעים הפרטים האמורים. וגם בזה פרסום בכרך הבא במקום מתאים בודאי שיועיל למנוע מכשול.</p>\n<p>כל האמור הוא גם בנוגע לטיפול בשבר שבכיס, בהוספה שזה נוגע לא רק לקטנים אלא גם לגדולים וכולי.</p>\n<p>(ג) עוד בעי' והיא קרובה ועקרית, ולא עוד אלא שמזמן לזמן מתגדלת התקלה, והיא בשאלת אימוץ ילדים. מספר המשתדלים לאמץ ילדים הולך ורב, וכפי שראיתי בכמה וכמה מקרים של זוגות המקפידים אפילו בדקדוק קל של דברי סופרים, <b>לא</b> <b>שמים לב כלל</b> שכל עניני איסור יחוד חיבוק ונישוק וכו' וכו' קיימים בתקפם בנוגע לילדים המאומצים, ראיתי בכמה ספרים וחוברות שמטפלים בבעי' איך להבטיח שלא ישא אח את אחותו וכו' וכן יש שדנים בנוגע לשאלת ירושה וכו'; אבל הרי כל זה בא לאחרי כמה שנות אימוץ, והם בגדר ספק, וכמה רק בעניני ממונות, משא\"כ איסורים הנ\"ל (יחוד וכו') הם בגדר ודאי ומתחילים כו\"כ שנים לפני שמגיעים הילדים לפרקם.</p>\n<p>פשוט שאין האמור לעיל דומה לענין גידול יתום ויתומה שהי' נפוץ בין בנ\"י, כיון שבשנים אלו כוונת המאמצים היא להעלים מהילד המאומץ שאינם הוריו האמתיים, ומשתדלים ומדייקים בזה שלא להראות כל תנועה וענין שיעוררו חשד בלב הילד המאומץ שהיחס אליו אינו דומה להיחס לחבריו מצד הוריהם הם, ולא עוד אלא שכמה מהמוסדות המחלקים ילדים לאימוץ מקבלים (או גם דורשים) הבטחה מראש שהילד יגדל ללא כל סיבוכים והפרעות, זאת אומרת שיהי' היחס אליו בכל הפרטים כמו לבן ובת מבטן ומלידה, ובאים ומוסיפים רופאים ופסיכולוגים שמוכרח יחס כזה כדי שיהי' החינוך בלי תקלות, ובודאי לדכוותייהו האריכות אך למותר, ורק להוסיף אשר מספר הילדים המאומצים הוא <b>כמה</b> פעמים ככה מאשר משערים או מודיעים בעלי הסטטיסטיקה, כיון שכמה מהמאמצים ועוד יותר כמה מהמוסרים ילדיהם</p>\n<p>לאימוץ - אינם רוצים כלל בפירסום מכו\"כ טעמים*.</p>\n<p>ולכן כל הפרסום וכל האזהרות על דבר חומר הענין וכו' שיתנו בכרך הבא, הלואי שיספיק להביא התיקון המוכרח סו\"ס לבוא בענין האמור, ואף שלכאורה המקום לפרסום האמור צריך להיות בספר הנקרא על ידי בעלי-בתים ואותם הרוצים לאמץ ילדים, אבל ההתחלה בזה ראוי' שתבוא בספר כאוצר הפוסקים וכיו\"ב, בהדגשה מתאימה על האיסור ואשר נשנה האיסור בכל יום ויום, ובתנאי תקופתנו כמעט שאי אפשר להזהר ממנו, כי אם על ידי השתדלות קפדנית ומתמידה, ואפילו אם יהיו מאמצי הילדים יראי השם.</p>\n<p>ופשוט שביד מערכת אוצר הפוסקים, בתור קובץ למורי הוראה בישראל, לדרוש מירחונים ושבועונים ומכתבי עתים לפרסם ענין האמור, ויש מקום לומר שימלאו בקשתם ודרישתם בזה.</p>\n<p>בכבוד ובברכה אשר יצליח ה' מלאכתם בקדש להורות לעם ה' דרך המלך היא דרכו של ממה[\"מ ה]קב\"ה באורח חייהם, וכנ\"ל - בדברים אשר תוצאותיהם עד סוף כל הדורות.</p>\n<p><b>מ. שניאורסאהן</b></p><p><i>ח'תתקכד</i></p>\n<p>האגרת הוא להנהלת אוצר הפוסקים. חלקה נדפס באוצר הפוסקים אה\"ע ח\"ט (ירושלים תשכ\"ה) ע' קל בלקו\"ש חי\"ב ע' 212 וע' 193 והושלמה עפ\"י הנדפס ב\"המאור\" חוברת קנד (תמוז תשכ\"ה).</p>\n<p><b>לניתוח הפרוסטטה:</b> ראה גם לעיל ח\"כ אגרת ז'תרלג, ובהנסמן בהערות שם.</p>\n<p><b>בשאלת אימוץ ילדים:</b> ראה גם לעיל אגרת ח'תש, ובהנסמן בהערות שם.</p>\n<p><b>שביד מערכת אוצר הפוסקים:</b> ראה גם לקמן אגרת ח'תתקנד.</p>\n<p>*) אם שייך כהנ\"ל גם במי שנושא אשה שיש לה בנות מבעל אחר או אשה שנושאת איש שיש לו בנים מאשה אחרת, העיר כ\"ק האדמו\"ר שליט\"א:</p>\n<p>צודק ששייך, אלא שבהנ\"ל - ע\"ד המגדל יתום כו' ששיבוחוהו חז\"ל - <b>אין מעלימים</b> שאין זה בתה (או בנו) ובמילא שניהם נזהרים (ולא ברשיעי עסקינן), משא\"כ בנדו\"ד <b>שמשתדלים</b> להעלים והרגל נעשה טבע וכו'.</p>"],[1200970252,"ח'תתקכה\n\n<p><i>[כ\"ד טבת תשכ\"ה]</i></p>\n<p>ויהא כהנ\"ל בהצלחה רבה ומגלגלים זכות (טהרה ודכויי - ולא רק בנוגע לעצמו - (תחטאיני) - כ\"א גם - וחיטא את <b>הבית</b> חולין כ\"ז רע\"א) ליום זכאי (<b>ולהעיר</b> ממש\"כ בכו\"פ סו\"ס י\"א שבזמנינו אין לחוש אפילו לשחוט אווז בטבת) - הילולא דאדה\"ז שהוראתו היינו נתינת כח - ששו\"ב ה\"ה יר\"ש ביותר וחרד על דבר ה' שלם בדעתו וכו' (הל' שחיטה ס\"א סק\"ב, ושקו\"ט בשו\"ת צ\"צ יו\"ד סי\"ב).</p>\n<h4><i><b>ח'תתקכה</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"א ע' 198. חל\"ב ע' 183. והיא מענה למו\"ה אלי' שמואל הכהן כהנוב, ונכתבה על גליון מכתבו מיום כ\"ד טבת תשכ\"ה. אגרת נוספת אליו - לעיל ח\"ד א'צט.</p>\n<p><b>ויהא כהנ\"ל:</b> נכתב במענה לההודעה על קבלת התלמידים דישיבת תו\"ת \"הוראה\" לשחיטה ביום כ\"ד טבת.</p>\n<p><b>ומגלגלים:</b> תענית כט, א.</p>"],[1200970253,"ח'תתקכו\n\n<p>ב\"ה, כ\"ה טבת, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>ד\"ר ש. פרידלנדר שי'</p>\n<p>שלום וברכה!</p>\n<p>הנני לאשר קבלת ספרו Pie XII et le IIIe Reich ות\"ח על שלחו לי.</p>\n<p>ועל דבר חשיבות עבודתו בודאי למותר להאריך, ורק אוסיף שחשיבות זו אינה ענין אך ורק להיסתורי' לדורות הבאים אלא חשיבות מיוחדת נודעת לה בתקופתנו זו, כי לצערנו הרב יש משתמשים עד היום במיסיון וכולי במעשיות בדויים שלא היו ולא נבראו כדי לנתק בני ובנות ישראל מדת אבותיהם, מחיי תורה ומצוותי'. ובא ספרו ולא רק מכחיש כמה וכמה מהם אלא מוכיח שההיפך הוא האמת.</p>\n<p>ואף שלאמתו של דבר אין תורתנו ודתנו צריכות ראי' ממקום אחר, שהרי גלוי וידוע שהתורה היא עצם חיות עם ישראל וכל פעולה נגדית חותרת מתחת יסוד קיום עמנו, קיום היחיד והכלל, אבל בכל זה יש אנשים וחוגים שמסיבות ומטעמים שונים עדיין זקוקים להוכחה בזה משטחים אחרים, אם משטח ההיסתורי', או הארכיאולוגי' וכדומה.</p>\n<p>ומה המציל נפש אחת כאילו קיים עולם מלא, על אחת כמה וכמה המשפיע בכיוון זה על כמה מאחינו בני ישראל ומעמידם על קו האמת.</p>\n<p>רואה אני על השער שכ' מתכונן להכין עוד עבודה באותה תקופה. ויהי רצון אשר ההצלחה תלווהו גם בזה.</p>\n<p>בכבוד ובברכה.</p>\n<p>תקותי שישלח פרסומיו שיצאו לאור עד עתה ושעתידים לצאת לאור לספרי' שלנו לתועלת הרבים, ותודה מראש.</p>\n<h4><i><b>ח'תתקכו</b></i></h4>\n<p><b>ומה המציל:</b> סנהדרין לז, א.</p>"],[1200970254,"ח'תתקכז\n\n<p>ב\"ה, ר\"ח שבט, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת המכתב מיום...</p>\n<p>ומענין יום זה:</p>\n<p>אמרה תורה: בעשתי עשר חדש באחד לחדש - הואיל משה באר את התורה, ופירש רש\"י בשבעים לשון פירשה להם.</p>\n<p>אתפשטותא דמשה בכל דרא ודרא לששים רבוא נשמות, אלא שהיא בהעלם</p>\n<p>והסתר גדול.</p>\n<p>יתרה מזה - בכל צדיק וחכם דמתעסק באורייתא.</p>\n<p>ועוד זאת יתר על כן בכל דור ודור יורדין ניצוצין מנשמת מרע\"ה ומתלבשין בגוף ונפש של חכמי הדור עיני העדה ללמד דעת את העם כו' ולעבוד ה' בלב ונפש.</p>\n<p>מכל האמור מובן אשר ללמד דעת ועבודת ה' את העם צ\"ל עד לפירוש בשבעים לשון, באם ישנו מי בעם הזקוק לזה.</p>\n<p>במוחש נראה לימוד באופן זה אצל כ\"ק מו\"ח אדמו\"ר, אשר ציווה והעתיקו ד\"ת כולל גם דברי תורת החסידות לכו\"כ לשונות - לשונות כפשוטן, וגם שבעים לשון ופנים בלשון חד דתורה - לבאר גם חלק הסוד שבתורה, שבדורותינו נתגלה בתורת החסידות, לכאו\"א גם לפשוטי העם.</p>\n<p>ובכל זה - גם בנוגע להורותם דרך לעבודת ה' בלב ונפש.</p>\n<p>ויה\"ר אשר בימים אלו הסמוכים ליום ההילולא שלו, וביתר שאת וביתר עז ביום ההילולא עצמו - הוא יום העשירי בעשתי עשר חדש - יתעורר כאו\"א להחלטות טובות - שתבואנה אח\"כ בפועל טוב, במעשה טוב שהוא העיקר - ללכת בדרכיו ואורחותיו הנ\"ל - הליכת קבע ותמידית, באופן של - נצח סלה ועד שאין לו הפסק עולמית.</p>\n<p>וימשיך זה ויוסיף בכל הענינים להם \"מסוגל הוא היום הזה\" וכלשון רבנו נשיאנו בעל ההילולא:</p>\n<p>להתקשר בעץ החיים, לקבל, אתם נשיכם בניכם ובנותיכם, ברכת ה' בשפעת חיים ופרנסה טובה ונחת מיו\"ח, וברוכים תהיו בבני חיי ומזוני רויחי.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתקכז</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ו ע' 266 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>ויה\"ר:</b> ראה גם לקמן אגרת ח'תתקלב.</p>\n<p><b>במעשה:</b> אבות פ\"א מי\"ז.</p>\n<p><b>וכלשון רבנו:</b> אג\"ק שלו ח\"ב אגרת תלב. ח\"ד א'ד.</p>\n<p><b>אמרה תורה: </b>דברים א, ג-ה.</p>\n<p><b>פירשה להם: </b>מדייק רש\"י \"להם\" - לבני ישראל ולא לאו\"ה (שאסורים ללמוד תורה) - ושאני כתיבת התורה בע' לשון שלא הייתה אלא לבוא וללמדה כל הרוצה מן האומות (סוטה לה, ב. ומסיים: ולא למדו), שהי' ע\"פ הדיבור.</p>\n<p><b>אתפשטותא... נשמות: </b>אגה\"ק סוף הביאור לסי' זך (מתקו\"ז תס\"ט קיב, א. קיד, א).</p>\n<p><b>בהעלם והסתר גדול: </b>אגה\"ק שם. (בתניא פמ\"ד \"בבחי' הסתר והעלם גדול\", ואולי יל\"פ החילוק כי כאן מדבר ע\"ד אופן <b>מציאותה</b> בנשמה, ובאגה\"ק - באופן הארתה ממרע\"ה שבתחלה מתעלם האור ואז אפשר שיהי' הסתר).</p>\n<p><b>בכל... באורייתא: </b>תקו\"ז שם (קיב, א). וראה רש\"י ד\"ה משה (חולין צג, א). תו\"א סד\"ה משה ידבר.</p>\n<p><b>ועוד זאת... ונפש: </b>ולא בגוף ע\"י התלבשות בנפש תחלה, כ\"א ע\"ד כמו בגוף מרע\"ה, היינו שגם מצד גופם נקראים משה.</p>\n<p><b>שבעים לשון... דתורה: </b>משה רעיא מהימנא בזח\"ג כ, א.</p>\n<p><b>בדרכיו... ועד: </b>ראה אגה\"ק סי' זך.</p>\n<p><b>נצח... הפסק עולמית: </b>עירובין נד, א.</p>\n<p><b>וכלשון רבנו: </b>קונטרס ג; קונטרס לו.</p>"],[1200970255,"ח'תתקכח\n\n<p>ב\"ה, ב' שבט, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לכבוד מר יוסף שי' דקל</p>\n<p>שלום וברכה!</p>\n<p>באתי להביע לכ' ת\"ח למפרע בעד הבטחתו למלא בקשת הספרן לשלוח לספרי' שלנו עניני דפוס המבוקשים.</p>\n<p>בהזדמנות זו רצוני לעורר על הפרשה בנצרת עילית, שבודאי להיותו במקום יודע פרטי הענינים והמצב עוד יותר ממני. ואביע תקותי אשר עושה כל התלוי בו לקרב את הלבבות בקירוב אמתי. כוונתי קירוב לבב בנ\"י אחד לרעהו, ובאמת, שתלוי ועולה בד בבד עם קירוב הלבבות לאבינו שבשמים, הנקרא לבן של ישראל.</p>\n<p>- וזכורני סיפורו על העמל שהשקיע בביסוס העיר והרי - אדם חס על מעשי ידיו.</p>\n<p>בכבוד ובברכה לבשורות טובות.</p>\n<h4><i><b>ח'תתקכח</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ב ע' 309 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>מר יוסף דקל:</b> אגרות נוספות אליו - לעיל ח'תרצט, ובהנסמן בהערות שם.</p>\n<p><b>הנקרא:</b> שהש\"ר פ\"ה, ב.</p>"],[1200970256,"ח'תתקכט\n\n<p>ב\"ה, ד' שבט, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לכבוד הרב שלמה שי' טרשנסקי</p>\n<p>שלום וברכה!</p>\n<p>מאשר אני קבלת מכתבו מי\"א בטבת, ות\"ח על הציונים ומ\"מ בטעם מה שלא נמצא קרובץ דפורים בברכת את צמח דוד.</p>\n<p>כן, כמובן, ת\"ח כפולה על פעולתו בנוגע להדפסת חידושי הגאון הרגטשובי על המורה נבוכים, שבודאי תצא לפועל בקרוב, נוסף על פעולתו בעבר בהוצאת חידושי הגאון הנ\"ל. ובאמת אין התואר \"חידושים\" הולמם ומכילם, כי חידושיו הם שלא בערך למעלה ממובן הרגיל של מלת \"חידוש\". ובסגנון המונחים בתורת החסידות, מלאים הם אור הממלא את הכלי ועוד כהנה וכהנה אשר לא יכילנו הכלי ומקיף עליו מלמעלה.</p>\n<p>מצורף בזה מה שהו\"ל לאחרונה, שבודאי יענין את כת\"ר.</p>\n<p>בכבוד ובברכה לבשו\"ט תכה\"י.</p>\n<h4><i><b>ח'תתקכט</b></i></h4>\n<p><b>הרב שלמה טרשנסקי:</b> אגרת נוספת אליו - לעיל חכ\"ב ח'שפה.</p>"],[1200970257,"ח'תתקל\n\n<p>ב\"ה, ד' שבט, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לכבוד הוו\"ח אי\"א נו\"מ בחור מעם ומורם<br>\nמעם ודורש טוב<br>\nלעמו בעל מדות תרומיות ענף עץ אבות<br>\nמו\"ה שניאור זלמן<br>\nשליט\"א</p>\n<p>שלום וברכה!</p>\n<p>יום ההילולא של כ\"ק מו\"ח אדמו\"ר ממשמש ובא. ואם כפר חב\"ד עולה בזכרונינו תכופות בכלל, בודאי שיום זה הבע\"ל מעורר ומעלה זכרון הכפר ביתר תוקף.</p>\n<p>וכאן מקום אתי להביע עוה\"פ תקותי החזקה - אף שאיני יודע מה צריך להיעשות בזה - שסוף סוף ייעשו המאמצים הדרושים שיאפשרו לכפר חב\"ד להוות מקום מקלט למספר הגון של ידידיהם ואחיהם של תושבי הכפר, ואחיהם לצרה בעבר - יהיו ב\"ב עמהם וחבריהם להתיישבות באה\"ק ת\"ו, ארץ אשר עיני ה\"א בה מראשית השנה ועד אחרית שנה, אשר גם עיניהם של אחב\"י הנתונים בצרה ושבי' נשואות אלי'.</p>\n<p>מסופקני אם הייתי כותב לכ' עוד הפעם בענין זה, בפרט שכ' הי' ממיסדי כפר חב\"ד. אלא שהענין הולך בכבדות ובתסבוכת שלא על דרך הרגיל. ובענין הזה אם הי' צורך גדול בהוכחה שהוא ענין שבקדושה אפשר שהי' מקום לתסבוכת וקושיים (אבל לא כאלו), אבל פשוט הדבר שהענין קדוש הוא כשלעצמו, נוסף על העיקר שכפר חב\"ד הוא הצנור להפצת המעיינות. ועוד שהרי כבר יצאו ידי חובת כל הצדדים בקושיים והסתרים.</p>\n<p>ויהי רצון אשר בקרוב ממש יתרחב ויתפשט כפר חב\"ד גם כפשוטו, בשטחי אדמה נוספים הלוך ומוסיף, ובזמן קרוב לאחרי זה ייבנו גם שטחים אלו במוסדות חב\"ד ויתמלאו בעולים חדשים ממדינתנו לפנים, אשר יעלו משם הם ובניהם ובנותיהם וכל אשר להם בחסד וברחמים, וימשיכו במסורת חב\"ד ובדרך חיים על פי תורת חב\"ד, מיוסדת על שלשת האהבות, אהבת ה' אהבת התורה ואהבת ישראל, בארץ ישראל.</p>\n<p>בכבוד ובהוקרה ובברכה.</p>\n<p>בודאי נתקבל מכתבי מראש חודש שבט, והרי גם מכתבי הקודם פרק בעלי' ממיצר אל המרחב.</p>\n<p>זה עתה הביאו מבית הכורך דבר בעתו מעניני ימים אלו והוא חלק שני של <b>ספר</b> <b>הזכרונות</b> (אידיש), ונשלח לכ' בפ\"ע.</p>\n<h4><i><b>ח'תתקל</b></i></h4>\n<p><b>מו\"ה שניאור זלמן:</b> שזר. אגרות נוספות אליו - לעיל ח'תרפב, ובהנסמן בהערות שם.</p>\n<p><b>ב\"ב:</b> במהרה בימינו.</p>"],[1200970258,"ח'תתקלא\n\n<p>ב\"ה, ד' שבט, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>צו אלע אנטיילנעמער אין דעם יערלעכן<br>\nדינער<br>\nפאר דעם מוסד חינוך אהלי תורה<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>דער היי-יארדיגער דינער קומט פאר אור ליום חמשה עשר בשבט, ראש השנה לאילנות. דאס אונטערשטרייכט די ספעציעלע פארבינדונג פון דער אונטערנעמונג מיט דעם טאג. ווארום, ווי באקאנט, זאגט די תורה, אז דער מענטש איז גלייך צו א בוים (האדם עץ השדה), וואס דערמיט גיט אונז די תורה א וויכטיגע לערע און אנווייזונג; ספעציעל אין דעם געביט פון חינוך.</p>\n<p>ווען דער בוים איז יונג, נאכמער - ווען ער איז נאך אין דער פארם פון א גרעין, א קערנדל, דאן איז יעדע גוטע באהאנדלונג, ווי קליין און מינדערווערטיג זי זאל זיך אויסווייזן, א זאך וואס ווערט מיט דער צייט פארגרעסערט אויף א פילפאכיגען אופן, און די פולע רעזולטאטען קומען צום אויסדרוק אין דעם דערוואקסענעם בוים און אין די פרוכט וואס ער טראגט.</p>\n<p>דאס גלייכן איז די פרטיות'דיגע ווירקונג אויף א קינד, אפילו אין א פעולה וואס קאן זיך אויסווייזן אויפן מאמענט אלס גאר א קליינע, אזוי אז מען נעמט איבערטראכטן אויב עס איז גאר כדאי צו לעגען מי און ענערגיע אויף דעם - קען אבער אויך די \"קליינע\" פעולה פארוואנדלט ווערן אין אן אויסערגעוויינלעך גרויסע און דויערנדע השפעה אין דער טאג-טעגלעכער הנהגה על פי תורה ומצוות. און ווי חכמינו ז\"ל זאגן, אז די אמת'ע פירות זיינען די מצוות (מאי פירי - מצוות). דעריבער איז יעדער אנשטרענגונג בארעכטיגט אין דעם שעביט פון חינוך, ווארום דא האנדלט זיך וועגן די גאנצע צוקונפט פון דעם תלמיד און זיין לעבנס-לענגלעכע טובה.</p>\n<p>דער מוסר חינוך <b>אהלי תורה</b> איז א מוסד וואו דער דערמאנטער צוגאנג ווערט אויפגעהאלטן און באנוצט לטובת די תלמידים שי'. דער מוסד פארדינט, דעריבער, א ספעציעלע אנשטרענגונג מצד די בעלי-בתים און פריינד צו שאפן די געהעריגע שטיצע פאר דער אויסהאלטונג און אויסברייטערונג פון דעם מוסד, אין כמות און אין איכות.</p>\n<p>עס איז צו האפן, אז אלע חובבי תורה ומצוה וועלן זיך ווארים אפרופן אויף דעם הילפס-רוף פון דעם מוסד חינוך אהלי תורה און וועלן געבן זייער שטיצע מיט א ברייטע האנט.</p>\n<p>איך שיק מיין באגריסונג און ברכה צו די חשובע געסט און אלע אנטיילנעמער שיחיו.</p>\n<p>בכבוד ובברכת הצלחה.</p>\n<h4><i><b>ח'תתקלא</b></i></h4>\n<p>חלקה נדפס בלקו\"ש ח\"ו ע' 311 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>ווי חכמינו:</b> סוטה מו, סע\"א.</p>"],[1200970259,"ח'תתקלב\n\n<p>ב\"ה, יום ראשון לפ' ובנ\"י</p><p>ברוקלין, נ.י.</p><p>יוצאים ביד רמה, ה'תשכ\"ה</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכ' מיום...</p>\n<p>ויה\"ר אשר בימים אלו הסמוכים (מלפניו ומלאחריו) ליום ההילולא של כ\"ק מו\"ח אדמו\"ר, וביתר עז ביום ההילולא עצמו - הוא יום העשירי בעשתי עשר חדש - יתעורר כאו\"א להחלטות טובות - שתבואנה אח\"כ בפועל טוב, במעשה טוב שהוא העיקר - ללכת בדרכיו אשר הורנו ובאורחותיו, לחזק היהדות המסורתית ולהפיצה ועד להפצת המעינות חוצה - הליכת קבע ותמידית, באופן של נצח סלה ועד שאין לו הפסק עולמית.</p>\n<p>וימשיך זה ויוסיף בכל הענינים להם \"מסוגל הוא היום הזה\" וכלשון רבנו נשיאנו בעל ההילולא:</p>\n<p>להתקשר בעץ החיים, לקבל, אתם נשיכם בניכם ובנותיכם, ברכת ה' בשפעת חיים ופרנסה טובה ונחת מיו\"ח וברוכים תהיו בבני חיי ומזוני רויחי,</p>\n<p>עדי יוציאנו ה' למרחב בגאולה האמתית והשלימה ע\"י משיח צדקנו ובנ\"י יוצאים ביד רמה.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><p>* * *</p>\n<p>בנוגע למוסד - מה שאפ\"ל מכאן: ההצלחה דע\"ע בענין <b>החיוני</b> דחינוך בנ\"י מוכיחה, אשר: 1) ההכרח להמשיך, 2) תומשך ההצלחה גם להבא כשתהי' עכ\"פ אחיזה בדרך הטבע. - הדרך לפעולה ופרטי', מובן שזה אפשר לקבוע רק על אתר.</p>\n<p>פשוט שהצעתי מאז ע\"ד ה' אלף ל\"י כו' - בתקפה הוא.</p>\n<p>בברכה לרפואה ולהרחבה (כמובן - לכל לראש במוחין - ובמילא יתרחב בהמוסד) ולבשו\"ט מתוך שמחה וט\"ל.</p>\n<h4><i><b>ח'תתקלב</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ו ע' 291 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>ויה\"ר:</b> ראה גם לעיל אגרת ח'תתקכז.</p>\n<p><b>במעשה:</b> אבות פ\"א מי\"ז.</p>\n<p><b>וכלשון רבנו:</b> אג\"ק שלו ח\"ב אגרת תלב. ח\"ד א'ד.</p>\n<p><b>בנוגע:</b> קטע זה למו\"ה אלכסנדר בונין. אגרות נוספות אליו - לעיל חכ\"ב ח'שכז, ובהנסמן בהערות שם.</p>\n<p><b>ראשון: </b>ראה פסחים ח, א.</p>\n<p><b>מלפניו ומלאחריו: </b>להעיר ממכילתא יתרו כ, ח. שו\"ע אדה\"ז סרס\"א ס\"ד.</p>\n<p><b>בדרכיו... ועד: </b>ראה אגה\"ק סי' זך.</p>\n<p><b>נצח... עולמית: </b>עירובין נד, א.</p>\n<p><b>וכלשון רבנו: </b>קונטרס ג. קונטרס לו.</p>"],[1200970260,"ח'תתקלג\n\n<p>ב\"ה, ח' שבט, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו' מו\"ה<br>\nשלמה שי'</p>\n<p>שלום וברכה!</p>\n<p>ס'איז איבעריק צו זאגן, אז איך פרעג זיך נאך אויף אייך גאנץ אפט און באקום לעבעדיקע גרוסן וועגן אייער געזונט צושטאנד און פעולות פאר בית ליובאוויטש.</p>\n<p>דערנעענטערנדיק זיך צום סגולה טאג פון יום ההילולא פון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע דערמאנט מען זיך נאטירלעך וועגן אלע גוטע פריינט וועלכע זעצן פאר זיין הייליקע ארבעט אויף די פארשידענע פראנטן אין דער ברייטער וועלט, ניט נאר אנצוהאלטן די מיט-גרויס-מי-דערארבערטע פאזיציעס, נאר אויך צו פארשטארקן און אויסברייטערן זיי - פאר החזקת התורה והמצוות און הפצת המעיינות.</p>\n<p>דערביי האט מען די פארזיכערונג, אז דער רבי דער שווער שטייט אויף דער וואך און איז נושא רינה ותפלה פאר אלע זיינע \"סאלדאטן\", זיי זאלן מצליח זיין אין זיין שליחות און זאלן געבענטשט ווערן אין אלץ וואס מען נויטיקט זיך בגשמיות וברוחניות גם יחד.</p>\n<p>בא דער געלעגנהייט וועט מען אייך ספעציעל מזכיר זיין אויף דעם ציון פון כ\"ק מו\"ח אדמו\"ר, און דער אויבערשטער זאל העלפן, אז דער זכות פון אייערע פעולות פאר די מוסדות פון בעל ההילולא זאל אייך און אלע אייערע ב\"ב שיחיו ביישטיין צו געניסן פון דער פולער מאס פון ברכות ה' בכל המצטרך, בפרט א פארבעסערונג אין געזונט צושטאנד ומאור עיניו בקרוב ממש.</p>\n<p>בברכה להצלחה ולבשורות טובות.</p>\n<h4><i><b>ח'תתקלג</b></i></h4>\n<p><b>מו\"ה שלמה:</b> פערין. אגרות נוספות אליו - לעיל חכ\"א ז'תתקסה. חי\"ח ו'תשעה, ובהנסמן בהערות שם.</p>\n<p><b>בית ליובאוויטש:</b> לונדון.</p>"],[1200970261,"ח'תתקלד\n\n<p>ב\"ה, ט' שבט תשכ\"ה</p><p>ברוקלין.</p><p>ב\"ד מרת שיינא זעלדא תי'</p>\n<p>ברכה ושלום!</p>\n<p>במענה למכתבה - בנוגע לנוסח המצבה שכותבת, לדעתי נכון להזכיר שם האב - דודי - בעל הנפטרת ז\"ל (בהוספה שהוא מגזע אדמו\"ר הזקן וכו'), וכמובן שם אבי' (הררד\"צ ז\"ל).</p>\n<p>הנוסח בפרטיות - יש להתייעץ עם רבני אנ\"ש שי' <b>על אתר</b> - כיון שבכגון זה צריך להתחשב עם הנהוג בבית-החיים זה וצ\"ל הוראת הרב במקום.</p>\n<p>בקשתי את ידידי הרה\"ח וכו' הרב אברהם שי' לשתפני בהוצאות האישפוז בביה\"ח וכו'.</p>\n<p>מברקי והמכתב הקודם בטח נתקבלו בעתם.</p>\n<p>בברכה כפולה שמכאן ולהבא אך טוב בטוב הגלוי יהי' תוכן המכתבים שבינינו ובפ\"ש כל המשפחה שי' ב\"ד המאחל כ\"ט.</p>\n<h4><i><b>ח'תתקלד</b></i></h4>\n<p><b>מרת שיינא זעלדא:</b> ש\"ס-מישקובסקי, ירושת\"ו. אגרת נוספת אלי' - לעיל חכ\"א ח'ד.</p>\n<p><b>דודי:</b> הרה\"ח ר' שלום שלמה שניאורסאהן.</p>\n<p><b>הנפטרת:</b> מרת רחל שניאורסאהן.</p>\n<p><b>בהוספה... הזקן:</b> ראה גם לעיל ח\"כ אגרת ז'תקמד, ובהנסמן בהערות שם.</p>\n<p><b>הרד\"צ:</b> חן.</p>\n<p><b>הנוסח:</b> ראה גם לעיל ח\"כ אגרת ז'תקמד.</p>"],[1200970262,"ח'תתקלה\n\n<p><i>[נוסח המברק לקראת יו\"ד שבט תשכ\"ה]</i></p>\n<p>התועדויות פעילות וכפרשת השבוע ביד רמה ובשירה ובשיר להשם, תורת הנגלה והחסידות.</p>\n<p>בברכה.</p>\n<p><b>/מקום החתימה/</b></p>\n<p>יד הרמה - תורה.</p>\n<p>שיר ושירה - זו\"ן. עה\"ח ועה\"ד. נגלה ונסתר, - עיין בכ\"ז בלקו\"ת (כמצוין במפתח) ובכ\"מ.</p>\n<h4><i><b>ח'תתקלה</b></i></h4>\n<p>נדפס בסה\"מ מלוקט ח\"א ע' שעב.</p>"],[1200970263,"ח'תתקלו\n\n<p>ב\"ה, י\"ב שבט תשכ\"ה</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א בנש\"ק וכו' מו\"ה<br>\nאלימלך אלטר שי'</p>\n<p>שלום וברכה!</p>\n<p>... להמדובר דישנה שקו\"ט בהאוכל חמץ בפסח אף שעבר על איסור דאורייתא מ\"מ מקיים עשה דתשביתו ומסלק הלאו דבל יראה - מצאתי רשום אצלי שכ\"כ בס' תשובה מאהבה סקפ\"ב ודלא כטעם המלך על הרמב\"ם הל' חו\"מ פ\"א ה\"ג. ואין הס' תח\"י עתה.</p>\n<p>- והשגות הראב\"ד והרמב\"ן על בעל המאור (לרי\"ף פ\"ק דפסחים) - יש לפרש דעתם דאסור לאכול אבל אם עבר ואכל קיים העשה וכו'.</p>\n<h4><i><b>ח'תתקלו</b></i></h4>\n<p><b>מו\"ה אלימלך אלטר:</b> פאנעט, ברוקלין.</p>"],[1200970264,"ח'תתקלז\n\n<p>ב\"ה, ערב ט\"ו בשבט, תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>ילדים יקרים שי'</p>\n<p>שלום וברכה!</p>\n<p>קבלתי בשמחה את הציורים שלכם עם מכתב המורה והגננת שלכם מרת רחל שתחי' זמיר.</p>\n<p>הציורים והמכתב הגיעו לידי לפני ההילולא (יארצייט) של כ\"ק מו\"ח אדמו\"ר, והמענה שלי נכתב ערב ט\"ו בשבט, ראש השנה לאילנות. והרי גם בציוריכם ראיתי ילדים וילדות ואילנות ופרחים. ולקשר את כל הענינים האלה, אזכיר לכם החיבה והאהבה היתרה שרחש כ\"ק מו\"ח הרבי לכל בני ובנות ישראל, הגדולים עם הקטנים, ובפרט הקטנים אשר דאג לחינוכם ולטובתם בכל מקום שהם, ובכל ילד וילדה ראה שתיל העתיד לגדול ולהיות עץ-פרי הדר נושא פירות טובים ונחמדים. אמנם דבר זה תלוי ברצונם ועבודתם של הילד והילדה, והמשל לזה הוא האילן. כשנוטעים גרעין או שתיל רך, צריך לשמור עליו מעשבים רעים וכל מיני מזיקים, ולהספיק לו מים וכולי, עד אשר יגדל ויהי' לאילן נושא פירות טובים. והוא הדבר בכל ילד וילדה, אשר אמר השם יתברך על ידי נביאו שהם \"נצר מטעי מעשה ידי להתפאר\". והנה הבורא יתברך נטע בתוככם נשמה קדושה, חלק אלוקה ממעל ממש, ועליכם לשמור \"גרעין\" אלוקי זה מעשבים רעים ומזיקים, זאת אומרת מחברים בלתי הגונים, ולהספיק לו מים חיים, ואין מים אלא תורה, תורת חיים, ומצוותי' שחיים הם לעושיהם, ואזי יתן ויחזור ויתן לכם השם יתברך ברכתו שתצליחו להיות \"אילנות\" נושאי פירות טובים ומשובחים, לשמחת הוריכם ומוריכם ולגאון ולתפארת עמנו, עם בני ישראל.</p>\n<p>בברכה להצלחה ולבשורות טובות,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתקלז</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ו ע' 310 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>ואין מים:</b> בבא קמא יז, א.</p>"],[1200970265,"ח'תתקלח\n\n<p>ב\"ה, ט\"ו בשבט, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לכבוד מר מרדכי שי' איש-שלום<br>\nראש העיר, ירושלים עיה\"ק ת\"ו</p>\n<p>שלום וברכה!</p>\n<p>ת\"ח בעד הפ\"ש על ידי הרב נחום שי' רבינוביץ, וביחוד גם בעד שימת לבבו ואות השתתפותו בהתועדות ההילולא. וכאן מקום אתי להביע לכ' הכרת תודה בעד העזר שהושיט עד עתה למוסדות כ\"ק מו\"ח אדמו\"ר נבג\"מ זי\"ע בירושלים עיה\"ק ת\"ו, והתקוה שגם להבא יעשה ויוסיף כהנה וכהנה. ובודאי יודע כ' עוד יותר ממני צרכי המוסדות, אשר על עזר כל בני העיר הם נשענים, ובפרט ראש העיר.</p>\n<p>בכבוד ובברכה.</p>"],[1200970266,"ח'תתקלט\n\n<p>ב\"ה, ט\"ו שבט תשכ\"ה</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ צנמ\"ס עוסק בצ\"צ כו'<br>\nהר\"מ שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתביו, בם מציע אשר אבוא בכתובים לברר פסקי הלכות למעשה בכמה ענינים שמונה וסופר במכתביו.</p>\n<p>והנה בודאי יודע - שבכלל אין זה מעניני לתקוע עצמי לפסקי הלכות למעשה, ובפרט בענין שרבים הדנים בזה, וממצים הענין לכל צדדיו.</p>\n<p>והרי זוהי הדרך אשר התוה כ\"ק מו\"ח אדמו\"ר בבית הרב - מלבד במקרים יוצאים מן הכלל, שישנם טעמים מסוימים וסיבות חשובות, להכנס לשקו\"ט כהאמורות.</p>\n<p>ובפרט אשר רבים בניו יארק ובאה\"ב בכלל, אשר ישמחו אלי גיל כשיציעו לפניהם לחוו\"ד בהאמור (כמובן כוונתי לרבנים אשר ראוים הם לאיצטלא דמורה הוראה, לפסוק דין מבלי משוא פנים ולמעשה בפועל), ובטח גם יחזיקו לו טובה על הדפיסו את דבריהם וכו'.</p>\n<p>ואתו הסליחה. נוסף על טעם העיקרי הנ\"ל, הרי גם אין הפנאי ואין הזמן גרמא למלאות בקשה כהאמורה.</p>\n<p>בכבוד ובברכה,</p>\n<p><b>מנחם שניאורסאהן</b></p><p>להעיר ממחז\"ל <b>בשעת</b> המפזרים כנס (ברכות סג, א) - וה\"ז הטעם גם <b>בענין</b> שבו מפזרים.</p>\n<p>במש\"כ הרה\"ג וכו' וכו' הררי\"מ הכהן שי' ר. בענין ביה\"ש - תמהתי על תוכנו. ובפרט בידעי את הנ\"ל מאז, שאין מובן איך כותב דברים כאלו (אלא - שקונ' השלמה, הס' זכרון יוסף, בני ציון, דברי חנה, קנה וקנמון אינם תח\"י). ואולי בא לו משום רצונו להגן עמש\"כ בסו\"ס חי' הרמ\"ל וסייעתי' - ואשתמיטתי' מש\"כ בזה בנימוקי או\"ח סרס\"א. וד\"ל.</p>\n<p>ובנוגע למש\"כ הנ\"ל ע\"ד אדה\"ז בסידורו בזה - לא סמך שם אדה\"ז ואף לא הביא שם - לא הירוש' ולא הרדב\"ז, ומה שהקשה - דאאפ\"ל דר\"ת יחידאה הוא כיון שכתב החיד\"א בשה\"ג דפסקו של השו\"ע הוא פסק ר' גדולים בדורו (ואם נפרש כן - להלכה - דברי החיד\"א - עדיפא הו\"ל להקשות ולהפריך כל דברי הרמ\"א בכ\"מ שמחולק על השו\"ע, כי מעולם לא שמענו שבב\"ד של הרמ\"א ישבו מאתים ואחד גדולים.</p>\n<p>ובכל אופן) אי\"ז שייך לדברי אדה\"ז שדייק בלשונו ר\"ת וסייעתו יחידאי נינהו <b>נגד</b> הגאונים. ואחריהם וכו'. נוסף על כתבו שהשו\"ע חזר בו. ולהביאו הפר\"ח החיד\"א וערוך השלחן - הנה בנדו\"ד <b>כולם</b> כתבו כשיטת הגאונים (הפר\"ח - הובא בסידור שם. ברכ\"י ועה\"ש - באו\"ח סרס\"א שם).</p>\n<p>ביאור השיטות הנ\"ל - עייג\"כ ס' מנחת כהן, ס' ביה\"ש (להרי\"מ טוקצינסקי). וערך ביה\"ש באנציקלופדי' התלמודית.</p>\n<h4><i><b>ח'תתקלט</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חי\"א ע' 247 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>הר\"מ שי':</b> אמסל, ברוקלין. אגרות נוספות אליו - לעיל חי\"ח ו'תתקה. חי\"ב ג'תתכא.</p>\n<p><b>הררי\"מ... ר.:</b> רפפורט.</p>"],[1200970267,"ח'תתקמ\n\n<p>ב\"ה, טו\"ב בשבט, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>צו אלע אנטיילנעמער אין דער יערלעכער<br>\nחגיגה פון מרכז<br>\nהישיבות תומכי-תמימים ליובאוויטש<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>די תורה הקדושה, וואס איז א נצחיות'דיגע, אנטהאלט אנווייזונגען אין צוזאמענהאנג מיט אלע געשעענישן, אין אלע צייטן; ספעציעל א געשעעניש וואס איז דירעקט פארבונדן מיט תורה, ווי די יערלעכע פייערונג פון דער צענטראלער ישיבה \"תומכי תמימים\" ליובאוויטש.</p>\n<p>די פייערונג קומט היי-יאר פאר אין דעם טאג ווען מען הויבט אן צו לייענען די פרשה <b>משפטים</b> (\"געזעצן\"), וועלכע הויבט זיך אן מיט די געזעצן פון <b>בין אדם לחברו,</b> צווישן מענטש און מענטש. אבער די פרשה משפטים קומט באלד נאך פרשת <b>יתרו,</b> די סדרה פון <b>מתן תורה,</b> מיט די <b>עשרת הדברות,</b> וועלכע הויבן זיך אן מיט <b>אנכי ה'</b> <b>אלקיך;</b> און די סדרה ענדיגט זיך מיט אן ענין פון מזבח, וואס האט צו טאן מיט <b>בין</b> <b>אדם למקום</b> - אין די ראמען פון פליכטן פון מענטש צו ג-ט. און ווי אונזערע חכמים זכרונם לברכה באמערקן אויף דעם: \"דערפאר קומט די פרשה פון <b>דינים</b> באלד נאך דער פרשה פון <b>מזבח,</b> כדי צו ווייזן, אז די סנהדרין דארפן זיין נאענט צום מקדש (מזבח)\".</p>\n<p>אין דאס אויבנדערמאנטע ווערט אונטערשטראכן, אין פארשידענע און טיפזיניגע אופנים, דער גרונט-געדאנק, אז -</p>\n<p>ווען עס קומט צו דער פראגע פון איינשטעלן גוטע און יושר'דיגע באציאונגען צווישן מענטש און מענטש און צווישן פאלק און פאלק, איז ווייט ניט גענוג צו פארלאזן זיך אויף \"איינגעבארענע\" געפילן פון יושר און גערעכטיקייט; ווי די ביטערע דערפארונג האט דאס ליידער אפט באשטעטיגט.</p>\n<p>בלויז דאן קען עטיק און יושר האבן א קיום אין טאג-טעגלעכן צוזאמענלעבן פון מענטשן און פעלקער - אויב די עטישע און מאראלישע געזעצן שטיצן זיך אויף <b>איבער</b> - מענטשלעכע יסודות, ד.ה. אויף דעם יסוד פון <b>קדושה</b> וואס איז פארבונדן מיט דעם באשעפער פון דער וועלט, וועלכער איז אויך דער באשעפער פונם מענטשן.</p>\n<p>ווייל בלויז דער באשעפער אליין ווייס גרינטלעך די מענטשלעכע נאטור, מיט אלע אירע שוואכקייטן; דעריבער האט בלויז דער באשעפער געקענט שאפן די אמת'ע און דויערהאפטע עטישע און מאראלישע געזעצן פאר דער מענטשהייט, פאר דעם יחיד ווי פאר דעם כלל; און די דאזיגע ג-טלעכע געזעצן זיינען פארפליכטענד אויף אלעמען אן אויסנאם, אומעטום און אין אלע צייטן.</p>\n<p>אין ליכט פון דאס אויבנגעזאגטע, קען מען בעסער אפשאצן די</p>\n<p>לעבנסנויטווענדיקייט פון ישיבות בכלל, און ליובאוויטשער ישיבות בפרט.</p>\n<p>פארביי איז די צייט, ווען מען האט געמיינט, אז צו פארטיפן זיך אין גמרא, מוסר און חסידות איז א נויטווענדיקייט פאר א רב, א שוחט, אד\"ג, אבער דער דורכשניטלעכער איד, דער \"בעל-הבית\", דארף דאס ניט האבן. אין דער איצטיגער צייט, און איצטיגער סביבה, איז געווארן גאנץ קלאר, אז צו פארטיפן זיך אין תורה און אנזאפן זיך מיט דער יראת-שמים-אטמאספערע פון דער ישיבה איז א לעבנסנויטווענדיקייט פאר <b>יעדן</b> אידן, אויב מען וויל זיין א <b>גאנצער</b> איד, גאנץ אין <b>בין אדם למקום</b> און <b>אין בין</b> <b>אדם לחברו,</b> און קענען דערפילן אין דער פולסטער מאס די נשמה-שליחות וואס די השגחה עליונה האט אויף יעדן איינעם ארויפגעלעגט.</p>\n<p>און אין דער צייכנען זיך טאקע אויס די ליובאוויטשער ישיבות, וואו די תלמידים \"תמימים\" ווערן דערצויגן צו א <b>גאנצקייט</b> אין ביידע דערמאנטע ריכטונגען, בא וועמען אהבת-השם און אהבת-התורה גייט צוזאמען מיט אהבת-ישראל און קומען צום פולסטן אויסדרוק אין טאג-טעגלעכן לעבן.</p>\n<p>איך שיק מיין ברכה און באגריסונג צו אלע חשובע געסט און אנטיילנעמער אין דער יערלעכער פייערונג פון מרכז הישיבות \"תומכי-תמימים\" ליובאוויטש, און האף אז יעדער איינער און איינע וועלן ביישטייערן זייער פולן חלק צום דערפאלג פון דער אונטערנעמונג, סיי אין מאטעריעלן און סיי אין גייסטיגען זין.</p>\n<p>בכבוד ובברכה להצלחה רבה בכל האמור.</p>\n<h4><i><b>ח'תתקמ</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ו ע' 314 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>חכמים... באמערקן:</b> ראה גם לקמן אגרת ח'תתקמב, ובהנסמן בהערות שם.</p>\n<p><b>דער גרונט געדאנק:</b> ראה גם לעיל חכ\"ב אגרת ח'שלח, ובהנסמן בהערות שם. לקמן ח'תתקמב. ח'תתקסט. ובכ\"מ.</p>"],[1200970268,"ח'תתקמא\n\n<p>ב\"ה, י\"ח שבט, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לכבוד הרב יהודא שי' סמט</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו, בו כותב ראשי פר[ק]ים מעבודתו בתור רב צבאי, ושואל הוראות איך יצליח בשליחותו,</p>\n<p>הנה על יסוד פעולות צעירי אגודת חב\"ד, שהי' להם נסיון משך כמה שנים, בביקורים במחנות צבא ובפגישות עם סטודנטים וכדומה, יש להציע הנקודות דלהלן:</p>\n<p>א. בשים לב לקוצר הזמן, כמו שכת\"ר שי' כותב, שנשארו לו רק מספר חדשים במקום - מחד, ואשר רוב אנשי הצבא היהודים אשר באים לשם נשארים רק ששה שבועות - מאידך, קשה לתכנן תכנית של עבודה ההולכת ומתקדמת מדרגה לדרגה וכו'.</p>\n<p>ולכן, קודם כל, צריך להשתדל לעורר התעוררות כללית בדברים היוצאים מן הלב ונכנסים אל הלב, באופן שכל אחד ואחד ישאל את עצמו מהו תפקידו בתור יהודי, ומה עליו לעשות למלא תפקידו, ועד כמה ממלא הוא את חובתו בזה. והעיקר לעורר בו תשוקה למלא תפקידו, שאם יהי' בו הרצון ויכיר את מעלתו וגאונו להיות יהודי, במילא ישתדל בעצמו להרחיב ידיעותיו גם לאחרי שיצא מתחת השפעת כת\"ר, והרי השפעת כת\"ר תהי' מנקרת בו גם אח\"כ.</p>\n<p>ב. כדי שההשפעה לא תשאר בעולם הדיבור בעלמא, צריך להגיע לידי דבר ממשי בפועל, היינו מצוה מעשית בכל יום; שמלבד תועלת של כל דבר בפועל כמו שהוא לעצמו, הרי עוד זאת שמצוה גוררת מצוה. ויתר על כן, שהפועל-ממש שיגיע אליו המושפע יזכירו בתמידות אותם דברים המלבבים שהביאוהו לידי הפועל ממש. כגון הנחת תפילין בכל יום חול, ולכל הפחות לרגעים אחדים, קריאת שמע, הפרשת פרוטה לצדקה בכל בוקר חול, וכדומה.</p>\n<p>ג. בנוגע אלה בעלי משפחה (רופאים וכו') הבאים לשם לשנה ויותר, כמובן שצריך לסדר תכנית מסודרת בקביעת עתים לתורה, ובשמירת המצוות, כגון כשרות, תפילין לגברים, טהרת המשפחה וכולי; ובפרט חינוך הילדים.</p>\n<p>ד. צריך לשים לב לזה שלפעמים יש בין אנשי הצבא בחורים הבאים מחוגים שומרי מצוות, אלא חושבים שבצבא פטורים הם מעול מצוות, משום קושי וכו'. והרי ידוע שאדרבה, יש אפשרות בצבא לקיים המצוות; ועוד זאת שצריך להשפיע על אלה שיכירו באחריות והזכות שיש להם להשפיע על זולתם, ומי יודע אם אין זה תפקידם העקרי שנתגלגלו למחנה פלוני בין חברים חדשים, וכו'.</p>\n<p>כיון שכת\"ר כותב שנשארו לו שם רק חדשים מספר, בודאי יוסיף אומץ בהשפעתו, באופן שכשיבוא ממלא מקומו יוכל לא רק למסור לו תכנית עבודה בפועל להמשיך בה, אלא גם להצביע על הצלחה ופירות מהשפעתו.</p>\n<p>באם נצרך לסיוע נוסף, או עניני דפוס, וכיו\"ב, יוכל לפנות ישר לצעירי אגודת חב\"ד, ואולי יוכלו לסדר ביקור מאחד מחבריהם במחנה שלו אם יהי' בזה תועלת מיוחדת.</p>\n<p>בברכה להצלחה ולבשורות טובות,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ח'תתקמא</b></i></h4>\n<p><b>שמצוה גוררת מצוה:</b> אבות פ\"ד מ\"ב.</p>"],[1200970269,"ח'תתקמא*\n\n<p><i>[י\"ח שבט תשכ\"ה]</i></p>\n<p>להרשות בינגא - מובן שא\"א (ואפי' הקונסרבטיב שללו ואסרו זה).</p>\n<h4><i><b>ח'תתקמא*</b></i></h4>\n<p>מענה למו\"ה שמואל פסח שי' בוגומילסקי על גליון מכתבו מי\"ח שבט תשכ\"ה. על שאלתו אם להרשות משחק בינגאו בביהכ\"נ. אגרות נוספות אליו - לעיל ח'תשצה, ובהנסמן בהערות שם.</p>"],[1200970270,"ח'תתקמב\n\n<p>ב\"ה, יום ראשון פרשת משפטים, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>ברוקלין</p><p>חברה גמילות חסדים שומרי שבת בעיר<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בנועם קבלתי הידיעה, ע\"ד האסיפה השנתית שלהם לטובת קרן הגמ\"ח, ויהי רצון שתהי' בהצלחה בכל הפרטים.</p>\n<p>ידוע אשר בתורתנו הק' גם הסדר - תורה והוראה היא, ונסמכה פרשת דינין (משפטים) לפרשת מזבח, לומר לך שתשים סנהדרין אצל המקדש.</p>\n<p>ללמדנו, אשר אפילו ענינים שבין אדם לחבירו, שהם רובם ככולם דדיני פרשת משפטים, צ\"ל בסמיכות ומיוסדים על המקדש והקדושה,</p>\n<p>- וכמובן ג\"כ מהקישור דעשרת הדברות, אשר התחלתם, אנכי ה' אלקיך וסיומם - לא תחמוד. -</p>\n<p>אשר רק אז ההנהגה בין אדם לחבירו בשלימות היא.</p>\n<p>וכן גם להיפך: דעלך סני לחברך לא תעביד - זו היא כל התורה כולה ואידך פירושא הוא זיל גמור.</p>\n<p>ויהי רצון אשר גם עניני גמ\"ח שלהם, ניכר יהי' אשר מיוסדים הם על אנכי ה\"א אלקיך (ל' יחיד) של כל אחד ואחת מישראל, אשר מצד זה - כולן מתאימות ואב אחד לכולנה, ואהבה ואחוה אמיתית ביניהם, אשר כל זה מביא לשלימות והידור בגמ\"ח ובהפיוס שצ\"ל עמו יחדיו.</p>\n<p>ושכר כל העוסקים בגמ\"ח, הרי מבואר הוא ומפורש בכ\"מ בתורתנו תורת חסד, הנתונה מא-ל רחום וחנון אשר צוונו ללכת בדרכיו והצדקה דייקא היא מצות ה' ממש מה שהקב\"ה בכבודו ובעצמו עושה תמיד.</p>\n<p>בברכת הצלחה בעבודתם בקדש,</p>\n<p><b>מ. שניאורסאהן</b></p><p>מצו\"פ השתתפותי, בל\"נ, בקרן הגמ\"ח.</p>\n<h4><i><b>ח'תתקמב</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ו ע' 339 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>ידוע:</b> ראה גם לקמן אגרת ט'כז, ובהנסמן בהערות שם.</p>\n<p><b>דעלך: </b>שבת לא, א (כל\"א בפירש\"י שם ד\"ה דעלך). תניא פ' לב.</p>\n<p><b>כולן... ביניהם: </b>תניא שם.</p>\n<p><b>בגמ\"ח ובהפיוס: </b>בסבר פנים יפות ובשמחה (רמב\"ם הל' מתנות ענים פ\"י ה\"ד) ובטוב לבב (הוספת טושו\"ע יו\"ד סרמ\"ט, ס\"ג).</p>\n<p><b>הצדקה... תמיד: </b>אגה\"ק סי' טו\"ב.</p>"],[1200970271,"ח'תתקמג\n\n<p>ב\"ה, כ\"א שבט תשכ\"ה</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>לאחרי הפסק הכי ארוך, נתקבל מכתבו מעש\"ק עם הפ\"נ, שיקרא בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>ולשאלתו אודות משרה בישיבה תיכונית, - בודאי ידועים לו החילוקי דיעות שמסביב לענין זה, חילוקי דיעות מן הקצה אל הקצה, ומובן שאין לו לסייע לצד וכו', והרי כו\"כ מאברכים יראי ה' מסתדרים באה\"ק ת\"ו באהלה של תורה, מבלי לעשות כהנ\"ל, וק\"ל.</p>\n<p>מובנת הפליאה והתמי' על הקור רוח בסגנון מכתבו שאינו עוסק באופן מיוחד בהפצת המעינות, אף כי בטח (כיון שמשתמש בביטוי האמור) יודע המדובר בזה באגה\"ק של הבעש\"ט, ובפרט ע\"פ פס\"ד ערוך בש\"ס וברמב\"ם, אשר <b>לעולם</b> יראה עצמו שקול וכל העולם כולו שקול כו'.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>ש.מ. סימפסאן</p>\n<p>מזכיר</p>\n<h4><i><b>ח'תתקמג</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חכ\"ד ע' 352 וחלקה בחכ\"ג ע' 515 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>בש\"ס:</b> קידושין מ, ב.</p>\n<p><b>וברמב\"ם:</b> הל' תשובה פ\"ג ה\"ד.</p>"],[1200970272,"ח'תתקמד\n\n<p>ב\"ה, כ\"ב שבט תשכ\"ה</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>מכתבו מיום ח' שבט נתקבל.</p>\n<p>ולכתבו אודות ענין הידוע - יסיח דעת מזה לגמרי (עיין שו\"ת הצ\"צ שער המילואים ח\"ב) וירבה באותיות התורה והתפלה, כן ילמוד בע\"פ פרקים (אחדים לפחות) מש\"ס משנה ומס' התניא. וירבה בנתינותיו לצדקה גם כי הסך הכולל אחד הוא כמ\"ש הרמב\"ם ז\"ל בפיה\"מ. ראה אגה\"ק לרבנו הזקן סכ\"א.</p>\n<p>בברכה.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<h4><i><b>ח'תתקמד</b></i></h4>\n<p><b>ענין הידוע:</b> ראה גם לעיל אגרת ח'תרפו.</p>\n<p><b>שו\"ת הצ\"צ... ח\"ב:</b> בהוצאת תשנ\"ד - או\"ח ח\"ב סי' קח. אג\"ק אדמו\"ר הצ\"צ ח\"א אגרת כו.</p>\n<p><b>בפיה\"מ:</b> אבות פ\"ג מט\"ו.</p>"],[1200970273,"ח'תתקמה\n\n<p>ב\"ה, כ\"ג שבט תשכ\"ה</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו ממוצש\"ק.</p>\n<p>בעת רצון יזכירו כל שכותב אודותם על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע מתאים לתוכן כתבו.</p>\n<p>ולכתבו אודות ציווי הרופאים על זוגתו תחי' להמנע מהריון, ושאל דעת רב בזה, והתיר לו אמצעים שונים בזה, שמונה אותם במכתבו.</p>\n<p>ולפלא שאין מזכיר ענין פשוט וביחד עם זה יעיל, ובפרט בצירוף עם האמצעים שכותבם, והוא אשר בנדון <b>(דידי') שהרב מפורש התיר</b> וכו' לדחות הטבילה לימים אחדים כפי שיורה אותו הרופא המכיר זוגתו תחי' ויודע ג\"כ היום שעלולה ביותר להכנס להריון וע\"פ רוב מספיק איחור של ב' ג' ימים וכו' וידבר בכל האמור עם הרב והרופא, ויורוהו.</p>\n<p>ע\"פ סגנון מכתבו, תקותי שלמותר להדגיש על הכרח הנהגה בחיי היום יומים שתהא מתאימה להוראות תורתנו תורת חיים ובקיום מצותי' עליהם נאמר וחי בהם, שנוסף על העיקר שכן הוא ציווי השם הרי זה גם הדרך לקבלת ברכת השם בכל המצטרך, ובפרט כשזקוקים לברכה מיוחדת. - במקרה שלהם ההדגשה בפרט על הזהירות כדבעי בכל דיני טהרת המשפחה.</p>\n<p>ומהנכון אשר יבדקו את התפילין שלו, וכן את המזוזות בדירתם שתהיינה כולן כשרות כדין, וזוגתו תחי' תשמור על מנהגן הטוב של בנות ישראל הכשרות להפריש צדקה קודם הדלקת הנרות בכל ערב שבת וערב יום טוב.</p>\n<p>תפירת השיחלות - נוסף על החששות שישנם בכל ניתוח ובפרט ניתוח הפנימי ובמיוחד - במצב בריאות רופף (ובכמה פרטים גם לא ברור כנראה ממכתבו) - יש בזה כמה צדדים שליליים: א) זוהי פעולה לשלול ההריון לתמיד, אפילו לכשתבריא וכו'. ב) חששות מצד הדין, כפי שיבארו הרב שלו. ג) היו מקרים שלמרות התפירה נכנסה לאח\"ז להריון (ביאור הרגיל ע\"ז, כי כנראה שהתפירה התפרקה מאלי', ולהיותה בפנים א\"א לדעת עד\"ז).</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א,</p>\n<p>מזכיר</p>\n<h4><i><b>ח'תתקמה</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ב ע' 229 והושלמה עפ\"י העתק המזכירות.</p>"],[1200970274,"ח'תתקמו\n\n<p>ב\"ה, כ\"ד שבט תשכ\"ה</p><p>ברוקלין.</p>\n<p>ברכה ושלום!</p>\n<p>במענה למכתבה מד' שבט, בו שואלת פרטים בנוגע להזמן שלאחרי החתונה בשעה טובה ומוצלחת.</p>\n<p>ומובן אשר בכגון זה עלי' לדבר לכל לראש עם ב\"ג שי', ובפרט שכמדומה כבר כתב באחת הבעיות שמזכירה במכתבה.</p>\n<p>לכתבה אודות המשך ההתעסקות שלה בשטח החינוך גם לאחרי החתונה,</p>\n<p>מובן שבכלל נכון הדבר וטוב במאד. ובפרט אשר בתקופתנו ובאה\"ק ת\"ו - חינוך בני ישראל על טהרת הקדש, ענין חיוני הוא, וק\"ל.</p>\n<p>וע\"פ סגנון מכתבה, התקוה אשר בענין זה גם עתה עובדת במסירה ונתינה המתאימות, והבטיחונו חז\"ל בכגון זה הבא לטהר - וידוע דיוק רבנו הזקן לטהר גם אחרים - מסייעין אותו.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א,</p>\n<p>ש.מ. סימפסון</p>\n<p>מזכיר</p>\n<h4><i><b>ח'תתקמו</b></i></h4>\n<p>נדפסה ב\"היכל מנחם\" ח\"א ע' קכ.</p>\n<p><b>והבטיחונו... דיוק:</b> יומא לח, ב. לקו\"ת דרושים לשמע\"צ פח, ב.</p>"],[1200970275,"ח'תתקמז\n\n<p>ב\"ה, כ\"ה שבט ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>מר ל. ארמן שי'</p>\n<p>שלום וברכה!</p>\n<p>הנני מאשר קבלת מכתבו, וכן הספרים ששלח, כרשום למטה. ותודה רבה עבור שימת לבבו, ובודאי גם מה שיוציא לאור בעתיד ישלח לספרי' שלנו, ות\"ח מראש.</p>\n<p>אף שלא כותב פרטים על עצמו, אבל כמו שרואים מספריו האמורים בדפדפי בהם, מתבונן הוא בהנעשה סביב לו וכולי. ותקותי שמקדיש חלק חשוב מזמנו ללימוד תורתנו, שהיא מאחדת ב' הקצוות, כפשוטו - בחיי האדם מרגע ראשון להולדתו ועד רגעו האחרון עלי אדמות, וכן בחיים הרוחניים שלו, וכמו שמודגש הדבר בעשרת הדברות, המתחילים ב\"אנוכי\" - כולל ענינים הכי עמוקים ביחוד השם (מונוטיאיזם בלע\"ז), כמבואר בארוכה בספרי חסידות, ועד \"לא תרצח\" \"ולא תגנוב\" וכולי - האינסטינקטים הכי שפלים שבאדם.</p>\n<p>וכיון שדרשו רבותינו ז\"ל לימוד המביא לידי מעשה דוקא, תקותי שלימודו הוא ג\"כ באופן זה, כי תורתנו תורת חיים היא, לראש ולראשונה, הוראה בחיי היום-יום, לחיים הראויים לשמם. ואם תמיד כך, על אחת כמה וכמה בתקופתנו רבת המבוכות, ובפרט בארצנו הקדושה תבנה ותכונן, אשר ארץ הקדש ייקרא לה בפי כל עמי תבל, ובלשון הכתוב - ארץ אשר עיני ה' אלקיך בה מראשית השנה ועד אחרית שנה.</p>\n<p>במשנה תודה על משלוח האמור ובכבוד וברכה.</p>\n<p>במזכירות שלי אין כותבים גרמנית, אבל כ' יכול לכתוב לי גם בשפה זו אם נוח לו יותר.</p>\n<p>ארשה לעצמי לבקש את משרדי לשלוח לו ספרים אחדים שיצאו לאור על ידי הוצאת ספרים שלנו, שתקותי שכ' ימצא בהם ענין ויעיין בהם בשימת לב המתאימה.</p>\n<h4><i><b>ח'תתקמז</b></i></h4>\n<p><b>שדרשו חכמינו:</b> קידושין מ, ב.</p>"],[1200970276,"ח'תתקמח\n\n<p>ב\"ה, ח' אדר א' תשכ\"ה</p><p>ברוקלין.</p><p>הנהלת אגודת נשי חב\"ד אשר בעיר ניו<br>\nהייווען<br>\nה' עליהן תחיינה</p>\n<p>ברכה ושלום!</p>\n<p>מיט צופרידענהייט האב איך באקומען די ידיעה וועגען די ארבעט פון אייער גרופע, און די לעצטענס פארגעקומענע אסיפה, און דע[ם] ווארימען אפרוף פון די פארזאמעלטע, ווי געשריבען אין דעם בריף פון מרת שרה תחי' דייטש.</p>\n<p>השם יתברך זאל העלפען, אז דער אנהויב זאל זיין אין א גוטער שעה און גוטען אופן,</p>\n<p>און די פעולות וועגען וועלכע איר שרייבט און די איינטיילנעמער אין דעם, זאל זיין, ווי געשריבען אין דער סדרה פון היינטיקער וואך, להעלות נר תמיד.</p>\n<p>צו זעהן טאן אין דער ריכטונג, אז די אידישער ליכט, וואס דאס איז די נשמה פון א אידן, ווי עס שטייט, נר ה' נשמת אדם, זאל לייכטען בא יעדער אידן, תמיד (שטענדיג) און באלייכטען זיין הויז און אומגעגענד בגשמיות וברוחניות.</p>\n<p>וואס דענסטמאל וועט מען זיכער צו-ציהען אלץ מער און מער אידישע פרויען אין דעם אויבען געזאגטען גייסט, ווי ס'איז די פאדערונגען און האפנונגען פון רבותינו נשיאינו זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>בברכה צו גוטע בשורות און גאר אין גיכען.</p>"],[1200970277,"ח'תתקמט\n\n<p>ב\"ה, ח' אדר ראשון, תשכ\"ה</p><p>ברוקלין.</p><p>הנהלת ישיבת תומכי תמימים לוד<br>\nהנהלת ישיבת אחי תמימים ראשון לציון<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבם מראש חדש אדר ראשון, בו כותבים ע\"ד הצעת הרה\"ח אי\"א נו\"נ רב פעלים ובעל מדות הרח\"ש שליט\"א, למזג ישיבת אחי תמימים דראשון לציון עם ישיבת תומכי תמימים דלוד וכפר חב\"ד.</p>\n<p>ובודאי הכוונה בהאמור, שעי\"ז יתוסף בביסוס ישיבות אלו, וגם בהתפשטותם,</p>\n<p>ויהי רצון שיהי' המיזוג בהצלחה בכלל, ובהצלחת מטרה האמורה במיוחד,</p>\n<p>שהרי היא היא פקודת ותקות ורצון רבותינו נשיאינו, להרחיב אהלי התמימים ומשכנותם, באופן דמוסיף והולך בגשמיות וברוחניות גם יחד, מוסיף והולך ואור.</p>\n<p>וגדול זכות הענין והתעוררות ר\"ר של רבותינו נשיאינו, להוסיף בהצלחת כל האמור, נוסף על הברכה וההצלחה דכל אלו שישתתפו בזה בהווה ובעתיד, וכל אלו שעשו בביסוס מוסדות אלו בעבר ועד עתה.</p>\n<p>וכמובן ופשוט - להמשכת ברכת רפואה להרה\"ח וכו' וכו' הר\"ר חיים שאול שליט\"א, שבודאי כשיתחזק בבריאותו יתחזק בפעולות לביסוס מוסדות האמורים ועוד בתוספת מרץ, מתוך שמחה וטוב לבב, אשר כמובן גם חיזוק זה עיקר במיזוג האמור.</p>\n<p>והרי כ\"ז כהוראת פרשת שבוע זה:</p>\n<p>ואתה (בתוספת וא\"ו, המשכה מלמעלה מהשתלשלות) תצוה (מלשון צוותא</p>\n<p>והתקשרות) את בני ישראל (לי ראש, היא בחי' חכמה (שבתורה הוא ענין פנימיות התורה)) ויקחו אליך (לבחי' משה שבכ\"א) שמן זית (הבא ע\"י כתישתו, אתכפיא וכו') זך (ראשון שבשמנים, כמ\"ש כל <b>חלב</b> לה', וע\"י) כתית (ביטול - מגיעים) למאור (של תורה, ועי\"ז מתקשרים בקוב\"ה בבחי' הנקראת מאור, ומזה נמשך להיות, ד)יערוך אותו אהרן (שמחה של מצוה, ובאופן ד)חקת עולם (דבר של קיימא ונצחי) כמבואר בדא\"ח.</p>\n<p>המצפה - ובברכה - לבשו\"ט בכל האמור,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתקמט</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חכ\"ו ע' 436 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>הרח\"ש:</b> ברוק.</p>\n<p><b>למזג ישיבת:</b> ראה גם לקמן אגרת ח'תתקסח. ח'תתקעז.</p>\n<p><b>כמבואר בדא\"ח:</b> ראה תורה אור עה\"פ.</p>"],[1200970278,"ח'תתקנ\n\n<p>ב\"ה, ט\"ז אדר א', ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצרכי צבור מוכתר<br>\nבנימוסין וכו'<br>\nמו\"ה נסים נ\"י ב[כ]ר</p>\n<p>שלום וברכה!</p>\n<p>בעתו נתקבל מכתבו, ולאחרי זה גם פ\"ש מפורטת על ידי הרה\"ג והרה\"ח וו\"ח אי\"א נו\"נ עוסק בצ\"צ בעל מרץ ורב פעלים וכו' הרב רב\"א שי' גורודצקי, שמסר לי על דבר פעולותיו הכי כבירות של מר להחזקת היהדות במחנו הט'.</p>\n<p>ויהי רצון אשר פעולותיו אלו לטובת בני ובנות ישראל תעמודנה לו אשר ביחד עם זוגתו שתחי' ישבעו נחת אמתי מכל יוצאי חלציהם שיחיו.</p>\n<p>ובפרט אשר בודאי אינו מסתפק בהשגים דעד עתה ויוסיף כהנה וכהנה. והובטחנו הבא לטהר (וידוע דיוק רבנו הזקן - ליטהר עצמו ולטהר אחרים) מסייעין אותו.</p>\n<p>מלאתי ידי הרב גורודצקי שליט\"א לבוא עם כבודו בכתובים בפרטיות באותן הבעיות והענינים שדברו פנים אל פנים. ואני תפלה שתשרה שכינה במעשה ידי כלנו יחד להגדיל תורה ולהאדירה, בהתמסרות הראוי' ובהתלהבות ואור חסידותיים, עבודה מתוך שמחה וטוב לבב.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתקנ</b></i></h4>\n<p><b>מו\"ה נסים בכר:</b> אגרת נוספת אליו - לעיל חכ\"ב ח'תרעג.</p>\n<p><b>במחנו:</b> איסטמבול.</p>\n<p><b>והובטחנו... דיוק:</b> יומא לח, ב. לקו\"ת דרושים לשמע\"צ פח, ב.</p>"],[1200970279,"ח'תתקנא\n\n<p>ב\"ה, י\"ז אד\"ר תשכ\"ה</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>בתמהון גדול קראתי מכתבו מעש\"ק תצוה, בו כותב אודות נכדו הנעלה האברך ירא שמים ות\"ח... אשר מתבטא שאין לו נחת ממנו (ח\"ו) כבריאות גופו וכו'.</p>\n<p>ותיכף שאלתי וחקרתי להנעשה את נכדו שי' ומסרו לי עוד הפעם ע\"ד הצלחתו בלימוד התורה, לימוד המביא לידי מעשה, כמובן וגם פשוט, ובהנוגע לבריאותו, אשר - הרופא מצא שהכל אתו בסדר, אלא שכנראה טבע נפשו, שתובע מעצמו תמיד בנוגע למצבו ברוחניות ובמילא פועל על הבריאות וכו', מובן וגם פשוט אשר נסיעה וטלטול ממקום למקום, לא ישנה בזה מאומה, והלואי שלא יזיק, שהרי הורנו חז\"ל, לעולם ילמוד אדם במקום שלבו חפץ, ומי יודע איך יסתגל במקום החדש.</p>\n<p>ולהמשך מכתבו אשר במקום חדש ילמוד ג\"כ איזה אומנות, כי טוב תורה עם דרך ארץ, הרי במכתבו זה עצמו, הקדים תורה לדרך ארץ, ובודאי ובודאי שעדיין לא הגיע זמן נכדו שי' לגזול מהשעות אשר מקדיש הוא להתמדה ושקידה בלימוד תורתנו תורת חיים, חיים גם כפשוטם בעולם הזה הגשמי, ולהתבלבל בחשבונות רבים מחשבות בני אדם ותחבולותיהם היפך מזה שהאלקים עשה את האדם ישר.</p>\n<p>יודע הנני אשר אויר מדינה זו גורם למחשבות בנוגע לתכלית, בגיל הרך של הבנים והבנות, אבל כל המביט בעינים גלויות על הנעשה סביבו, רואה על כל צער ושעל, שברובא מסתדרים בפרנסה דוקא לא בזו האומנות שלמד בעודו רך.</p>\n<p>שולח הנני העתק מכתבי גם לבנו הרב שי' כיון שאיני יודע ממי באו סברות הכתובות במכתב כ' (אף שלכאורה הרי הן בהיפך מפעולות בנו הרב שי' לילך נגד הזרם דארצוה\"ב, פעולות במרץ ומבלי התחשב עם דעת הרבים וכו' וכו').</p>\n<p>ויהי רצון אשר נוסף על הנחת רוח שיש לו עתה מנכדו שי' והלואי ועוד יותר מכל יו\"ח שי' נחת אמיתי, יוסיף השם כהנה וכהנה ע\"י הצלחה מופלגה של נכדו בלימוד התורה בנגלה ובחסידות, מבלי הפרעות ענינים מבחוץ, ובודאי כשיוכל ללמוד במנוחה, יקוים בו אשריך בעוה\"ז וטוב לך וכו'.</p>\n<p>בכבוד בברכה לבשו\"ט.</p>\n<p>נ.ב. וכיון שהכל בהשגחה פרטית, עלי החובה (והזכות) לעוררו על ההכרח לקבוע עתים בלימוד פנימיות התורה, שבדורנו נתגלתה בתורת החסידות, קביעות בכל יום ובהוספה ביום השבת, כמבואר בכתבי האריז\"ל החי.</p>\n<h4><i><b>ח'תתקנא</b></i></h4>\n<p><b>לימוד המביא:</b> קידושין מ, ב.</p>\n<p><b>הורונו חז\"ל:</b> ע\"ז יט, א.</p>\n<p><b>טוב תורה:</b> אבות פ\"ב מ\"ב.</p>\n<p><b>יקויים בו:</b> אבות פ\"ו מ\"ד.</p>"],[1200970280,"ח'תתקנב\n\n<p>ב\"ה, ועש\"ק פ' כי תשא ה'תשכ\"ה ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>ומענין פרשת שבוע זה:</p>\n<p><b>וידבר ה' אל משה</b> - כי שאל משה: רבש\"ע במה תרום קרן ישראל (ובפרט - שהי' אך זה עתה מעשה העגל). אמר לו הק'</p>\n<p><b>לאמר</b> - לדורות (כולל אפילו ביום פקדי (אשר אז) ופקדתי עליהם חטאתם בעגל) -</p>\n<p><b>כי תשא</b> - אתה דוקא - ראשם של ישראל (ורק משה - לא הייתה לו כל <b>שייכות</b> אפילו לענין העגל, שהרי הי' אז בהר <b>עם ה'</b>(</p>\n<p><b>תשא את ראש</b> - תוכל \"לשאת את ראשם בהגבהה\", ע\"י אשר -</p>\n<p>תשא את ראש, תמנה אותם לגלות חיבתם לפני המקום. - ולכפר על החטא המונע הרמת קרנם (ובפרט - חטא העגל) -</p>\n<p><b>ונתנו איש כופר נפשו</b> - צדקה, כמש\"נ וחטאך בצדקה פרוק.</p>\n<p>* * *</p>\n<p>וכיוון אשר כל נפש ונפש מבית ישראל יש בה מבחי' משרע\"ה - הרי הוראה בפרשתנו, שע\"י בחי' זו על כאו\"א להרים קרנו, ע\"י אשר יגלה חבתו לפני המקום, בהתבוננו אשר אהבת עולם אהבתנו ה' אלקינו כו' ובנו בחרת - הוא הגוף החומרי - וקרבתנו כו', שאזי ממילא כמים הפנים לפנים יתעורר גם הוא לדבקה בו ולהמשיך אוא\"ס ב\"ה למטה ולהעלות כל העולם כולו לה', שזהו ע\"י התומ\"צ ובפרט ע\"י הצדקה, שהיא עיקר המצות מעשיות ועולה על כולנה - במילוי הציווי לעשות משכן ודירה לו ית' בתחתונים.</p>\n<p>בברכת הצלחה בעבוה\"ק,</p>\n<p><b>מ. שניאורסאהן</b></p><p>* * *</p>\n<p>לכתבו ע\"ד קופסאות הכולל - לפלא השאלה לאחרי הזירוז <b>ומכאו\"א</b> דרבותינו נשיאינו. ואשרי המשתדל בזה העושה והמעשה.</p>\n<p>בפירש\"י ר\"פ וארא: וארא אל (מפני שהן) האבות (ולא מפני שאברהם מכניס אורחים וכו').</p>\n<h4><i><b>ח'תתקנב</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ו ע' 395 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>בי' לד\"ה:</b> אוה\"ת בראשית (כרך ג) תעג, ב ואילך.</p>\n<p><b>דרמ\"צ ח\"ב:</b> ובאוה\"ת תשא ע' א'תתנד.</p>\n<p><b>לכתבו:</b> קטע זה למו\"ה יצחק דובאוו. אגרות נוספות אליו - לעיל ח'תשט, ובהנסמן בהערות שם.</p>\n<p><b>קופסאות הכולל:</b> חב\"ד.</p>\n<p><b>בפרש\"י:</b> ראה גם לקו\"ש ח\"ג ע' 860.</p>\n<p><b>שאל משה: </b>ב\"ב י, ב.</p>\n<p><b>זה עתה... העגל: </b>תנחומא ר\"פ תשא. רש\"י תשא ל, טז.</p>\n<p><b>לאמר - לדורות: </b>כדמוכח ממרז\"ל בב\"ב.</p>\n<p><b>ביום... בעגל: </b>סנהדרין קב, א.</p>\n<p><b>אתה דוקא: </b>ולא כבשאר המנינים, וכהערת חדא\"ג בב\"ב שם.</p>\n<p><b>ראשם של ישראל: </b>ראה בארוכה בי' לד\"ה השמים כסאי ס\"ג (נדפס בלקו\"ת לג\"פ).</p>\n<p><b>לשאת... בהגבהה: </b>רש\"י ב\"ב שם.</p>\n<p><b>תמנה אותם: </b>דאין מקרא (והענין) יוצא מידי פשוטו.</p>\n<p><b>לגלות חיבתם: </b>ראה רש\"י ר\"פ שמות. ובפרט כאשר המנין הוא באופן דתשא <b>את</b> - שאז לכולי עלמא חשוב ולא בטל (ביצה ג, ב). - ועפ\"ז מתורצת התמי' בסוגית ב\"ב דההרמה היא ע\"י צדקה - שא\"כ למה מנה אותם. ותגדל התמי' ביותר - דאיך זה יסייע ענין המנין להרמת קרנם והרי אדרבה - אסור למנות את בנ\"י (שו\"ע רבנו הזקן או\"ח סקנ\"ו סט\"ו - במ\"מ שם עה\"ג \"רמ\"א\" ואולי צ\"ל \"שמ\"א\" או \"ש\"א\" - שמואל א'). ועכצ\"ל דיש במניית בנ\"י ענין נעלה, וכנ\"ל.</p>\n<p><b>חטא המונע: </b>שלכן תמה משה במה תרום כו'. וראה ג\"כ שמו\"ר ר\"פ תשא: כי תשא חייבין לי ישראל. ופי' הצ\"צ (דרמ\"צ ח\"ב רסט, א) ע\"פ הירוש' שקלים (ב, ג) חוב עבור העוונות ע\"ד עוונותי עברו ראשי.</p>\n<p><b>ונתנו... נפשו: </b>ראה פי' הרגמ\"ה בב\"ב שם.</p>\n<p><b>כמש\"נ וחטאך: </b>ראה צ\"צ שם.</p>\n<p><b>כל... משרע\"ה: </b>תניא רפמ\"ב. וראה תקו\"ז תס\"ט (קיד, א): אתפשטותא דמשה בכל דרא ודרא... עד שתין ריבוא.</p>\n<p><b>אהבת... לפנים: </b>תניא ספמ\"ט.</p>\n<p><b>יתעורר... בו: </b>תניא הקדמה לשער היחוה\"א. ושם: אהבה זו רצה מרע\"ה ליטע בלב כל ישראל כו' עיי\"ש.</p>\n<p><b>ולהמשיך... לה': </b>תניא ספמ\"ט.</p>\n<p><b>הצדקה... כולנה: </b>תניא פל\"ז (מח, ב - מט, א).</p>"],[1200970281,"ח'תתקנג\n\n<p>ב\"ה, כ\"ד אד\"ר תשכ\"ה</p><p>ברוקלין.</p>\n<p>ברכה ושלום!</p>\n<p>במענה למכתבה מי\"ט טבת, שנתקבל באיחור זמן רב, בו כותבת כמה שאלות בדיני ומנהגי ישראל.</p>\n<p>ובכלל אין עניני לפסוק שאלות, ואין כל צורך בזה, שהרי כמה מורי הוראה בעירה, אליהם תפנה ויבארוה השאלות לכל פרטיהן (שלפעמים רבות קשה להעלותן על הכתב במכתב).</p>\n<p>בכל זה כיון שכבר כתבה עכ\"פ אענה על שאלה הראשונה, ובנוסח שלה, בעית כיסוי הראש באשה, על מה מסתמך המנהג וכו'.</p>\n<p>הנה זהו דין גמור בתורתנו הק' תורת חיים, ולא מנהג בעלמא (אף שגם מנהג ישראל חשיבות גדולה לו) ולא עוד אלא שגם בין הדינים - חשיבות מיוחדה לקיום דין זה, כיסוי הראש באשה (נשואה, כמובן) כמובן מגודל השכר בעד קיום דין זה, ובלשונו המדוייק [הועתק במפרשי השולחן ערוך חלק אורח חיים סימן ע\"ה (שם מבואר דין זה דכיסוי הראש בפרטיות) - שם מובא גם העונש, אבל בוחר אני להעתיק בהנוגע להשכר] מאמר הזהר הק' דפרשת נשא (הועתק במשנה ברורה הלכות קריאת שמע סי' ע\"ה): בנהא יסתלקון בחשובין על שאר בני עלמא ולא עוד אלא דבעלה מתברך בכל ברכאן דלעילא וברכאן דלתתא בעותרא בבנין ובני בנין וכו'.</p>\n<p>עוד להוסיף בהאמור, שפלא גדול על כל מי שניצוץ אמונה יש בלבו ורוצה אשר החיים לאחרי הנשואין מאושרים יהיו לאמיתתן - בנוגע להבעל והאשה ובניהם שיברכם השי\"ת.</p>\n<p>האומנם יש תפיסת מקום להאי נעימות (אפילו <b>את\"ל</b> שיש בזה אי נעימות) שיש בכיסוי הראש בערך הברכה מהשם, יוצר האדם ובורא העולם ומנהיגו?! והרי זוהי קלות דעת שאין כמוה, אפילו באם ספק וספק ספיקא בהכרח הענין, ועאכו\"כ בדבר המפורש.</p>\n<p>מובן שיודע הנני הקושיא על האמור, שהרי נמצאים כמה וכמה שאין שומרים על דין האמור - אלא שקשיא זו קיימת היא כמה אלפים שנה, שאתם המעט מכל העמים ואיך זה דיניהם שונות מכל עם, ולצערנו הרב הרי גם בתוככי בנ\"י יש למצוא כאלו שלע\"ע מחללים השבת בפרהסיא ועד לנשואי תערובת ר\"ל, ופשוט שאין זה גורע ח\"ו כלל וכלל בעניני חיונים של תורתנו תורת חיים ומצותי' עליהם נאמר וחי בהם, כמו שעשיית העגל בזמנו (ובסמיכות לזמן מתן תורה) לא נגרע עי\"ז כלל וכלל בחיונית של עשרת הדברות ולאחרי זה דכל התורה ומצותי' ועד לדורנו זה.</p>\n<p>ובהמצאנו בימים ספורים לפני ימי הפורים, הרי - כנ\"ל טענה זו היתה טענת המן, והמסקנא שלו לא רק אבדן חיים הרוחנים של עם ישראל אלא להשמיד <b>כל</b> היהודים מנער ועד זקן טף ונשים,</p>\n<p>שהרי קיום בנ\"י <b>בכל</b> מקום שהם הוא אך ורק ע\"י התורה ומצותי' שניתנו מהשם אחד לגוי אחד בארץ.</p>\n<p>בברכה.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ח'תתקנג</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ג ע' 263 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>כיסוי הראש:</b> ראה גם לעיל חי\"ג אגרת ד'שעב. ובכ\"מ.</p>"],[1200970282,"ח'תתקנג*\n\n<p><i>[אדר תשכ\"ה]</i></p>\n<p>עניתי כו\"כ פעמים (להכותב ולעוד כמה ששאלו כיו\"ב) - בכ\"ז אכתוב עוה\"פ:</p>\n<p>1) דבר הפשוט שאפשר ובידי אנ\"ש שי' יושבי אהקת\"ו לפעול <b>רבות ונצורות</b> שם - <b>ובמכ\"ש וק\"ו</b> - מכל אלו התנועות והחוגים שם שפתחו לאחרונה כו\"כ ישיבות ת\"ת ביהכנ\"ס וכו' אף שאין להם הנשיאות חן והסיוע מכו\"כ משרדים שישנו לעניני חב\"ד, גם לא ההיכרות שאפשר להשיגה (או שכבר ישנה) <b>ועוד ועוד,</b> ועוד - ועיקרי: גם לא ברכת כ\"ק רבותינו נשיאנו המיוחדה לעניני חב\"ד.</p>\n<p>2) דבר הפשוט שאין מקום לשלוח גענעראלען מכאן.</p>\n<p>3) דבר הפשוט שאין מקום לשלוח מורים ומנהלי בתה\"ס מכאן - וגם אין כל צורך בזה - שהרי כהנ\"ל מוצאים על אתר.</p>\n<p>4) דבר הפשוט שכהנ\"ל דורש עבודה מסודרת ואז <b>אין גבול</b> להתפשטות האפשרית (דוגמא מפעולות יחידים <b>ממש</b> הר\"ר ברוק שי' בראל\"צ סלונים בירות\"ו זילברשטרום שי' שם וולף שי' בלוד חפר שי' בכפר, איידלקופ שי' שם <b>ועוד</b>) <b>וכהנ\"ל</b> - לא חכו להתמנות פעם אחר פעם \"ולזריקות\" וכו'.</p>\n<p>5) <b>דבר הפשוט</b> שבהעדר פעולה אפילו כשמלבישים אותו באצטלא של יר\"ש וחסידות וכו' תוצאותיו - ע\"ד הנראה <b>במוחש</b> הנוגע.. המצב.. בכלל (דירת מאות משפחות מגזע חב\"ד, לפני זמן קצר - כו\"כ ביהכ\"נ חב\"ד, רבני אנ\"ש וכו') ועוד.</p>\n<p>6) אין מקום למינוים מעבר לים, וגם ללא תועלת - כי זה וואס שטייט אן לעשות מה לנוגע להזולת (ולא רק בעניני פרנסתו הוא) אין זקוק למנוי, ומי שאינו רוצה לעשות מה - כו\"כ תירוצים מן המוכן אצלו להמשיך בשטתו זו, כמו שנהג כזה ע\"ע, אף שנודע לכל ומפורסם שהשיטה הזו היא <b>בנגוד מוחלט לפקודות ברורות</b> של רבותינו נשיאינו.</p>\n<p>7) עצות והוראות מסוג זה שכותב אודותם <b>ברורות</b> בכל שטח לפי ענינו, ע\"פ מה שרואים איך שפעלו אחרים בשטח המקביל אשתקד ולפני שנתיים - ובכמה ענינים: איך שפועל כ\"א בעצמו כשהדבר נוגע <b>לפרנסתו הגשמית והפרטית.</b></p>\n<p>8) דבר פשוט שלו בא קירוב הלבבות ואיחוד אנשי חב\"ד - הייתה ההצלחה פי כמה בהנ\"ל, אבל אפילו בהמצב בזה עתה - גם כן כר <b>נרחב</b> לפעולות מוצלחות.</p>\n<h4><i><b>ח'תתקנג*</b></i></h4>\n<p><b>הר\"ר ברוק:</b> חיים שאול.</p>\n<p><b>סלונים:</b> עזריאל זעליג.</p>\n<p><b>זילברשטרום:</b> אהרן מרדכי.</p>\n<p><b>וולף:</b> אפרים.</p>\n<p><b>חפר:</b> שמואל.</p>\n<p><b>איידלקופ:</b> יונה.</p>"],[1200970283,"ח'תתקנד\n\n<p>ב\"ה, אור ליום א' דר\"ח אדר הסמוך לניסן, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לכבוד הדר\"ג הנהלת \"אוצר הפוסקים\"<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>באיחור קבלתי מכתבם במענה על פניתי לעורר דעת הרבנים ודעת הקהל בבעיות הכי חמורות הקשורות עם ענין אימוץ ילדים וילדות.</p>\n<p>ומה שכותבים שברצונם להדפיס הדברים באוצה\"פ כיון שהם בעלי חשיבות מרובה, רצוני כן לעשות רצונם, ובפרט על פי ידיעותי שעוד ניתוסף עליהן - מגודל הפרצה השוררת כעת בשטח האמור, וכן בשטח הטיפולים הרפואיים אודותם מדובר במכתבי הנ\"ל.</p>\n<p>ויהי רצון אשר הדפסה האמורה תביא תועלת המקווה. ואם בסגנון חכמינו ז\"ל המציל נפש אחת מישראל כאילו הציל עולם מלא, על אחת כמה וכמה להביא תיקון בכמה בתי ישראל, שתקותי חזקה שכשיעוררו שימת לב בני ובנות ישראל לחומר בעיות האמורות, הרי לבן של ישראל ער הוא אפילו כשנמצאים בבחינת \"אני ישנה בגלותא\", גלות מבחוץ וגלות מבפנים, ויבוא הענין על תיקונו.</p>\n<p>בכבוד ובברכת הצלחה בפעלם הנעלה לזכות את הרבים באורה זו תורה וכו' ויהי רצון שכל אחד ואחד יעשה בהאמור מתוך אורה ושמחה וששון ויקר גם כפשוטו של מקרא - ובהוקרה.</p>\n<h4><i><b>ח'תתקנד</b></i></h4>\n<p><b>על פניתי:</b> דלעיל אגרת ח'תתקכד.</p>\n<p><b>בסגנון חכמינו:</b> סנהדרין לז, א.</p>\n<p><b>אני ישנה:</b> זח\"ג צה, א.</p>\n<p><b>באורה של תורה:</b> מגילה טז, ב.</p>"],[1200970284,"ח'תתקנה\n\n<p>ב\"ה, ראש חודש אדר שני, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>צום יערלעכן באנקעט פון דער ליידיס<br>\nאקזילערי פון<br>\nבראנזוייל און איסט ניו-יארק פאר די<br>\nליובאוויטשער<br>\nישיבות תומכי-תמימים</p>\n<p>שלום וברכה!</p>\n<p>די יערלעכע אונטערנעמונג קומט היי-יאר פאר אין א העכסט-גינסטיגע צייט - אין דער צייט צווישן די צוויי פורים'ס. ספעציעל איז די צייט א גינסטיגע פאר אידישע פרויען, נעמענדיג אין אכט דעם וויכטיגען ארט פון אסתר המלכה אין דעם נס פון פורים, בימים ההם בזמן הזה.</p>\n<p>אסתר המלכה האט זיך געקענט פילן גאנץ זיכער אין איר פערזענלעכער לאגע; און מרדכי איז דאך זיכער געווען גערעכט, אז <b>ריוח והצלה יעמוד ליהודים ממקום אחר</b> - דעם אויבערשטנס הילף קען קומען דורך אן אנדערן. איז צו וואס זאל זי איינשטעלן איר לעבן פאר א צווייטן? אבער אסתר האט ניט געמאכט קיינע פערזענלעכע חשבונות; זי איז געגאנגען אויף מסירות-נפש צו ראטעווען אידן. און דעריבער האט זי אויך זוכה געווען, אז די מגילה ווערט אנגערופן אויף איר נאמען.</p>\n<p>דערפון איז אן אנווייזונג פאר אידישע פרויען, אין אלע צייטן, אז כאטש וועלכע פרוי קען זיך גלייכן צו אסתר המלכה, איז אבער זיכער, אז יעדע איינע קען גאר פיל אויפטאן אויף איר אייגענעם אופן, און אין איר אייגענער סביבה, אויב זי וועט אויספילן די תורה-אנווייזונגען און וועט עס טאן מיטן גאנצן הארצן, ווי אסתר המלכה האט געוויזן א לעבעדיגען ביישפיל וואס א אידישע פרוי איז בכוח צו טאן.</p>\n<p>און פונקט ווי אין דער צייט פון דעם ערשטן פורים, ווען המן'ס גזירה איז בטל געווארן אין דעם מאמענט ווען מרדכי האט פארזאמלט די אידישע קינדערלעך און האט מיט זיי געלערנט תורה, מיט אזא באגייסטערונג און אומבאגרענעצטע ליבשאפט פאר תורה ומצוות, ביז זיי האבן זיך ניט געוועלט אפרייסן פון מרדכי הצדיק - אין לעבן, אדער ח\"ו פארקערט -</p>\n<p>אזוי איז אין אלע צייטן דער יסוד פון דעם גאנצן קיום פון אונזער פאלק - דער תורה-חינוך פון די אידישע קינדער.</p>\n<p>און דאס איז דאך די אויפגאבע און די ארבעט פון דער ליידיס אקזעלערי - צו העלפן די ליובאוויטשער ישיבות תומכי-תמימים צו באזארגן א תורה-חינוך על טהרת הקדש פאר זייערע פילצאליגע תלמידים, כן ירבו.</p>\n<p>דער יערלעכער באנקעט איז דער הויכפונקט אין דער דאזיגער ארבעט, און איך וויל האפן, אז אלע וועלן טאן אלץ וואס נאר מעגלעך צו זען, אז דער באנקעט זאל זיין מיט גרויס הצלחה אין אלע הינזיכטן.</p>\n<p>זייט אלע געבענטשט, צוזאמען מיט אייערע בני-בית שיחיו, אין אלץ וואס מען נויטיגט זיך, בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה להצלחה ולבשורות טובות ולפורים שמח.</p>\n<h4><i><b>ח'תתקנה</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ו ע' 376 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>האט פארזאמלט:</b> אסת\"ר פ\"ט, ג (ד).</p>"],[1200970285,"ח'תתקנו\n\n<p><i>[ז' לחודש אדר הסמוך לניסן, ה'תשכ\"ה]</i></p>\n<p>... והרי גם זה מעניני ימי הפורים האלה, אשר דרשו חכמינו ז\"ל ליהודים היתה אורה - זו תורה. ואדמו\"ר האמצעי מפרש בזה (מתורת אדמו\"ר הזקן) דיוק הלשון \"אורה\" בתוספת \"ה\", כי בפרטיות הרי \"תורה - אור\" לשון זכר הוא המדובר בתורה שבכתב, ו\"תורה - אורה\" המדובר בתורה שבעל פה (ובשרשה) ובאה ע\"י מס\"נ.</p>\n<p>ויהי רצון שעל פי הכלל שקבעו חכמינו ז\"ל אין מקרא יוצא מידי פשוטו, יהי' ליהודים אורה ושמחה וששון ויקר גם כפשוטו ובכל הענינים.</p>\n<h4><i><b>ח'תתקנו</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"א ע' 343.</p>\n<p><b>דרשו חכמינו:</b> מגילה טז, ב.</p>\n<p><b>ואדמו\"ר האמצעי מפרש:</b> בשערי אורה שער הפורים ד\"ה וקבל היהודים פל\"ב ואילך.</p>\n<p><b>הכלל:</b> שבת סג, א. וש\"נ.</p>"],[1200970286,"ח'תתקנז\n\n<p>ב\"ה, י' אד\"ש תשכ\"ה</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה הלל שי'</p>\n<p>שלום וברכה!</p>\n<p>...במענה לשאלתו - ידועה דעתי מאז שעל אנ\"ש שי' ובפרט כו' להשתדל לתפוס עמדה בפאריז לפעול שם וכו' - ופשיטא שענין רבנות בכלל זה ומהחשובים. בנוגע להצעה פרטית והפרטים בזה - יש להתייעץ עם ידידים הנמצאים על אתר.</p>\n<h4><i><b>ח'תתקנז</b></i></h4>\n<p><b>מו\"ה הלל שי':</b> פווזנר, פריז. אגרות נוספות אליו - לעיל חכ\"ב ח'שנ, ובהנסמן בהערות שם.</p>"],[1200970287,"ח'תתקנח\n\n<p>ב\"ה, י\"א אד\"ש, ה'תשכ\"ה</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>...ובעמדנו ימים אחדים לפני ימי הפורים הבע\"ל ובפרט ע\"פ דברי חכמם במשנתם: מגילה נקראת (גם לשון הווה) בי\"א כו' בט\"ו.</p>\n<p>יה\"ר שיקרא וימשיך כל אחד ואחת, בתוככי כלל ישראל, המגלה ועניני', כל עניני פורים, וכדיוק השם פורים, לשון רבים, אף כי נקרא \"פורים ע\"ש הפור\" וביאר כ\"ק אדמו\"ר הצ\"צ שזהו ב' בחי' פור - פור דהמן (דלעו\"ז) ופור הוא הגורל דקדושה, נעים גורלנו שלמעלה מטעם ודעת, ע\"ד טוב מאד זה יצה\"ר כשנהפך לטוב.</p>\n<p>ובדרך אפשר אולי מקום להוסיף דיוק בזה, שנקרא שם דוקא בלשון המן, פורים ולא גורלות,</p>\n<p>ע\"פ המבואר בדא\"ח בכ\"מ שעבודת נפה\"א בנפש הבהמית ובגוף פועלת הוספת כח גם בעבודת נפה\"א, וע\"ד מעלת לאתבא צדיקיא בתיובתא.</p>\n<p>היינו שעיקר העילוי דלעתיד לבוא הוא שהצדיק יהי' במעלת בע\"ת (ולא זה שהבע\"ת יהי' במעלת צדיק),</p>\n<p>ומוכרח זה גם ע\"פ הידוע שהנשמה קודם ירידתה היתה במעלת צדיק, אשר עם המלך במלאכתו ישבו שם וכדחז\"ל על הכתוב שנמלך בנשמותיהן של צדיקים, והירידה היא צורך עלי' (גם בעודן בעוה\"ז מלובשות בגוף הגשמי) - בכדי לאהפכא חשוכא לנהורא - העילוי דתשובה...</p>\n<h4><i><b>ח'תתקנח</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ו ע' 373.</p>\n<p><b>בד\"ה... 16: </b>אוה\"ת פנחס ע' א'סג.</p>\n<p><b>י\"א: </b>ענינו בקדושה ראה לקו\"ת מסעי (צח, ג).</p>\n<p><b>ימים אחדים: </b>בזמן שהן עוברין בשמחה נקראין אחדים (לק\"ט שמות ב, כג). ולהעיר מלקו\"ת שה\"ש (ה, ד): יום אחד... יום וגילוי בחי' אחד.</p>\n<p><b>חכמים במשנתם: </b>ריש מס' מגלה. וראה לקו\"ת בחוקותי (מח, ד).</p>\n<p><b>לשון הווה: </b>ראה טושו\"ע או\"ח סו\"ס תרפ\"ח. לקו\"ת שמע\"צ (פו, א).</p>\n<p><b>בי\"א כו' בט\"ו: </b>י\"א כמנין אותיות ו\"ה שבשם, ט\"ו כמנין י\"ה שבשם שהפריד ביניהם עמלק (של\"ה פ' תצוה - שכט, א). שמבני בניו הי' המן (תרגום שני למג\"א. מס' סופרים פי\"ג). וראה סד\"ה מגלה נקראת תרכ\"ט. לקו\"ת ברכה (צז, ב).</p>\n<p><b>יקרא וימשיך: </b>ראה תניא ספל\"ז. לקו\"ת ויקרא (ה, ב).</p>\n<p><b>יקרא וימשיך... ואחת: </b>דאף הן היו באותו הנס (מגילה ד, א). ולהעיר שאסתר דוקא בקשה (ופעלה): 1) כתבוני 2) לדורות (מגילה ז, א. משא\"כ בקבלת ימי הפורים דכתבו מרדכי ואסתר כבירושלמי שם. ועיין בבלי שם: שלחה אסתר קבעוני לדורות ובפירש\"י.</p>\n<p>ואכ\"מ). ולהעיר מלקו\"ת ס\"פ ברכה.</p>\n<p><b>וביאר... הצ\"צ: </b>בד\"ה אך בגורל (בביכל במדבר 16)15 - נכלל (ובתוס' ביאור) בד\"ה אך בגורל תרכ\"ו. וראה לקו\"ת ויקרא (ב, ד): משכני גו' נרוצה גו'.</p>\n<p><b>נעים גורלנו: </b>ראה אגה\"ק ס\"ז (<b>וגו'</b> הראשון אשר שם - מכוון לסיום הכתוב: אתה תומיך <b>גורלי</b>). לקו\"ת בשלח (א, ב): נועם הוא כו'.</p>\n<p><b>וכדחז\"ל על הכתוב: </b>רות רבה רפ\"ב. וראה לקו\"ת ר\"פ תצא.</p>\n<p><b>והירידה... לנהורא: </b>עיין לקו\"ת במדבר ב, א ואילך. ושם רד\"ה מה טובו: יש ע\"ז כמה תירוצים אך התירוץ האמתי הוא כו'.</p>"],[1200970288,"ח'תתקנט\n\n<p>ב\"ה, י\"א אדר שני, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>צו דער יערלעכער מסיבה פון די \"נציבי הישיבה\" תומכי-<br>\nתמימים ליובאוויטש אין מאנטרעאל<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>איך שיק מיין באגריסונג צו אלע אנטיילנעמער אין דער יערלעכער מסיבה, צוזאמען מיט דער ברכה אז די אונטערנעמונג זאל זיין מיט גרויס הצלחה אין אלע הינזיכטען.</p>\n<p>הייאר קומט די יערלעכע מסיבה פאר אין אן עיבור יאר און אין דעם חודש אדר שני. אונזער אידישע לוח, וואס באשטימט אלע צייטען און ימים-טובים אינם יאר, איז פארבונדען מיט דעם גאנג פון דער לבנה און אויך מיט די תקופות (סיזאנס) וועלכע זיינען אפהענגיק פונם גאנג פון דער זון. דער לבנה-יאר בלייבט \"הינטערשטעליק\" אויף אומגעפער 11 טעג א יאר לגבי דעם זון-יאר. דעריבער ווערט אלע צוויי-דריי יאר איינגעפירט אן עיבור יאר (מיט א פולן חדש מער), כדי צו <b>דערגענצען</b> די צייט (אזוי אז יעדער יום-טוב זאל פארקומען אין דער ריכטיקער צייט: פסח - אין חודש פון פרילינג; סוכות - אין חודש פון הערבסט-שניט, וכו').</p>\n<p>איינע פון די אנווייזונגען פון דעם עיבור-יאר איז די תורה האט אידען געגעבען א כוח צו באהערשען די צייט; און כאטש בכלל איז א מענטש ניט קיין בעל-הבית אויף דער <b>פארגאנגענער</b> צייט, האט א איד די מעגלעכקייט צו דערגענצען דאס וואס ער האט פארפעלט. נאך מער, ס'איז אפילו מעגלעך איינצושאפען זיך א \"רעזערוו\" פאר דער צוקונפט, ווי דאס ווערט אנגעדייטעט אין אן עיבור יאר.</p>\n<p>און אין אט דעם חודש - וואס ווערט פארדאפלט אין אן עיבור יאר - ווערט געפייערט דער יום-טוב פורים. ווי אונזערע חכמים, זכרונם לברכה, דערציילען, איז די גזירה פון המן הרשע בטל געווארן אין דעם מאמענט ווען מרדכי הצדיק האט צונויפגעזאמעלט די אידישע קינדער און האט אין זיי דערוועקט דעם גייסט פון מסירת נפש פאר תורה-אידישקייט. דערמיט איז דערגענצט געווארן דאס וואס איז פריער פארפעלט געווארן אין דעם געביט פון חינוך על טהרת הקדש, און דאס האט געבראכט דעם נס פון <b>ונהפוך הוא</b> און - <b>ליהודים היתה אורה ושמחה וששון ויקר.</b></p>\n<p>ווען פורים קומט פאר אין אן עיבור יאר, ווי הייאר, קומען זיך צוזאמען, און ווערן ספעציעל אונטערשטראכען, די דערמאנטע צוויי נקודות: די לעבענסנויטווענדיקייט פון תורה-טרייען חינוך פאר דעם קיום פון אונזער פאלק, און די מעגלעכקייט וועלכע ווערט אונז געגעבען, ניט נאר צו דערפילען וואס מען האט פארפעלט, נאר אויך שאפען א רעזערוו\" פאר דער צוקונפט.</p>\n<p>יאך וויל האפען, אז די הייארדיקע יערלעכע מסיבה וועט געבען דעם פולען אויסדרוק צו דאס אויבענדערמאנטע, און דער זכות פון הפצת התורה והמצוות וועט ביישטיין יעדן איינעם און איינער שיחיו, בתוך כלל ישראל, צו געניסן אין דער פולסטער מאס פון ליהודים היתה אורה ושמחה וששון ויקר - מיט אלע פירושים.</p>\n<p>בכבוד ובברכה להצלחה ולבשורות טובות.</p>\n<h4><i><b>ח'תתקנט</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ו ע' 378 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>אונזער אידישער לוח:</b> בהבא לקמן ראה רמב\"ם הל' קידוה\"ח רפ\"א ורפ\"ד. לקמן אגרת ח'תתקסה.</p>\n<p><b>חכמים... דערציילן:</b> אסת\"ר פ\"ט, ג (ד).</p>"],[1200970289,"ח'תתקנט*\n\n<p><i>[נוסח המברק לקראת חג הפורים תשכ\"ה]</i></p>\n<p>פורים שמח והתועדויות פעילות.</p>\n<p>/<b>מקום חתימה</b>/</p>"],[1200970290,"ח'תתקס\n\n<p>ב\"ה, כ' אדר שני תשכ\"ה</p><p>ברוקלין.</p>\n<p>ברכה ושלום!</p>\n<p>במענה למכתבה ממוצש\"ק, בו כותבת אודות הקישוים שפגשה בלמדה \"תוכן הענינים\" המדוברים בשיחות שבת קדש, שמבינה הענין בכללותו אבל לא תמיד לפרטיו.</p>\n<p>ובכלל בשיחות האמורות, ישנן כמה חלקים, כיון שהבאים ללימוד זה גם כן שייכים לסוגים שונים בהבנת התורה, אבל בכל אחת מהן - כל סוג יכול למצוא ענין שהבנתו מתאימה לידועותיו נוסף על הבנת כללות הענין, ובטח גם בנוגע אלי' כן הוא, וכשתתקדם בלימוד התורה בודאי תבין עוד חלק ועוד חלק וכו'. ואין ענין ללמוד ספרים בכדי להבין אלו השיחות, כי לא זו הדרך, כי אם להתקדם בלימוד והבנת התורה צעד אחר צעד, ובנקודה העיקרית - שתתאים להוראת רבנו הזקן בהלכות תלמוד תורה סוף פרק ראשון, בנוגע ללימוד התורה של נשים שהשתדלות בהעיקר - שיהי' הלימוד מביא לידי מעשה, חדור יראת השם ואהבת השם (כמובן ג\"כ בהלכות ת\"ת הנ\"ל).</p>\n<p>בברכה להצלחה בכל ולבשו\"ט בזה.</p>"],[1200970291,"ח'תתקסא\n\n<p>ב\"ה, כ\"א אדר שני תשכ\"ה</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' מו\"ה חיים שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מי\"ח אדר שני, בו כותב סברות שונות אודות אופן יקום יד ושם לזכותה של אמו ע\"ה, שרצונו לעשות זה ע\"י השקעת כסף במוסד חינוך בני ישראל על טהרת הקדש, ויש לו בזה שתי סברות.</p>\n<p>וע\"פ הוראת חז\"ל, אין מעבירין על המצות, ומצוה הבאה על ידך אל תחמיצנה, נכון לקבל העצה שבירושלים עיה\"ק ת\"ו, שאז הרי תיכף ומיד תהיינה פירות מהשקעה זו, צאן פרי מצוה.</p>\n<p>ואם בכל ענין טוב צריכה להיות זריזות וכנ\"ל שלא להחמיץ, עאכו\"כ בשטח החינוך הט', שבאם אין קולטים את המחונך תומ\"י למסגרת מתאימה, סכנה צפוי' מפני הרוחות בלתי רצויות המנשבות בחוץ וכו' וד\"ל.</p>\n<p>בברכה שמכאן ולהבא לא ידע עוד מכל צער ועגמת נפש ח\"ו, ומתוך בריאות וטוב לבב יעשה ויפעול בהפצת התורה והמסורה באופן דמוסיף והולך ואור.</p>\n<p>ובברכה לבשו\"ט בכל האמור.</p>\n<h4><i><b>ח'תתקסא</b></i></h4>\n<p><b>מו\"ה חיים:</b> סאמועל, ירושת\"ו.</p>\n<p><b>הוראת חז\"ל:</b> פסחים סד, ב. וש\"נ.</p>\n<p><b>ומצוה הבאה:</b> ראה מכילתא (הובא בפרש\"י) בא יב, יז.</p>\n<p><b>מאן פירי:</b> סוטה מו, סע\"א.</p>"],[1200970292,"ח'תתקסב\n\n<p><i>[כ\"ד אדר שני תשכ\"ה]</i></p>\n<p>...ומה טוב בשטח החינוך... והרי תפקיד טוב וקדוש הוא - לחנך ילדי ישראל, שעל כל אחד מישראל נאמר בנים אתם לה' אלקיכם, ובפרט ע\"פ פתגם הידוע של הבעש\"ט, אשר אהבת השם לכ\"א מישראל הוא באין ערוך יותר מאהבת הורים זקנים לבן יחידם שנולד להם לעת זקנותם.</p>\n<h4><i><b>ח'תתקסב</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ב ע' 366.</p>\n<p><b>פתגם:</b> ראה גם לעיל אגרת ח'תתעד, ובהנסמן בהערות שם.</p>"],[1200970293,"ח'תתקסג\n\n<p>ב\"ה, ד' ניסן תשכ\"ה</p><p>ברוקלין.</p><p>מרת חסיא תחי'</p>\n<p>ברכה ושלום!</p>\n<p>נאך א ליינגערן איבעררייס איז מיר אנגעקומען אייער בריף פון כ\"ט אדר שני מיט דאס בייגעלייגטע, אין וועלכען איר שרייבט אז השם יתברך האט אייך געהאלפען און האט דורכגעפירט אייער הארץ פארלאנג צום גוטען, צו אפשרייבען אייער הויז לטובת אגודת חב\"ד, פארן צוועק צו זיין דארט א בית תפלה ולימוד התורה.</p>\n<p>און זיכער איז דאס א גוטער אנהויב צו פארפולקאמען די זאך אזוי אז איר אליין בא אייער לעבען זאלט הנאה האבען און געניסען די פרייד אין דעם, און איינטיילנעמען אליין מיט איעיר מאן שי' אין די תפלות אין דעם בנין.</p>\n<p>און ווי באוואוסט דער ווארט פון מיין שווער כ\"ק מו\"ח אדמו\"ר נשיא ישראל, אויף דעם וואס שטייט, עולמך תראה בחייך, צו פארטיילען די ענינים פאר צדקה תורה ומצות באם לעבען, און דאס איז אויך א סגולה צו אריכות ימים ושנים טובות,</p>\n<p>און מיר זיינען צוגעזאגט געווארען אין ענליכע פאלען, אז ווען מען באשליסט מיט א שטארקייט, העלפט השם יתברך צו דורכפירען דאס מיט פיל ווייניגער שוועריקייטען ווי מ'האט זיך פארגעשטעלט, און מ'טוט דאס מיט גוטען געזונט גוטע שטימונג און מיט אמת'ע פרייד.</p>\n<p>און מיר געפינען זיך דאך אין דעם חדש ניסן, חדש הגאולה, באפרייאונג פון אלע שטערונגען וועכלע זיינען אין וועג, צו אויספילען דעם גוטען וילען אין דער פולסטער מאס.</p>\n<p>בברכה לבשורות טובות בכל אמור ולחג פסח כשר ושמח.</p>\n<h4><i><b>ח'תתקסג</b></i></h4>\n<p><b>מרת חסיא:</b> גולדנברג, נתני'.</p>\n<p><b>פארן צוועק... בית תפלה:</b> ראה גם לקמן אגרת ח'תתקפא.</p>\n<p><b>דער ווארט:</b> ראה גם לעיל חכ\"א אגרת ז'תתפ, ובהנסמן בהערות שם.</p>"],[1200970294,"ח'תתקסד\n\n<p>ב\"ה, ו' ניסן תשכ\"ה</p><p>ברוקלין.</p>\n<p>ברכה ושלום!</p>\n<p>במענה חמכתבה מכ\"ה אד\"ש בו כותבת אודות יום הולדת שלה,</p>\n<p>ובודאי מוסיפה בעניני יהדות ומצות כציווי תורתנו הק' תורת חיים להעלות בקדש,</p>\n<p>ונוסף על העיקר מילוי הציווי - הרי זה גם הצנור והכלי לקבלת ברכות השי\"ת בהמצטרך.</p>\n<p>ויהי רצון מהשם יתברך שתהי' שנה הבאה עלי' לטובה שנת הצלחה בגשמיות וברוחניות ותבשר טוב בכל האמור.</p>\n<p>בברכת חה\"פ כשר ושמח.</p>\n<p>נ.ב. לכתבה אודות עינן הבדידות, לפלא גדול, שהרי בודאי יודעת מפתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע נשיא ישראל, חסידות האט אויפגעטאן אז מ'איז ניט עלענד כו' (החסידות פעלה במה שסילקה ענין הבדידות). שאם בנוגע להקשר שבין רבי וחסיד הדברים אמורים, כמבואר שם בארוכה עאכו\"כ להקשר שבין אדם לאדם שבסביבתו, ופשיטא שכן הוא הקשר שבין ה' ובני ישראל, ובמיוחד מובן הענין ע\"פ יסוד תורתנו תורת חיים בענין בהשגחה פרטית, שהוא כפשוטו אשר השם יתברך משגיח בהשגחה פרטית על כל פרטי ופרטי החיים, והשגחתו וברכתו והשפעת טובו וכו' הרי אחד הם, כי מקורם אחדות הפשוטה.</p>\n<p>מהאמור משתלשל ומובן בנוגע לפועל ולהרגש, ולהשקפת חיים אשר כל אחד ואחת נמצא בעולם (עולם של כו\"כ נבראים מכל הסוגים דמדבר חי צומח ודומם) שהשפעתו עליהם, וכלל הענינים שבעולם מושפע גם הוא מהם, (ואף שמובן ופשוט שההשפעות אינן דומות כלל), וכיון שכן הוא הרי כל אחד מהם מלא תוכן עכ\"פ בכח ובו הדבר תלוי להפעיל התוכן שיבוא מכח אל הפועל, כ\"ז באופן עקרוני בנוגע לכאו\"א מישראל אשר תפקידו להיות שותף במעשה בראשית מתאים להאמור.</p>\n<p>בנוגע אלי' תגדל התמי' פי כמה, שהרי זיכתה אותה השגחה העליונה והעמידתה בשטח חינוך בני ישראל, בניו של מקום ילדי ישראל, שכל פעולה טובה שלה בהם והשפעה עליהם, הרי זה מייצר קירוב נצחי ביניהם, רוחני וקדוש טוב ומועיל גם למטה, שבכל ענינים אלו אין המקום מפסיק ואי אפשר שיחול בו פירוד (שלכן הוא נצחי) במלות אחרות, כשיושבת בחדרה ונמצאת בהרגש של בדידות, ובה בשעה אחד מתלמידי' או מהמושפעים שלה חוזר על השיעור ששמע ממנה או מברך ה' כפי שלמדה אותו וכו' הרי זה מוסיף חיות ואור בהקשר שביניהם, וא\"א שהנפש אלקית שבה לא תרגיש התוספת, כיון שענין זה הוא מעצם עצמותה, והרי פנימיות האדם ועיקרו הוא הנפה\"א שבו, ולאמתתו של דבר היא המחי' גם את הנפש הבהמית.</p>\n<p>יודע הנני שלא כל אחד מרגיש את האמור, כיון שאין נראה לעיני בשר ואין היד יכולה למשמשו, אבל אין זה ממעט כלל אמיתת מציאות הענין, שלכן בהתבוננות קלה נפתח הפתח מהנפה\"א לשכל האדם ועד לנפש הבהמית להשפיע עליה בכיוון האמור, כיון שהאדם בעל שינוים הוא ישנם זמנים שצריכים להתעוררות מיוחדה ולתוספת מיוחדת, ואז הרי עצה היעוצה להפגש עם מי שהוא מהתלמידים או המושפעים או עכ\"פ לדבר עם מי שהוא אודותם והשיעורים וכו', והרי הקול מעורר הכוונה והדבור מגלה את הענינים יותר.</p>\n<p>ריגל הדבר וכמעט טבעי הוא בבני אדם, בסגנון חז\"ל, טענו חטים והודה לו בשעורים, כוונתי שמחליפים הסיבה האמיתית בענין אחר, הסיבה במצבה ה\"ה כנראה אשר לע\"ע לא נשתדכה עדיין, וכאן המקום אתי למלאות את ידה למסור לכאו\"א מאחי' שי' בשמי, אשר פלא גדול וגם מצער, מה שאינם עושים בהאמור ככל הדרוש, והרי ברכת ה' חלה עלי' כמ\"ש וברכך ה\"א בכל אשר תעשה, עשי' בדרך הטבע וכדרוש, וק\"ל.</p>\n<p>ויהי רצון שתבשר טוב בכל האמור ובהקדם והשי\"ת יצליחה.</p>\n<h4><i><b>ח'תתקסד</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חכ\"ב ע' 380 וחל\"ג ע' 290 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>כציווי:</b> ברכות כח, א. וש\"נ.</p>\n<p><b>מפתגם:</b> ראה גם לעיל חי\"ז אגרת ו'קנה, ובהנסמן בהערות שם.</p>\n<p><b>שכל פעולה... נצחי:</b> ראה תניא פכ\"ה (לב, א).</p>\n<p><b>קול מעורר הכוונה:</b> של\"ה פב, ב. שו\"ע אדה\"ז חאו\"ח סס\"א ס\"ה.</p>\n<p><b>בסגנון חז\"ל:</b> בבא קמא לה, ב.</p>"],[1200970295,"ח'תתקסה\n\n<p>ב\"ה, י\"א ניסן ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>אל בני ובנות ישראל בכל מקום שהם<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>דער אויבערשטער האט באשטימט, אז יציאת מצרים זאל פא8רקומען אין <b>חודש</b> <b>האביב</b> (פרילינג חודש). און די תורה זאגט אן, אז מען מוז ספעציעל אכטונג געבן אז פסח זאל אלעמאל אויסקומען אין פרילינג חודש: <b>שמור את חודש האביב ועשית</b> <b>פסח לה' אלקיך, כי בחודש האביב הוציאך ה' אלקיך ממצרים לילה -</b> \"היט דעם פרילינג חודש און מאך פסח פאר ג-ט דיין ג-ט, ווארום אין פרילינג חודש האט דיך ג-ט דיין ג-ט ארויסגעפירט פון מצרים באנאכט\".</p>\n<p>כדי אפצוהיטן, אז פסח זאל אויספאלן אין חודש האביב - נעמענדיק אין אכט, אז אונזער לוח איז איינגעשטעלט לויט דער לבנה, וואס דאס שאפט א יערלעכן אונטערשיד פון ארום עלף טעג לגבי דער זון, און די זון באשטימט דאך די תקופות פון יאר - האבן מיר יעדע צוויי אדער דריי יאר אן \"עיבור יאר\" - אזוי ווי הייאר - ווען עס קומט צו א גאנצער חודש, אדר. אזוי ארום ווערט \"אויסגעגליכן\" דאס יאר פון דער לבנה מיט דעם יאר פון דער זון, און פסח פאלט אויס שטענדיק אין דעם חודש האביב. און דורך דעם ווערן אויך די חדשים פון יאר, און אלע ימים טובים, רעגולירט און איינגעשטעלט אין זייער ריכטיקער צייט.</p>\n<p>***</p>\n<p>דאס וואס יציאת מצרים איז פארגעקומען אין פרילינג חודש, ווערט דערקלערט פון אונזערע חכמים ז\"ל אלס א ספעציעלער חסד פון דעם אויבערשטן, וואס ער האט די אידן ארויסגעפירט פון מצרים אין דער בעסטער צייט פון יאר. אבער ווי אין אלע ענינים פון תורה, איז אויך אין דעם פאראן פילע אנווייזונגען, רמזים און טעמים פארן כלל און פארן פרט. איינע פון די נקודות וואס איך וויל דע ארויסברענגען, וועט קלאר ווערן ווען מען באטראכט די אומשטענדן בא וועלכע עס איז פארגעקומען יציאת מצרים:</p>\n<p>הונדערטער יארן זיינען די אידן געווען פארשקלאפט בא א פאלק וואס האט דאן באהערשט אלע ארומיקע פעלקער, ניט נאר מיטן גראבן כוח פון \"רייטוועגענער און רייטער\" (רכבו ופרשיו), נאר אויך מיט זיין געוואלדיקער איבערגעוויכט אין די געביטן פון וויסנשאפט, אין אלץ וואס מען רופט היינט אן \"קולטור\" און \"ציוויליזאציע\".</p>\n<p>די קולטור און ציוויליזאציע פון מצרים האבן זיך געשטיצט אויף די נאטור-כוחות און נאטור דערשיינונגען, ספעציעל - דער טייך נילוס. דאס לאנד מצרים איז כמעט אינגאנצן פריי פון רעגן; מענטשלעכע דערפינדלעכקייט האט אבער געשאפן א קינסטלעכע באוואסערונג, וואס האט פארוואנדלט מצרים אין א פרוכטבארן גארטן, ארומגערינגלט פון מדבריות.</p>\n<p>די דאזיקע אומשטענדן האבן מיטגעבראכט א פארצווייגטע געצנדינערישע קולאר, וואס האט געהאט צוויי הויפטשטריכן: די פארגעטערונג פון די כוחות פון דער נאטור, און די פארגעטערונג פון די כוחות פונם מענטשן וואס האט פארשטאנען ווי אויסצוניצן די כוחות פון דער נאטור. דערפון איז בלויז א קורצער שריט צו דער פארגעטערונג פון פרעה'ן, וועלכער האט פארקערפערט אין זיך דעם מצרישן אידעאל פון דעם \"געניאלן\" מענטשן.</p>\n<p>אזא סיסטעם, וואס האט באטראכט די וועלט אלס א צוזאמענשטעל פון מערערע \"נאטור כחות\", צווישן וועלכע עס איז אויך דער \"כח\" פון מענשן, מיט'ן צוגאב פון דער פילאזאפיע אז <b>כוחי ועוצם ידי עשו לי את החיל הזה - \"מיין</b> כוח און די מאכט פון <b>מיין</b> האנט האבן מיר איינגעשאפן דעם גאנצן פארמעגן\"; האט געפירט צו דער נידעריקסטער גייסטיקער און מאראליש-עטישער געפאלנקייט, וועלכע האט אויך \"בארעכטיקט\" די אומפארשעמטסטע פארשקלאפונג און גרויזאמקייטן צו דעם פיזיש-שוואכערן מענטש אדער פאלק.</p>\n<p>***</p>\n<p>די געצנדינסט און איבערגלויבן פון די מצריים האבן דערגרייכט זייער שטארקסטן אויסדרוק אין דער צייט פון דער יערלעכער באנייאונג פון די כחות פון דער נאטור - אין דעם פרילינג חודש, דער חודש פון \"מזל טלה\", און דער שעפס איז געווען פון די הויפט-סימבאלן פון דער מצרישער עבודה-זרה.</p>\n<p>***</p>\n<p>און אט קומט משה רבנו מיט דער בשורה פון \"פקוד פקדתי\" - אז עס איז געקומען די צייט ווען דער ג-ט פון אברהם יצחק און יעקב האט באשלאסן צו באפרייען די אידן פון פרעה'ס הענט און פון גלות מצרים.</p>\n<p>ס'איז שוין געווען 210 יאר ווי די אידן זיינען געווען אונטערגעווארפן צו פרעה'ן; א טייל איד זיינען שוין אפילו געווען פארשלונגען פון דער מצרישער \"קולטור\"; קיין הילף פון די ארומיקע פעלקער האט מען ניט געקענט דערווארטן; קיין איינציקער שקלאף האט (ביז דאן) ניט געקענט באפרייען זיך פון מצרים; עס איז פשוט ניט געווען קיין שום אויסזיכט, פון א נאטירלעכן שטאנדפונקט, צו באפרייען דאס אידישע פאלק פון מצרים - און דאך פארזיכערט זיי משה רבנו, אז די צייט פון באפרייאונג איז געקומען.</p>\n<p>עס איז אבער פאראן איין באדינג: <b>משכו וקחו לכם צאן למשפחותיכם ושחטו</b> <b>הפסח!</b></p>\n<p><b>משכו -</b> ציט זיך צוריק פון דער עבודה-זרה פונם לאנד; <b>וקחו לכם</b> גו' - נעמט אייך א שעפס (דאס וואס די מצריים האבן פארגעטערט) און שעכט אים אלס קרבן פסח פאר ג-ט. ס'איז ניט גענוג צו פארלייקענען די מצרישע עבודה-זרה בא זיך אין הארצן, אדער אפילו בא זיך אין דער היים, פארבארגענערהייט און שטילערהייט; נאר דוקא אין דער עפנטלעכקייט, אן מורא, לויט אלע פרטים וועלכע זיינען געווען פארבונדן מיטן קרבן פסח אין מצרים.</p>\n<p>און דאן פארזיכערט משה רבנו אין נאמען פון דעם אויבערשטן, אז ניט נאר מ'וועט באפרייט ווערן פון מצרים, נאר אז פרעה אליין וועט זיי הייסן ארויסגיין פון מצרים; די גאולה וועט פארקומען ניט אין דער צייט ווען די כוחות פון דער נאטור זיינען איינגעדרעמלט און פארבארגן, נאר דוקא אין <b>חודש האביב,</b>, אין דעם רעכטן מיטן פון דעם פרילינג חודש, ווען די נאטור אנטפלעקט אירע שטארקסטע כוחות.</p>\n<p>דערמיט ווערט אונטערשטראכן, אז עס זיינען ניטא קיין אפגעזונדערטע וועלטן: א וועלט פון נאטור און נאטור כחות און א וועלט פון \"העכער פון וועלט\", וואס אמאל באהערשט איינע די צווייטע און אמאל פארקערט; עס איז די בלויז איין און איינציקער ג-ט, וואס ער איז דער אבסאלוטער בעל-הבית איבער דער גאנצער וועלט, און פאראיינציקט אויך די גאנצע וועלט.</p>\n<p>די דאזיקע אנערקענונג איז געקומען צום העכסטן אויסדרוק בא מתן-תורה, דער קולמינאציאן פונקט פון יציאת מצרים, וועלכער האט זיך אנגעהויבן מיט: <b>אנכי ה'</b> <b>אלקיך אשר הוצאתיך מארץ מצרים מבית עבדים; לא יהי' לך אלקים אחרים</b> גו' - \"איך בין ג-ט, דיין ג-ט, וואס האט דיך ארויסגעפירט פון לאנד מצרים, פון דער היים פון פארשקלאפונג; עס זאל בא דיר ניט קיינע אפגעטער\".</p>\n<p>***</p>\n<p>פונקט ווי אין מצרים אמאל, אזוי אויך היינט זיינען פאראן אזלעכע וועלכע בויען זייער לעבן אויפ'ן פארגעטערן די אזוי גערופענע נאטור כחות מיט'ן צוגאב פון דעם כוחי ועוצם יי פון דעם מענשן. מאנכע האבן געפונען אן \"אויסוועג\", אז בע זיך אין דער היים, האט ער אן ארט פאר דעם אויבערשט'ן אויך - אבער אין געזעלשאפט איז ער \"מיט לייטן גלייך\", נהי' כגוים, ואדרבה - נאך מער גוי - ווי זיי.</p>\n<p>קומט יום טוב פסח און דערמאנט ווידער אמאל: פקוד פקדתי - איר האט קיין ברירה ניט. דיר אויבערשטער געדיינקט אייך און עס מוז זיין - <b>משכו</b> - אפווארפן די עבודה-זרה פונם לאנד, אין וואס פאר א פארם זי זאל זיך ניט אויסדריקן און טאן דעס עפענטליך, אן מורא, און מיט שטאלץ. <b>וקחו לכם -</b> נעמן זיך און אלץ וואס איר האט, אלע מעגלעכקייטן און כחות וואס איר פארמאגט - צו זיך, צו אייער אמת'ן אייביגן אידישן \"איך\",</p>\n<p>און טאן דאס אלץ בחדש האביב - ניט לאזן זיך פארטומלען פון די פארפירער אז וויבאלד אז עס איז די א בליענדע וועלט מיט דעם מענשן אינמיטן און זיין כח ועוצם ידו - איז אלה אלקיך, דאס איז דיין אפגאט און צו דעם ביזט דו פארשקלאפט און ניטא קיין ארט ר\"ל פאר דעם אויבערשטן -</p>\n<p>נאר אדרבה - בחדש האביב הוציאך ה' אלקיך ממצרים - ג-ט, וואס ער איז דיין ג-ט נעמט דיר ארויס פון פארשקלאפונג אין חדש האביב - די בליענדע וועלט מיט די וואונדער אף וואונדער וואס מען זעט אין איר בריינגען עם צו נאך קלארער דערזען דעם אמת - און דעם נוסח פון אונזערע חכמים ז\"ל - אז ה' אלקינו (איז) מלך העולם (דער קעניג פון וועלט) שלא חיסר בעולמו כלום (אז <b>ער</b> האט געמאכט אז עס זאל אין איר גארניט פעלן).</p>\n<p>***</p>\n<p>דער אויבערשטער זאל העלפן און מצליח זיין, אז פסח - זמן חירותנו זאל ברענגען יעדן איינעם און איינער בתוך כלל ישראל צו דער אמת'ער באפרייאונג פון אלע שטערונגען און באגרענצונגען און מ'זאל דינען דעם אויבערשטן בלבב שלם,</p>\n<p>און די גאולה פון דעם פרט זאל ברענגען צו דער גאולה פון כלל ישראל, די גאולה האמתית והשלימה על ידי משיח צדקנו במהרה בימינו.</p>\n<p>בברכה לחג הפסח כשר ושמח,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ח'תתקסה</b></i></h4>\n<p>נדפסה בהגדה של פסח ח\"ב ע' תרה - הוצאת תנש\"א.</p>\n<p><b>האט באשטימט: </b>ראה שמות רבה פט\"ו, יא: החדש הזה כו' כשבחר ביעקב ובניו קבע כו'. אור התורה (להצ\"צ) ע\"פ זה (ע' רסד).</p>\n<p><b>זאגט אן... שמור: </b>דברים טז, א. ולרמב\"ן (לשרש הא' דסהמ\"צ להרמב\"ם) ולבעל ההלכות - זוהי מ\"ע (לעבר שנים, או - מושמרת את החוקה). וראה סהמ\"צ סוף מ\"ע קנג: באו רמזים כו' שמור כו' הורה כו'. וביד הל' קדה\"ח בתחלתו ורפ\"ד.</p>\n<p><b>ווערט דערקלערט: </b>מכילתא לשמות יג, ד (הובא בפרש\"י שם).</p>\n<p><b>איינע פון: </b>ראה רמב\"ן בא (יב, ג). צרור המור שם (יב, א). ועיין זח\"ג (רנא, א).</p>\n<p><b>באהערשט אלע: </b>מכילתא לבשלח יד, ה: הי' פרעה שולט מסוף העולם ועד סופו. וראה זח\"ב ו, א.</p>\n<p><b>געוואלדיקער איבערגעוויכט: </b>ראה זח\"א קכה, סע\"א.</p>\n<p><b>ספעציעל... נילוס: </b>יחזקאל כט, ג.</p>\n<p><b>פריי פון רעגן: </b>ראה רש\"י ויגש מז, י. דברים יא, י.</p>\n<p><b>מענטשליכע דערפינדלעכקייט: </b>רש\"י ר\"פ מקץ.</p>\n<p><b>פון פרעה'ן: </b>שמו\"ר פ\"ח, ב. תנחומא שם.</p>\n<p><b>כוחי ועוצם ידי: </b>דברים ח, יז. וראה סמ\"ג מל\"ת סד: וארא בחלום כו' שכחת את העיקר כו' והתבוננתי כו' והנה יסוד גדול הוא כו'.</p>\n<p><b>דער נידעריקסטער: </b>ויקרא יח, ג ובתו\"כ (ובפרש\"י) שם. ובקה\"ר עה\"פ והארץ לעולם עומדת דמצרים דוגמת ערוה באדם.</p>\n<p><b>שטארקסטן אויסדרוק: </b>רמב\"ן וצרור המור שם.</p>\n<p><b>א טייל אידן: </b>שמו\"ר פי\"ד, ג. וראה תניא פל\"א.</p>\n<p><b>קיין איינציגער שקלאף: </b>מכילתא יתרו יח, יא.</p>\n<p><b>איין באדינג - ציט זיך: </b>שמו\"ר פט\"ז, ב: כל זמן כו' משכו כו' שבכך כו'.</p>\n<p><b>וקחו לכם: </b>למשפחותיכם (דוקא), וכהודעת משה בבנינו ובבנותינו - כל הארבעה בנים (ובנות), מן החכם ועד השאינו יודע לשאול.</p>\n<p><b>אין דער עפנטליכקייט: </b>ראה שו\"ע רבנו הזקן ר\"ס תל.</p>\n<p><b>דער קולמינאציאן פונקט: </b>כמש\"נ בהוציאך את העם ממצרים תעבדון את ה' (שמות ג, יב). וראה ז\"ח ר\"פ יתרו: <b>בכל</b> יומא אפיק כו'. וראה תניא פל\"א שם.</p>\n<p><b>נהי' כגוים: </b>יחזקאל כ, לב.</p>\n<p><b>קיין ברירה ניט: </b>יחזקאל שם. תנחומא נצבים ג. נתבאר בקונטרס ומעין מי\"א, פ\"ג.</p>\n<p><b>לכם... אידישן \"איך\": </b>ראה שמו\"ר פט\"ו, כג: לכם הה\"ד יהיו לך לבדך ואין לזרים אתך.</p>\n<p><b>אדרבא - בחדש האביב: </b>להעיר מלקו\"ת במדבר (ג, א). סד\"ה החדש הזה - לכ\"ק מו\"ח אדמו\"ר - בס' המאמרים ה'ש\"ת.</p>\n<p><b>הוציאך... ממצרים: </b>לילה. וכן גם עתה אין להתרשם מזה שלאחרים לילה ואין רואים את האמת, כי הנה בחושך יכסה ארץ וערפל לאומים ועליך יזרח ה' וכבודו עליך יראה (ישעי' ס, ב).</p>\n<p><b>אין חדש האביב... אין דעם נוסח: </b>ברכות מג, ב. והנה לכמה אחרונים (או\"ח סרכ\"ו) ניסן לאו דוקא, אבל י\"א דדוקא הוא (שד\"ח אסיפת דינים מע' ברכות רס\"ב. וש\"נ). והנה אדמו\"ר הזקן בלוח ברכות הנהנין (הראשון) כ' דאחר ל' יברך בלא שם ומלכות (מוכח דניסן לאו דוקא), אבל בסדר ברה\"נ (שבסידורו פי\"ג סי\"ד) השמיט זה. ואף שי\"ל בדוחק דטעמו מפני דס\"ל דאין לברך כלל אלא פעם אחת (ועדיין יקשה למה לא ביאר דברי השו\"ע \"בימי ניסן\" דהיינו לאו דוקא - כמו שהוסיף ביאור בכמה דינים שבברה\"נ), י\"ל - דהשמיט מפני דבמשנה האחרונה ס\"ל ד\"בימי ניסן\" כפשוטו - בדוקא, וא\"כ א\"א \"לאחר ל'\". ואכמ\"ל.</p>"],[1200970296,"ח'תתקסו\n\n<p>ב\"ה, י\"א ניסן ה'תשכ\"ה</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתביו ות\"ח ת\"ח על הברכות...</p>\n<p>...לקו\"ת כדאי ללמוד על הסדר שאז תקוה שסו\"ס וועט מען אניאגן, משא\"כ \"חוב ישן\"...</p>\n<h4><i><b>ח'תתקסו</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ד ע' 365.</p>\n<p><b>לקו\"ת:</b> בשנת תשכ\"ה הורה כ\"ק אדמו\"ר ללמוד לקו\"ת על הפרשה בכל שבוע, ושאל א' כשאינו מספיק ללמוד הכל בשבוע א', האם ילמד בשבוע ב' השייך לאותו שבוע וישלים החסר בזמן הפנוי, או שימשיך ללמוד על הסדר. וראה גם לקמן אגרת ט'ז.</p>"],[1200970297,"ח'תתקסז\n\n<p>ב\"ה, י\"ב ניסן ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>לכבוד מר שלום שי' לוין</p>\n<p>שלום וברכה!</p>\n<p>זה עתה נתקבל המברק שלו, ותשואות חן על איחוליו וברכותיו, וכל המברך מתברך כהנה וכהנה.</p>\n<p>כיון שחזקה שהדואר עושה שליחותו, הרי בטח קבל מכתבי הקודם, והעתק מכתבי, אף שלא אישר הקבלה. ולא נוגע האישור כמובן, אלא תקותי שהתבונן בתוכן המכתב וגם תקותי שמסכים למהלך המחשבה שלי, ובמילא גם מתבטא בפעולות מתאימות.</p>\n<p>ואת\"ל זהו גם כן מתוכן ימים אלו, שבליל התקדש חג הפסח מתחילים בכל בתי בני ישראל עם הסדר, שכוונתו כמו שמודגש בתורה שבכתב ושבעל פה ובכ\"מ הוא והגדת לבנך, וכביאור חכמינו ז\"ל המכוון הוא לאו דוקא לבן חכם אלא גם לשאר הסוגים, והאריכות לכ' אך למותר.</p>\n<p>ולקראת חג הפסח, זמן חירותנו, הבא עלינו ועל כל ישראל לטובה ולברכה, הנני שולח לכ' ולכל הנלוים אליו ברכת חג הפסח כשר ושמח, וחירות אמתית מכל ענינים המבלבלים מנפש ועד בשר, ולהמשיך משמחה וחירות זו בכל השנה.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתקסז</b></i></h4>\n<p><b>מר שלום שי' לוין:</b> אגרות נוספות אליו - לעיל ח'תרפא, ובהנסמן בהערות שם.</p>"],[1200970298,"ח'תתקסח\n\n<p>ב\"ה, י\"ג ניסן ה'תשכ\"ה</p><p>ברוקלין.</p><p>הנהלת ישיבת תומכי תמימים אשר בלוד<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>מועתק בזה נוסח המברק שהואיל כ\"ק אדמו\"ר שליט\"א להבריק להם היום:</p>\n<p>שבת וחג הפסח כשר ושמח ועונג וחירות אמתי ובפרט שהשנה שלימה ותמימה.</p>\n<p>/<b>מקום החתימה</b>/</p>\n<p>בודאי כדרישת הרח\"ש ז\"ל מאז וכהוראתי אשורי מאז מנהלים סניפם אחי תמימים דראשון לציון בלי הפסק וכל אנ\"ש מסייעים בידם.</p>\n<p>בכבוד ובברכת חג כשר ושמח.</p>\n<p>ש.מ. סימפסון</p>\n<p>מזכיר</p>\n<p>נ.ב. בטח יתענינו באופן המתאים ע\"ד העזבון של הנ\"ל, בהנוגע להכתבים, ספרים (הן בנגלה והן בדא\"ח) וכיו\"ב על מנת להעבירם לספרית כ\"ק אדמו\"ר שליט\"א, ות\"ח מראש על הודעתם מהנעשה בזה.</p>\n<h4><i><b>ח'תתקסח</b></i></h4>\n<p><b>הרח\"ש:</b> ברוק.</p>\n<p><b>וכהוראתי אישורי מאז:</b> לעיל אגרת ח'תתקמט.</p>"],[1200970299,"ח'תתקסט\n\n<p><i>[כ\"ד ניסן תשכ\"ה]</i></p>\n<p>עס איז צו מיר \"צופעליק\" געקומען צו דער האנט אייער ארטיקל אין דעם פסח-נומער פון \"דזשואיש אדוואקאט\" - \"וועגן אידישע אטעאיסטן\". \"צופעליק\", וייל אייער ארטיקל דערשיינט אויף דער אנדער זייט פון מיינעם א בריוו אויף דער טעמע פון \"דיאלאג\". ס'איז אבער איבעריק צו זאגן, אז בא אונז אידן איז דאך בכלל ניטא דער ענין פון צופעליקייט, ווייל אלץ איז בהשגחה פרטית.</p>\n<p>אזוי ווי א איד זוכט כסדר רמזים, געפן איך אין דער דערמאנטער</p>\n<p>צוזאמענטרעפעניש פון אונזערע ארטיקלען א מעגליכקייט אויסצונוצן די געלעגנהייט און שרייבן אייך עטלעכע שורות, נאך דעם צו-לאנגן איבעררייס אין אונזער קארעספאנדענץ, אדער א פאר ווערטער בא א פארבריינגען.</p>\n<p>אגב, האט מען מיר איבערגעגעבן, אז איר זייט געווען אנוועזנד עטלעכע מאל בא \"פארברענגענס\", אבער צוליב אירגענד וועלכער סיבה האט איר ניט געוועלט צוגיין נעענטער.</p>\n<p>אייער ארטיקל האט מיר, נאטירלעך, \"אינטריגרט\", און איך האב אים געלייענט מיט אינטערעס.</p>\n<p>איר שרייבט, אז לכתחילה האט איר גערעכנט אז דער ארויסטריט פון דע[ם] טרויעריק-בארימטן (אדער טראגי-קאמישן) ראביי קעגן דעם רבונו של עולם איז געווען אן אויסדרוק פון פראטעסט (קעגן דער גערעכטלאזיקייט פון דער וועלט). איך נעם אן, אז דאס איז בלויז א מליצה, ווארום זיכער ווייסט איר, אז איינער וואס איז דערצויגן געווארן אין א סעמינאר פון א באוועגונג, וואס איר גאנצע פילאזאפיע איז דער היפך פון קעמפן און רעבעלירן, נאר איז אויסן בלויז צו מאכן זיך לייכטער או באקוועמער דאס לעבן - איז ניט שייך צו אזא מדרגה.</p>\n<p>איך בין, זעלבסטפארשטענדליך, מסכים מיט אייך, אז די טענה פון \"השופט כל הארץ לא יעשה משפט!\" קען זיין אויטענטיש און האבן די געהעריקע שטארקייט - נאר ווען זי רייסט זיך ארויס פון אן אנגעווייטיקטער הארץ פון א טיפן מאמין. דעריבער געפינען ציר טאקע, אז דער ערשטער וועלכער האט זיך אויסגעדריקט די טענה איז געווען אברהם אבינו, דער גרויסער מאמין און פאטער פון די מאמינים בני מאמינים.</p>\n<p>אויך דערציילן אונזערע חכמים ז\"ל, אז דער ערשטער וועלכער האט אויפגעהויבן די פראגע פון \"צדיק ורע לו, רשע וטוב לו\" איז געווען ניט קיין אנדערער ווי משה רבנו, דער וועלכער האט ערקלערט צו די אידן, און צו דער גאנצער וועלט, די איידיע פון \"אנכי ה' אלקיך\" און \"לא יהי' לך אלקים אחרים\", וואס \"אלקים אחרים\" איז כולל אויך דעם מענטשלעכן שכל און פארשטאנד ווען מען מאכט זיי אן אפגאט און פוסק אחרון.</p>\n<p>דעריבער האט מיר געוואונדערט, וואס איר האט ניט פארגעזעצט דעם</p>\n<p>געדאנקען-גאנג און ניט ארויסגעבראכט דעם אויספיר. ווארום, ווי איר ווייסט, איז דער ענטפער אויף משה רבינו'ס טענה - בשעת, לויט דער דערציילונג פון חכמינו ז\"ל, מען האט אים געוויזן אז מען האט געריסן רבי עקיבא'ס פלייש אייזערנע קאמען א.ז.וו. און משה רבינו האט אויפגעשטורמט \"זו תורה וזו שכרה!\" - (איז דער ענטפער) געווען: \"שתוק, כך עלה במחשבה!\".</p>\n<p>לאמיר געדענקען, אז משה רבנו'ס טענה איז דאך ניט געווען בלויז אין ווערטער, נאר בעיקר אין געדאנק. דעריבער איז דער ענטפער \"שתוק\" ניט געווען אן אנזאג ניט צו ריידן וועגן דעם, נאר אויך ניט צולאזן דעם געדאנק וועגן דעם.</p>\n<p>און די איינציקע דערקלערונג איז געווען - \"כך עלה במחשבה (העליונה)\", וואס איז אייגנטלעך גאר ניט קיין ערקלערונג. פונדעסטוועגן האט עס ניט אפגעשוואכט די אמונה בא משה רבנו און בא אלע אנדערע אויטענטישע פרעגער און מאנער. אדרבה, דאס האט נאך פארשטארקט זייער אמונה, ווי מיר געפינען דאס בפירוש בא אויב'ן; אזוי אויך בא אברהם אבינו, וואס איז ניט נאר געבליבן פעסט בא זיין אמונה, נאר האט אויך געקענט אויסשטיין אלע נסיונות; און אזוי אויך די אנדערע \"רעבעלען\" זיינען געבליבן טיפע מאמינים ביז צום לעצטן טאג פון זייער לעבן.</p>\n<p>איך גלויב, אז איר וועט מיט מיר מסכים זיין אז עס [איז] ניט געווען סתם א צופאל דאס וואס די אלע אויטענטישע פרעגער זיינען געבליבן בא זייער אמונה; נאר אז עס האט גאר אנדערש ניט געקענט זיין. ווארום, אויב נאר מ'מיינט די קשי' מיט אן אמת, און זי איז דאך פארשטענדלעך, אז אזא טיפער געפיל קען קומען נאר פון דער איבערצייגונג, אז דער אמת'ער צדק איז דער צדק וואס שטאמט פון אן <b>איבער</b> מענטשלעכן מקור, דאס הייסט, וואס איז העכער סיי פון דעם מענטשלעכן שכל און סיי פונם מענטשלעכן געפיל. דערפאר רירט די קשיא אן ניט נאר רגש און שכל, נאר אויך זיין פנימיות און עצם מציאות.</p>\n<p>אבער נאך דעם ערשטן שטורמישן ארויסטריט, מוז ער זיך כאפן אז דער גאנצער צוגאנג פון שטעלן די קשיא און פון וועלן פארשטיין מיטן שכל דאס וואס איז העכער פון שכל, האט קיין ארט ניט. דעריבער מוז ער - נאך א דערשיטערנדען אמפערן זיך און דורכווייטיקן - סוף כל סוף קומען צום אויספיר - עם כל זה אני מאמין!\" אדרבא - נאך שטארקער.</p>\n<p>***</p>\n<p>דאס אויבנגעזאגטע באציט זיך אויף אייער ארטיקל. עס איז אבער פאראן נאך א נקודה אין דעם, א נקודה וואס איז נוגע דער גאנצער פראבלעם, און עס איז א פלא וואס מ'פארקוקט זי. איך מיין פאלגנדעס:</p>\n<p>נאך אלעמען, איז דאך דער גאנצער ענין פון דעם דערמאנטן \"קאנפליקט\" מיט אמונה ניט קיין נייע זאך, וואס איז אויפגעשוואומען אין אונזער דור. אונזער פאלק האט שוין געהאט אויסצושטיין שחיטות און שמדות ר\"ל אין פריערדיקע דורות. די קרייצצוגן, צ.ב., זיינען אין זייער פארנעם \"פראצענטועל\" און אין אומפאסונג געווען אפשר ניט לייכטער ווי די היטלעריסטישע, מיט דעם אונטערשייד דערצו, וואס דאן איז גארניט געווען קיין שטראל פון האפנונג, אז די לאגע זאל זיך ענדערן; די שחיטות זיינען אנגעפירט געווארן אין נאמען פון אותו האיש און די טריניטי, וואס לויט דער אידישער אויסטייטשונג איז דאס אמת'ע עבודה-זרה, וואס אידן האבן בשום אופן ניט געקענט אננעמען; נאכדעם ווי די טערקן זיינען באזיגט געווארן דורך די קרייצטרעגער, איז ניט געווען קיין אויסזיכט אויף קיינע \"פארבינדעטע\". בשעת אין היטלער'ס י\"ש צייטן - זיינען די שחיטות פארגעקומען \"סתם\" פון ווילדקייט און חי'שער נאטור פונם מענטשן, און מען האט געקענט האפן, אז אפשר וועט די וועלט פארט אויפגעטרייסלט ווערן, און דער עיקר, אז די פארבינדעטע וועלן סוף כל סוף זיגן און מאכן א סוף צו היטלערן ימח שמו.</p>\n<p>מיט אנדערע ווערטער: דער איד דער מאמין ביז 1940, וואס איז געבארן געווארן אינם 20'טן יארהונדערט און האט געוואוסט וועגן דער אידישער געשיכטע און די איבערלעבענישן פון אונזער פאלק, מיט אלע גזירות און שמדות ר\"ל, פון די קרייצטרעגער און פריער, ביז נבוכדנצר מלך בבל וכו', האט נאר געקענט פרעגן, פארוואס ער און זיין משפחה זיינען פארמישט אין דעם היטלער פלאן; אבער דער עצם ענין פון שטענדיקן עומדים עלינו לכלותנו איז טיילווייז גיט זיך דאס זיי איין - איז בא אים <b>קיין נייעס</b> ניט געווען; במילא האט היטלער ניט געקענט אנרירן זיין אמונה אין דעם רבונו של עולם. בלויז דער וואס זיין אמונה איז אויך פריער געווען א שוואכע און ער האט געזוכט א \"באגרנדונג\" פאר זיין פארלייקענען דעם רבונו של עולם, האט געפונען אזא באגרידונג, כביכול, אין דער היטלער געשיכטע.</p>\n<p>די היטלער געשיכטע האט יא געבראכט א חידוש, אבער אין אן אנדער</p>\n<p>ריכטונג - אין דעם געביט פון מענטשלעכער אנטוויקלונג, קולטור און ציוויליזאציע.</p>\n<p>פיל האבן געגלויבט בפרט אין די רייען פון די אזוי-גערופענע משכילים - אז אין 20'טן יארהונדערט האבנדיק דערגרייכט אזא ציוויליזאציע, מיט פארשידענע \"הויכע\" פילאזאפישע סיסטעמען, מיט א פארשפרייטע הויכע בילדונג, מיט אזא שול-וועזן און אזויפיל אוניווערזיטעטן, מיט אזא הויכע עטיק און שיינע מאנירען, קען ניט פאסירן דאס וואס עס האט פאסירט אין די \"פינסטערע צייטן פון מיטלאלטער\". די דאזיקע שטימונג האט זיך אויסגעדריקט אין דער ליטעראטור, אין דער פרעסע, און אויך אין מינדלעכע געשפרעכן פון פירנדע פערזענלעכקייטן און דענקער. דערמיט האט מען געוועלט אפשלאגן דעם \"פארעלטערטן\" צוגאנג פון תנ\"ך, אז \"חסד לאומים חטאת\", און רשב\"י'ס באהויפטונג אז \" <b>הלכה</b> ידוע שעשו שונא ליעקב\". פלוצלונג איז געקומען דער גרויסער קראך, און די גאנצע קולטור און ציוויליזאציע פון דעם 20'טן יארהונדערט איז צוזאמענגעבראכן. עס האט זין ארויסגעוויזן, אז עס איז גאר קיין סתירה ניט וואס פון איין זייט איז ער א פילאזאף, אדער א פאעט, מיט שיינע מאנירען, און נעמט אויס אין א הויכער געזעלשאפט אין א סאלאן אין בערלין, און דער זעלבער מענטש קומט דאן אין טרעבלינקא אד\"ג און טוט אפ די אלע זאכן וועלכע זיינען דארט אפגעטאן געווארן. און דא האנדלט זיך ניט וועגן אויסנאמספאלן, \"מאנסטערס\" און פארזעענישן בצורת אדם, נאר וועגן א 100 מיליאן מענטשן, א גאנץ פאלק. און דערביי - ציטירנדיק די קעפלעך פון אייערע ארטיקלען - \"די וועלט האט געשוויגן\". דערצו קען מען נאך צוגעבן אן אונטערקעפל, אז א גאר חשובע טייל פון דער וועלט איז געווען צופרידן וואס \"די זאך\" ווערט אפגעטאן (און)אדער) חאטש ס'ווערט אפגעטאן דורך אנדערע).</p>\n<p>אויב די היטלער געשיכטע האט ערגעץ געדארפט אנרירן דעם גלויבן, האט זי געדארפט און ניט נאר אנרירן נאר אויך קלאר באווייזן, אז מען קען זיך ניט פארלאזן אויף דעם מענטשלעכן געפיל פון צדק און יושר, ווען אפילו דער מענטש האט הויכע בילדונג און אן אוניווערזיטעט דיפלאמא, און איז אויך דער זון פון א דיפלאמירטן אקאדעמיקער.</p>\n<p>צום באדויערן, און צו שאנדע, האט מען מורא ארויסצוקומען מיט אט דעם באשיינפערלעכן אויספיר, שוין אפגערעדט פון די לאגישע קאנסעקווענצן צו וועלכע דער אויספיר דארף פירן בנוגע דעם טאג-טעגלעכן לעבן. די דאזיקע אומפארציילעכע צוריקגעהאלטנקייט געפינט מען ליידער אויך בא פרומע ווארטזאגער, און אפילו בא אזעלכע וואס האבן מיט די אייגענע אויגן געזען וואס מענטשן קענען אפטאן אויב מ'לאזט זיי איבער אין זייער אייגענעם רשות. און דאס איז, ווי געזאגט אין אנהויב בריוו, ווייל מ'זוכט שיך לייכטער און באקוועמער צו מאכן דאס לעבן, און עס זאל זיך שלאפן בעסער. ווארום ס'איז לייכטער מיטצוגיין מיט דער וועלט, כאטש ס'איז די זעלבע וועלט וואס האט געשוויגן, און אין א גרויסען טייל געווען אויך צופרידען אין הארצן.</p>\n<p>***</p>\n<p>און איצט ערלויב איך מיר א פערזענלעכע באמערקונג, וואס איז פארבונדן מיט אונזער שמועס בשעת מיר האבן זיך געטראפן בא מיר אין צימער. אייער סעריע ארטיקלען \"און די וועלט האט געשוויגן\" האט אין מיר נאכאמאל דערוועקט דעם געדאנק, ווא איך וויל דא אויסדריקן, בא דער געלעגנהייט:</p>\n<p>צו געדענקען און ניט צו פארגעסן, ווי די תורה זאגט: זכור את אשר עשה לך עמלק - איז זעלבסטפארשטענדלעך א פאזיטיווע זאך; אין דעם לשון פון אונזערע חכמים ז\"ל איז דאס א מצות-עשה. בפרט וען מען זעט די וואקסענדע טענדענץ און די באמיאונג צו פארגעסן און מאכן פארגעסן.</p>\n<p>אבער נאך דעם אלעמען, איז דאס געדענקען - בלויז איין טייל פון דער אויפגאבע וועלכע ליגט אויף אונז. די אנדערע, און אפשר נאך וויכטיקערע טייל, איז צו ארבעטן און ווירקן <b>אקטיוו</b> קעגן דער אזוי0גערופענער \"פיינאל סאלושאן\" ווא היטלער, פונקט ווי המן האבן געהאט אין זינען.</p>\n<p>די קעגנווירקונג דארף זיך אויסדריקן דורך מעשים אין דער ריכטונג פון \"כן ירבה וכן יפרוץ\". צו דערגרייכן דעם ציל וועט ניט העלפן דאס וואס מען וועט זיך שווער מאכן אויפן הארצן דורך כסדר דערמאנען זיך און ניט פארגעסן, ווי וויכטיק דאס איז. מ'מוז פארגרעסערן און פארשפרייטן די דערמוטיקונג אויפצובויען דעם אידישן פאלק, אלס אידיש פאלק, און פשוט אין דעם געביט פון ויפרו וירבו ויעצמו במאד מאד - פונקט פארקערט פון דעם געפלאנטן \"פיינאל סאלושאן\".</p>\n<p>ווי אין אלע זאכן, אזוי אויך אין דעם, איז נויטיק - אין צוגאב צו מינדלעכער דערמוטיקונג - צו ווייזן א לעבעדיקן ביישפיל. בפרט איינער וואס האט אליין איבערגעלעבט די אלע זאכן, דארף זיכער ווייזן, אז ניט נאר האט היטלר י\"ש ניט אויסגעפירט, נאר אויף צו להכעיס אים און זיינע ארויסהעלפער וועט ער דוקא אויפשטעלן א גרויסע פאמיליע מיט זין און טעכטער און אייניקלעך.</p>\n<p>איך ערלויב מיר צו זאגן מיט דער גאנצער שטארקייט, אז ניט קוקנדיק ווי וויכטיק עס איז צו דערציילן דעם איצטיקן דור וואס עס האט פאסירט מיט אונז, און ווי שווער עס זאל ניט זיין צו באפרייען זיך פון יענע זכרונות און איבערלעבונגען, איז אבער, לויט מיין אויפפאסונג, די ערשטע אויפגאבע מקיים צו זיין \"בעל כרחך אתה חי\", מיט דעם טראפ אויף <b>אתה חי</b>, ד.ה. עס זאל זיך אנזען די לעבעדיקייט. מיט אנדערע ווערטער: איר דארפט מאכן יעדע אנשטרענגונג ארויסצורייסן זיך אין דעם מאמענט פון יענע איבערלעבונגען און אריינצוגיין אין א סדר חיים, א פארהייראטן לעבן, אויפצושטעלן א אידישע היים און א אידישע פאמיליע. דאס וועט <b>זיכער</b> בייטראגן צו היטלער'ס מפלה, אז ער האט ניט אויסגעפירט צו מאכן ווייניקער מיט א וויזשניצער חסיד; אדרבה, איר וועט אויפהאגעווען קינדער און אייניקלעך, וויזשניצער חסידים עד סוף כל הדורות. איך מיין דא ניט סתם א גלייכווערטל, כאטש איך בין ניט מדייק און באשטיי א וויזשניצער אדער א ליובאוויטשער, אדער סתם א איד שומר תורה ומצוה. אבער אויב דאס קען זיין אין דעם אופן, איז געוויס גוט. און אזוי ווי איר האט אין אייער לעבן דורכגעמאכט שווערערע זאכן, און איר זייט איצט אין אמעריקע, איז אויב איר וועט וועלן מיט אן אמת, וועט איר דאס אויך דערגרייכן. והשם יתברך זאל אייך מצליח זיין.</p>\n<p>צו א ליינגער בריף? אויב אבער אירר וועט נאך שבועות חתונה האבן כדת משה וישראל במזל טוב - איז כדאי מיין שרייבן און אויך די טרחא פון אייער לייענען.</p>\n<h4><i><b>ח'תתקסט</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ג ע' 255.</p>\n<p>האגרת היא למר אלי' שי' וויזל.</p>\n<p><b>מאמינים בני מאמינים:</b> שבת צז, א.</p>\n<p><b>דערציילן אונזערע חכמים:</b> ברכות ז, א.</p>\n<p><b>דערציילונג פון חכמינו:</b> מנחות כט, ב.</p>\n<p><b>די... חידוש:</b> ראה גם לעיל אגרת ח'תתקמ, ובהנסמן בהערות שם.</p>\n<p><b>הלכה:</b> ספרי הובא בפרש\"י וישלח לג, ד.</p>\n<p><b>דעם לשון... חכמים:</b> ראה אנציקלופדי' תלמודית ערך זכירת מעשה עמלק (ע' ריט).</p>\n<p>וש\"נ.</p>\n<p><b>בעל... חי:</b> אבות ספ\"ד.</p>"],[1200970300,"ח'תתקע\n\n<p>ב\"ה, כ\"ה ניסן תשכ\"ה</p><p>ברוקלין.</p><p>במענה למכתבו מכ' ניסן, בו כותב אודות בתו תחי' וכו'.</p>\n<p>ואין ניכר במכתבו האם ניצל ככל האפשרי השפעת אחרים עלי' שבודאי יש למצוא כאלה בבית הספר בם למדה ובודאי גם בין פקידי הצבא, והרי רואים כעל כל צעד ושעל, שלפעמים קרובות השפעה על ילדים הבאה מצד ידידים ובפרט אם הם בני גילם לערך, מצליחה יותר מאשר השפעה ישירה של ההורים, ואף שלכאורה סברא פשוטה היא, מצאתי לחובתי להזכיר גם את זה.</p>\n<p>ב) כיון שכל בני המשפחה קשורים זה בזה לא רק בגשמיות אלא גם ברוחניות, מובן ופשוט שהוספה ביראת שמים מכל אחד מבני המשפחה, מוסיפה בכגון זה גם בשאר בני המשפחה ובפרט הוספה של הורים בנוגע לילידיהם וככל שתגדל הוספת ההורים תגדל גם התוצאה.</p>\n<p>ג) ועוד להעיר שלפעמים קורה כהנ\"ל ע\"י שבעת שנתעברה עם הנ\"ל הי' זה באופן שלא היו נזהרים ככל הדרוש בשמירת חוקי ודיני טהרת המשפחה (נדה, הפסק טהרה, טבילה במקוה כשרה וכו') אם מפני חסרון ידיעה או מסיבות אחרות, וכיון שתשובה מועילה במדה חשובה גם בנוגע לעבר, יש להשתדל בענין שמירת ענינים אלו הנ\"ל בנוגע לעצמם ובנוגע להזולת, וגם בזה על המרבה ה\"ז משובח.</p>\n<p>ומהנכון אשר יבדקו את המזוזות בדירתם שתהיינה כולן כשרות כדין וכן את התפילין שלו - באם לא נעשה כזה במשך שנים עשר חדש האחרונים - ובכל יום חול קודם תפלת הנחת התפילין יפריש פרוטות אחדות לצדקה, וזוגתו תחי' תשמור על מנהגן הטוב של בנות ישראל הכשרות, להפריש לצדקה קודם הדלקת הנרות בכל ערב שבת וערב יום טוב.</p>\n<p>בעת רצון יזכירום - כשיודיע שמותיהם (בצירוף שם האם) - על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע למילוי משאלות לבבם לטובה.</p>\n<p>שתסע בתו תי' למדינה בה יהודים מתי מספר (בכמות וגם באיכות) - לא נראה לי כלל.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ח'תתקע</b></i></h4>\n<p><b>אודות בתו תחי':</b> שמתידדת עם נכרי.</p>"],[1200970301,"ח'תתקעא\n\n<p><i>[כ\"ז ניסן תשכ\"ה]</i></p>\n<p>...כנראה קבל ידיעות בלתי נכונות, כי בשעה שדברתי עם הרב מנחם הכהן שי' בקשר עם הספרי תורות ששולחים לאהקת\"ו שהי' בנוכחות מר ישעי', הדגשתי בפירוש שאיני רוצה לחלק בין מושב למושב ובין כפר לכפר, ורק שיהי' זה במקום שישתמשו שם בספר התורה, ושמדגיש אני בפירוש שאיני נותן למוסד מסוים או כפר מסוים, שלא יהי' מקום למצוא בדברי הפלי' באיזה אופן שיהי', שהוא היפך כוונתי. ובקשתי שכשיתנו למקום מסוים יודגש גם אז שלא שאני שלחתי הס\"ת במיוחד לאותו מקום, כי אין זה מעניני. ואפשר לומר רק שהס\"ת נשלחה ממרכז דליובאוויטש כאן, אבל לא שהוחלט כאן מראש לאיזה מקום ומוסד לשלוח שממילא שולל מוסדות או מקומות אחרים.. על פי מכתבו הראשון מוצא אני לא למותר להוסיף עוד ענין שגם הוא מיוסד על שיחותינו כשהי' כאן, ששנינו היינו תמימי דיעה שאין מקום לנצל עניני תורה ודת לרווחים מפלגתיים שאין להם שייכות לדת. ועל דרך זה גם בנידון האמור, שבודאי אין לנצל ס\"ת הנשלחת מכאן או ס\"ת איזה שתהי' לענינים כהאמורים...</p>\n<h4><i><b>ח'תתקעא</b></i></h4>\n<p>האגרת היא למר יוסף דקל. אגרות נוספות אליו - לעיל ח'תרצט, ובהנסמן בהערות שם.</p>"],[1200970302,"ח'תתקעב\n\n<p>ב\"ה, תפארת שבתפארת, ה'תשכ\"ה</p><p>ברוקלין, נ.י.</p><p>כבוד כל המשתתפים<br>\nבהתועדות-חברים-הכללית למלאות<br>\nעשר שנים להתייסדות צעירי אגודת חב\"ד<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>ידועה שיחת כ\"ק מו\"ח אדמו\"ר, אשר</p>\n<p>עס איז א טעות וואס מען מיינט אז טאן א טובה כלל ישראל איז שייך נאר צו רביים, צו גדולים. יעדער איד קען טאן א טובה מיט זיין תפלה ובקשה.</p>\n<p>השם יתברך יראה בענינו וישמע שועתינו ויקבל תפלתינו ויביא ישועה כללית לכלל ישראל ברוחניות ובגשמיות.</p>\n<p>עס איז דאך איצט א הנהגה למעלה מהטבע, דאס זעט מען דאך - איז די צייט וואס החלש יאמר גבור אני.</p>\n<p>עס איז איצט אזוי ווי מען גייט עולה זיין בהר, א הר גבוה, ביז מען קומט נאענט אין די ד' אמות פון ראש ההר, איז דאמאלט דארף מען זיך מתגבר זיין מיט אלע כחות אויף צוקומען צום ראש ההר, עס איז דאך געבליבען מער ניט ווי ד' אמות. און דאן איז טאייער יעדער גרעזעלע וואס ער זעט, יעדער צווייגעלע, יעדער שטיינדעלע וואס מען קען זיך אן דעם אנהאלטען, ביד, ברגל או בגופו, און יעמאלט איז מוכרח אור להאיר, און אז מען איז מאיר - איר זייער טאייער דער אור וואס מען זעט אן וואס אנהאלטן זיך.</p>\n<p>דער משל פון עולה בהר - שטייט אין חסידות משני בני אדם אחד עומד למעלה על ההר ואחד למטה שהעומד למטה צריך לעלייתו להיות בעל כח, ולידע הדרכים, והלבושים יהיו בטוב שלא יסתבך על ידם, אבער אז דאס איז ניטא - אדן מוז מען גיין מיט מסירת נפש. און דאמאלסט איז טאייער יעדער זאך אן וואס אנהאלטן זיך און עס איז טאייער דער אור המאיר.</p>\n<p>עס איז דער זמן אז מ'איז לעבן ראש ההר. באמת זעט מען דאך אז משיח איז שוין קרוב, ער איז אהינטער'ן וואנט און דער וואס האט א גוטן חוש השמיעה און א חוש הראי' איז שומע קולו ורואה, מען דארף מער ניט ווי צוגיין דעם שטיקל וואס פעלט נאך, דארף מען יעדער דבר טוב מייקר זיין ביותר, און מען דארף א אור להאיר, וואס אור להאיר איז תורה און הרבצת התורה. אליין לערנען און מרביץ זיין תורה.</p>\n<p>קודם אור היום איז זיך מתגבר דער שלאף - דארף מען זיך מתגבר זיין ניט פארשלאפן די צייט און דאמאלס וועט מען אויך זיין א כלי אויף מקבל זיין אור היום.</p>\n<p>דאס איז מחוייב יעדער איד וויסן און אויך אז ער באגעגענט א אידן דארף ער אים זאגן: הער ברודער, זאלסט ניט פארשלאפן פאר דעם אור היום.</p>\n<p>***</p>\n<p>ויהי רצון אשר במלאות עשר שנים להתייסדות צעירי אגו\"ח, שלימות (המספר ו) הענין, יתעוררו בכאו\"א ובכללות כולם כל עשר הכוחות פנימים לפעול פעולתם - לטובתם האמיתית של עצמו ושל הזולת - פעולה בפנימיות ובשלימות (והרי השנה תמימה ושלימה),</p>\n<p>ע\"י העבודה בהכחות מקיפים - האמונה (ובפרט כשהיא בתוקף ההתגלות, וכמו שהי' ביצי\"מ) קבעומ\"ש וכו' -</p>\n<p>שאז הכחות פנימים ופעולתם נצבים וקיימים ומאירים.</p>\n<p>בברכת הצלחה בכל האמור ולבשו\"ט בכהנ\"ל,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתקעב</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 435.</p>\n<p><b>נשא תרע\"ג:</b> סה\"מ תרע\"ב-תרע\"ו ע' רס.</p>\n<p><b>תפארת שבתפארת: </b>ראה ס' התולדות - אדמו\"ר מהר\"ש ע' 7 -6. המשך מים רבים - תרל\"ו פק\"ד ואילך.</p>\n<p><b>ידועה שיחת: </b>י\"ט כסלו תרצ\"ט. הועתקה (מרשימת א' השומעים) בקיצור לשון, רק בהנוגע להנ\"ל.</p>\n<p><b>שיחת... אשר עס: </b>אי ברור עד כמה גם התיבות מדויקות, כיון שההנחה-רשימה לא הוגהה.</p>\n<p><b>תפלה ובקשה: </b>ראה תו\"א בהוספות (קג, א). אוה\"ת בראשית [כרך א] בהשמטות.</p>\n<p><b>החלש יאמר: </b>יואל ד, י. והזמן הוא: בעת ההיא אשר אשיב את שבות יהודה וירושלים (שם ד, א).</p>\n<p><b>ד' אמות: </b>להעיר שהן כרשותו של אדם (המאור לשבת צו, ב) ומקומו (עירובין מח, א).</p>\n<p>וראה תו\"ח לשמות סד\"ה ועשית שנים כרובים (תסג, א-ב) לאדהאמ\"צ.</p>\n<p><b>אין חסידות: </b>ד\"ה אריב\"ל כו' ש\"י עולמות, צ\"ח. ובכ\"מ.</p>\n<p><b>בעל כח, ולידע הדרכים, והלבושים יהיו: </b>חזק בנשמתו (באהוי\"ר - גדפין שבהם עולה) ובגופו (בירור וזיכוך הנה\"ב), ולידע דרכי התומ\"צ ודרכי העבודה, ולבושי מחדו\"מ יהיו בטוב (נשא תרע\"ג. וראה ג\"כ וישב, תרע\"ה).</p>\n<p><b>אהינטער'ן וואנט: </b>שה\"ש ב, ט (ומסיים: משגיח גו' ענה גו'. וי\"ל שזהו המשך השיחה: שומע קולו ורואה). וראה זח\"ג קיד, ב. ובאוה\"ת שם: אחר כתלנו כו' אילו ניתן רשות לראות כו'.</p>\n<p><b>קודם אור היום: </b>להעיר מברכות סב, ריש ע\"ב.</p>\n<p><b>שלימות (המספר ו)הענין: </b>ראה פרדס שער ב.</p>\n<p><b>עשר הכוחות: </b>תניא פ\"ג. וראה לקו\"ת ויקרא (ד, ב).</p>\n<p><b>השנה תמימה: </b>ראה ערכין לא, א. צ\"צ לתהלים יט, ח סק\"ד.</p>\n<p><b>ושלימה: </b>ראה רמב\"ם הל' קדוה\"ח פ\"ח ה\"ו.</p>\n<p><b>ע\"י העבודה... קבעומ\"ש: </b>ד\"ה אתם נצבים, תרע\"ה.</p>\n<p><b>נצבים וקיימים ומאירים: </b>ראה תנחומא פ' נצבים.</p>"],[1200970303,"ח'תתקעג\n\n<p>ב\"ה, ג' אייר תשכ\"ה</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' מו\"ה חיים ישראל שי'</p>\n<p>שלום וברכה!</p>\n<p>...להערתו דלפי' התוס' ונת' ביש\"ש (ב\"ק פ', סע\"א) בטעם שלום זכר צ\"ל כן גם בלידת נקבה, י\"ל דשאני נקבה דאז אין השמחה שלימה ע\"פ ב\"ב (טז, ב).</p>\n<h4><i><b>ח'תתקעג</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ב ע' 233 והושלמה עפ\"י העתק המזכירות.</p>"]]});
